local GameCalls = (function()
-- Every native call the mod makes into the game is stated under src/game: the
-- ABI of each function called and how its arguments are packed. A caller
-- hands over the address it proved; nothing here finds or checks what the
-- function is. Every function is fetched through `process.fn`, which refuses
-- a target that is not executable when it first fetches it and keeps the
-- function after that. No calls file casts a target address or copies to a
-- game address itself (tests/test_game_calls_boundary.py).
--
-- This file holds the calls the foundation makes; a part with calls of its
-- own has a file of its own beside this one (grid_calls.lua, armory_calls.lua,
-- render_calls.lua). Each set is made over the process it is handed and
-- returns the table its feature module calls its `backend` or its `api`, so a
-- test can still put a fake in its place.
local M={}
-- The three game functions DiverKit resolves and the loadout bridge calls
-- through it (set armor, commit, refresh). The bridge refuses a function
-- DiverKit holds under another type.
M.DIVERKIT={
 armor='void (*)(void *, uint32_t, uint32_t)',
 commit='void (*)(void *)',
 refresh='void (*)(void *, void *, bool, bool)',
}
-- The game's string lookup: a 32-bit key in, text out.
local LOOKUP='const char *(*)(uint32_t)'
function M.localization(process)
 return {
  -- Committed, executable and part of a loaded module.
  executable=function(at)return process.executable(at,true)end,
  lookup=function(at,key)return process.address(process.fn(LOOKUP,at)(key))end,
 }
end
return M

end)()
local GameGridCalls = (function()
-- The equipment grid's native calls: the ABI of each game function the grid
-- calls and how its arguments are packed (see calls.lua). Every call is made
-- through the process the grid was handed: `process.fn` refuses a target that
-- is not executable memory when it first fetches it and keeps the function,
-- and the one word write goes through `process.write`, which refuses anything
-- but writable data. FFI here packs arguments; it casts no target address.
local ffi=require('ffi')
local Grid=GameGridLayout or error('module is not bundled: src.game.grid_layout')
local M={}
-- name -> C signature. The process parses each once, for the life of the
-- session: parsing a function signature consumes a LuaJIT C type slot for good.
M.ABI={
 text_string='void (*)(void*, uint32_t, const char*)',
 unary='void (*)(void*)',
 append='void (*)(void*, uint32_t, uint32_t, uint8_t, uint8_t)',
 commit='void (*)(void*, uint8_t)',
 deployment_commit='void (*)(void*, uint32_t, uint32_t)',
 detail='void (*)(void*, uint32_t, uint8_t)',
 detail_stats='uint8_t (*)(void*, uint32_t, uint32_t, void*)',
 detail_passive='void (*)(void*, uint32_t)',
 consume='void (*)(void*, uint64_t, float)',
 vector='void (*)(void*, uint64_t)',
 highlight='uint8_t (*)(void*, uint32_t)',
}
-- Text handed to a text control is borrowed by the game: each distinct string
-- is kept for the session.
local texts={}
-- The equipment grid's calls: list building, previews, focus, the commit and
-- the consumption of a menu input action.
function M.new(process)
 assert(type(process)=='table'and type(process.fn)=='function'and type(process.write)=='function'
  and type(process.executable)=='function','GameGridCalls.new: process required')
 local ABI,fn=M.ABI,process.fn
 -- The menu's Select action, as the 64-bit value the consume function takes.
 local SELECT=Grid.menu_actions[1]
 local action_values={[SELECT]=ffi.new('uint64_t',SELECT*4294967296)}
 local xy,packed=ffi.new('float[2]'),ffi.new('uint64_t[1]')
 local word=ffi.new('uint32_t[1]')
 return {executable=function(at)return process.executable(at)end,
  button_state=function(at,widget,state)
   fn(ABI.detail_passive,at)(ffi.cast('void*',widget),state);return true
  end,
  equipment_sound=function(at,grid,offer)
   fn(ABI.detail_passive,at)(ffi.cast('void*',grid),offer);return true
  end,
  text_template=function(at,widget,key)
   fn(ABI.detail_passive,at)(ffi.cast('void*',widget),key);return true
  end,
  text_string=function(at,widget,key,value)
   if not texts[value]then texts[value]=ffi.new('char[?]',#value+1,value)end
   fn(ABI.text_string,at)(ffi.cast('void*',widget),key,texts[value]);return true
  end,
  list_clear=function(at,grid)fn(ABI.unary,at)(ffi.cast('void*',grid));return true end,
  list_append=function(at,grid,offer,group,a,b)
   fn(ABI.append,at)(ffi.cast('void*',grid),offer,group,a,b);return true
  end,
  preview_notify=function(at,manager)fn(ABI.unary,at)(ffi.cast('void*',manager));return true end,
  preview_details=function(at,widget,offer,equipped)
   fn(ABI.detail,at)(ffi.cast('void*',widget),offer,equipped and 1 or 0);return true
  end,
  focus_row=function(at,row,column)
   fn(ABI.detail_passive,at)(ffi.cast('void*',row),column);return true
  end,
  detail_stats=function(at,widget,offer)
   return fn(ABI.detail_stats,at)(ffi.cast('void*',widget),offer,offer,nil)~=0
  end,
  detail_passive=function(at,widget,offer)
   fn(ABI.detail_passive,at)(ffi.cast('void*',widget),offer);return true
  end,
  list_finish=function(at,grid)fn(ABI.unary,at)(ffi.cast('void*',grid));return true end,
  write_armor=function(at,id)
