   return process.write(at,ffi.string(word,4))==true
  end,
  deployment_commit=function(at,profile,player,id)fn(ABI.deployment_commit,at)(ffi.cast('void*',profile),player,id);return true end,
  commit=function(at,owner)fn(ABI.commit,at)(ffi.cast('void*',owner),0);return true end,
  consume=function(at,input,action)
