   action_values[action]=action_values[action]or ffi.new('uint64_t',action*4294967296)
   fn(ABI.consume,at)(ffi.cast('void*',input),action_values[action],-1)
   return true
  end,
  position=function(at,widget,x,y)
   xy[0],xy[1]=x,y;ffi.copy(packed,xy,8)
   fn(ABI.vector,at)(ffi.cast('void*',widget),packed[0]);return true
  end,
  highlight=function(at,grid,offer)
   return fn(ABI.highlight,at)(ffi.cast('void*',grid),offer)~=0
  end,
  size=function(at,widget,w,h)
   xy[0],xy[1]=w,h;ffi.copy(packed,xy,8)
   fn(ABI.vector,at)(ffi.cast('void*',widget),packed[0]);return true
  end,
  stop=function(at,animation)
   fn(ABI.unary,at)(ffi.cast('void*',animation));return true
  end,
 }
end
return M

end)()
local GameRenderCalls = (function()
-- The render side's native calls and raw memory work: the ABI of each game
-- function the preview and model renderers call, and the few conversions
-- between engine handles, addresses and bytes they need (see calls.lua).
--
-- Every function takes the native api its caller was handed (ArmoryNative's
-- `api`), made over the process (armory_calls). A call and a write go through
-- it and nowhere else: it refuses a write to anything but writable data and a
-- call to anything but executable memory. An api without `fn` cannot call and
-- one without `write` cannot write; both say so. `api.ffi` is for conversions
-- and buffers of our own.
local M={}
-- name -> C signature of the game function of that name in render_symbols.
M.ABI={
 pool_acquire='void (*)(void *,void *)',
 pool_release='void (*)(void *,uint32_t)',
 actor_visibility='void (*)(uint32_t,uint8_t)',
 actor_ready='uint8_t (*)(void *,uint32_t)',
 actor_set_body='void (*)(void *,uint32_t,uint32_t)',
 actor_set_helmet='void (*)(void *,uint32_t,uint32_t,uint32_t,uint8_t)',
 render_world_submit='void (*)(void *,const void *,const void *,const void *,const void *,const void *,uint32_t,uint32_t)',
 render_world_update='void (*)(void *)',
 ui_render='void (*)(void *)',
 world_flush='void (*)(void *)',
}
-- The game function `name` at address `at`, callable.
function M.fn(api,name,at)
 local abi=assert(M.ABI[name],'no such native call: '..tostring(name))
 return assert(api.fn,'GameRenderCalls.fn: the api cannot call')(abi,at)
end
-- An address as the pointer argument a native call takes.
function M.pointer(api,address)return api.ffi.cast('void *',address)end
-- The address an engine handle (a boxed pointer or light userdata) holds.
function M.address(api,handle)
 return tonumber(api.ffi.cast('uintptr_t',api.ffi.cast('void *',handle)))
end
-- Writes `bytes` at `at`. True when written; false or nil when refused.
function M.write(api,at,bytes)
 return assert(api.write,'GameRenderCalls.write: the api cannot write')(at,bytes)==true
end
-- Writes one 32-bit value at `at`.
function M.write32(api,at,value)
 local write=assert(api.write,'GameRenderCalls.write32: the api cannot write')
 local word=api.ffi.new('uint32_t[1]',value)
 return write(at,api.ffi.string(word,4))==true
end
-- `size` zeroed bytes of our own that a native call may be handed a pointer
-- to; the caller keeps the returned buffer alive for as long as the game may.
function M.storage(api,size)return api.ffi.new('uint8_t[?]',size)end
-- Floats: a fixed array to decode a byte block into (`fill`), and a sized
-- array with the bytes it is in memory (`bytes`).
function M.floats(api,count)return api.ffi.new('float['..count..']')end
function M.float_array(api,count)return api.ffi.new('float[?]',count)end
function M.fill(api,target,bytes,size)api.ffi.copy(target,bytes,size)end
function M.bytes(api,array,size)return api.ffi.string(array,size)end
return M

end)()
local GameArmoryCalls = (function()
-- The Armory extras' native calls: the ABI of each game function the extras
-- call and how its arguments are packed (see calls.lua), and the native api
-- the extras and the render side are handed in the game.
--
-- The caller proved every address by its bytes (armory_symbols). Every call
-- and every write to game data goes through the api, which is made over the
-- process: it refuses a call target that is not executable memory and a write
-- that is not into writable data. FFI here packs arguments; it casts no
-- target address and copies to no game address.
local ffi=require('ffi')
local Layout=GameArmoryLayout or error('module is not bundled: src.game.armory_layout')
local Render=GameRenderLayout or error('module is not bundled: src.game.render_layout')
local M={}
-- name -> C signature of the game function of that name in armory_symbols.
M.ABI={
 create='void *(*)(int,int,int,void *)',
 allocate='void *(*)(void *,void *,uint64_t,uint64_t)',
 set_texture='void (*)(void *,uint32_t,void *)',
 set_uv='void (*)(void *,uint64_t,uint64_t)',
 set_size='void (*)(void *,uint64_t)',
 set_alpha='void (*)(void *,float)',
 material='void (*)(void *,uint64_t,uint8_t)',
 register_image='void (*)(void *,void *)',
 text_template='void (*)(void *,uint32_t)',
 text_param='void (*)(void *,uint32_t,const char *)',
 text_plain='void (*)(void *,const char *)',
 text_flush='void (*)(void *)',
 compare_pair='void (*)(void *,uint32_t,uint32_t)',
 show_model='void (*)(void *,uint8_t)',
}
-- The native api over the process layer: reads, an in-place comparison, the
-- module bases, a clock, writes that obey the layer's rule and calls it has
-- seen to be executable.
-- `ffi` is for the conversions of render_calls.
function M.api(process)
 return{ffi=ffi,read=process.read,same=process.same,module=process.module,now_ms=process.now_ms,
  write=process.store,fn=process.fn}
end
-- The calls, taking numeric addresses; `at` maps each name of M.ABI to the
-- address its caller proved. Strings handed to text_param are borrowed by the
-- game: the caller keeps them alive. An api that cannot call or cannot write
-- makes no calls: there is no other way to the game from here.
function M.new(api,at)
 assert(type(api)=='table'and type(api.fn)=='function'and type(api.write)=='function',
  'GameArmoryCalls.new: an api with fn and write required')
 local void=function(n)return ffi.cast('void *',n)end
 local c={}
 for name,abi in pairs(M.ABI)do
  c[name]=api.fn(abi,at[name])
 end
 local floats=ffi.new('float[4]');local packed=ffi.cast('uint64_t *',floats)
 local material_id=ffi.new('uint64_t',Layout.image_material.high)*0x100000000+Layout.image_material.low
 local diffuse=Render.material.diffuse
 local one=ffi.new('uint8_t[1]')
 return {
  upload=function(allocator,pixels,width,height)
   local out=ffi.new('void *[3]');c.allocate(void(allocator),out,#pixels,8)
   if out[0]==nil then return nil end
   -- Into the block the game's allocator just returned for these pixels,
   -- by the pointer it returned: ours until `create` takes it.
   ffi.copy(out[0],pixels,#pixels)
   local handle=c.create(width,height,0,out[0]);if handle==nil then return nil end
   return tonumber(ffi.cast('uintptr_t',handle))
  end,
  set_texture=function(element,texture)c.set_texture(void(element),diffuse,void(texture))end,
  set_uv=function(element,u0,v0,u1,v1)floats[0],floats[1],floats[2],floats[3]=u0,v0,u1,v1;c.set_uv(void(element),packed[0],packed[1])end,
  set_size=function(element,w,h)floats[0],floats[1]=w,h;c.set_size(void(element),packed[0])end,
  set_alpha=function(element,value)c.set_alpha(void(element),value)end,
  material=function(element)c.material(void(element),material_id,1)end,
  register_image=function(manager,element)c.register_image(void(manager),void(element))end,
  text_template=function(control,key)c.text_template(void(control),key)end,
  text_param=function(control,key,text)c.text_param(void(control),key,text)end,
  text_param_at=function(control,key,address)c.text_param(void(control),key,ffi.cast('const char *',address))end,
  text_plain=function(control,text)c.text_plain(void(control),text)end,
  text_flush=function(control)c.text_flush(void(control))end,
  compare_pair=function(compare,left,right)c.compare_pair(void(compare),left,right)end,
  show_model=function(model)c.show_model(void(model),0)end,
  -- One byte of game data. True when written; false or nil when refused.
  byte=function(address,value)
   one[0]=value
   return api.write(address,ffi.string(one,1))==true
  end,
  cstring=function(text)return ffi.new('char[?]',#text+1,text)end,
  same_pointer=function(address,buffer)return address==tonumber(ffi.cast('uintptr_t',buffer))end,
 }
end
return M

end)()
local GamePackageLayout = (function()
-- The game's package lease table, as the lease functions of package_symbols
-- read and write it: an open-addressed table of 64-bit package ids and their
-- reference counts, stored in the object the `package_leases` global points to.
-- Facts about the game's data; nothing outside src/game states them.
local M={}
-- The table object. `storage` points at its rows, which this build keeps
-- inside the object at `rows`; `capacity` rows of `row` bytes each; `empty` is
-- the id of a free row; `factor` multiplies an id into its first row. The
-- allocator pointer after the rows tells one table from the next: the game
-- makes the table again when it resets what it holds.
M.leases={storage=0,capacity=8,empty=16,factor=24,rows=32,header=32,row=16,
 capacity_value=1024,factor_value=2,allocator=16416}
-- A row: the package id, then how many leases hold it (64 bits; the high word
-- is zero for any count the game can reach).
M.lease={id=0,count=8,count_high=12,id_size=8}
-- Beyond this a count is not one: the row is not what it is taken for.
M.max_count=1000000
-- Rows kept free for the game itself: a lease of ours is refused when taking
-- it would make a new row with fewer than this many left.
M.reserve=16
return M

end)()
local GamePackageSymbols = (function()
-- The game's package leases, for one named game build: the two functions that
-- take and give back a lease, with the instruction bytes that must be found
-- there, and the global that holds the lease table. Facts about the game's
-- binary; nothing outside src/game states them.
--
-- The format is render_symbols': module ('game' is game.dll), rva counted from
-- the module's base, bytes compared whole before the address is trusted. An
-- entry without bytes is a global holding a pointer to the object named.
local M={}
-- Every address below is for this game build and no other (research/105,
-- research/128).
M.build='26251122'

-- acquire(lease table, ids, count): for each 64-bit package id, the id's row
-- of the table is counted up, or made with a count of one, and a package whose
-- count became one is asked of the engine (its package load). The bytes are
-- the whole function, the path for a row that already exists included.
M.package_acquire={module='game',rva=0x11912f0,bytes=''}
-- release(lease table, ids, count): the row is counted down, and a package
-- whose count became zero is taken out of the table and given back to the
-- engine (its package unload). An id without a row is skipped.
M.package_release={module='game',rva=0x1191480,bytes=''}
-- The lease table itself (package_layout: leases).
M.package_leases={module='game',rva=0x2e381e8}

-- Leasing stands or falls as one capability.
for _,symbol in pairs(M)do if type(symbol)=='table'and symbol.module then symbol.capability='packages'end end
return M

end)()
local GamePackageCalls = (function()
-- The game's package leases as a port: the ABI of the two lease functions,
-- how their arguments are packed (see calls.lua), and the reading of the
-- lease table that checks every call before and after.
--
-- A package is a bundle of the game's data, named by a 64-bit id (sixteen hex
-- digits, as the bundle's file is named). The game loads a package while at
-- least one lease holds it and unloads it when the last is given back; its own
-- armor code goes through the same table, so a lease taken here is counted
-- with the game's and never unloads what the game still holds.
--
-- The caller proved every address by its bytes (package_symbols); `resolve` is
-- the game contract's answer for a symbol. Every read and call goes through
-- the process. Nothing is written to game data from here: the table changes
-- only inside the game's own two functions.
local ffi=require('ffi')
local Layout=GamePackageLayout or error('module is not bundled: src.game.package_layout')
local Symbols=GamePackageSymbols or error('module is not bundled: src.game.package_symbols')
local M={}
-- name -> C signature of the game function of that name in package_symbols.
M.ABI={
 package_acquire='void (*)(void *,const uint64_t *,uint32_t)',
 package_release='void (*)(void *,const uint64_t *,uint32_t)',
}
M.symbols=Symbols
local Leases,Lease=Layout.leases,Layout.lease
local ZERO=string.rep('\0',Lease.id_size)
local function u32(s,o)local a,b,c,d=s:byte(o+1,o+4);return a+b*256+c*65536+d*16777216 end
local function pointer(s,o)
 local lo,hi=u32(s,o),u32(s,o+4)
 if hi>=32768 then return nil end
 local n=lo+hi*4294967296;return n>=65536 and n or nil
end
-- A package id as the game holds it in memory: the hex name, low byte first.
local function packed(id)
 if type(id)~='string'or #id~=Lease.id_size*2 or id:find('[^0-9a-f]')then return nil end
 local out={}
 for i=Lease.id_size,1,-1 do out[#out+1]=string.char(tonumber(id:sub(i*2-1,i*2),16))end
 return table.concat(out)
end
M.packed=packed
-- process: the process layer. resolve(name) -> address | nil, reason.
-- Returns the port, or nil and why the game is not one it can lease in.
function M.new(process,resolve)
 assert(type(process)=='table'and type(process.read)=='function'and type(process.fn)=='function','process required')
 assert(type(resolve)=='function','symbol resolver required')
 local at={}
 for name in pairs(M.ABI)do
  local found,why=resolve(name)
  if not found then return nil,name..' '..tostring(why)end
  at[name]=found
 end
 local global,why=resolve('package_leases')
 if not global then return nil,'package_leases '..tostring(why)end
 local code={}
 for name in pairs(M.ABI)do
  code[name]=(Symbols[name].bytes:gsub('%x%x',function(pair)return string.char(tonumber(pair,16))end))
