-- Injectable file operations keep failure handling and platform selection
-- testable without touching a player's files. No tailing, line or byte limits.
function M.export(loader,metadata,host)
 local output,input,path,platform
 local ok,result=pcall(function()
  host=host or M.native()
  local directory=loader and loader.log_directory
  if not directory or directory==''then
   directory=join(assert(host.getenv('LOCALAPPDATA'),'Log directory unavailable'),'CowboyBingus/Helldivers2/Logs')
  end
  local names=host.list(directory);table.sort(names)
  local desktop=assert(M.desktop(host),'Desktop folder unavailable')
  platform=host.wine and'proton'or'windows'
  local base='HD2-Transmog-Logs-'..os.date('!%Y%m%d-%H%M%S')
  for suffix=0,999 do
   local candidate=join(desktop,base..(suffix>0 and'-'..suffix or'')..'.txt')
   local why;output,why=host.open(candidate,true)
   if output then path=candidate;break end
   assert(why==80 or why==183,'Cannot write to Desktop: '..tostring(why))
  end
  assert(output,'No free report filename')
  local function write(text)assert(output:write(text),'Report write failed')end
  write('HD2 Transmog support report\nUTC: '..os.date('!%Y-%m-%dT%H:%M:%SZ')..'\nDesktop: '..desktop..' ('..platform
   ..(host.wine_evidence and', '..host.wine_evidence or'')..')\n'..(metadata or'')
   ..'\nAll available .log files, including retained sessions. Each file is copied to its size at export time.\n')
  local copied,missing=0,0
  -- The open file, whole or up to limit bytes, between its two marks.
  local function copy(name,limit)
   local size=input:size();local remaining=math.min(size,limit or size)
   while remaining>0 do
    local chunk=input:read(math.min(remaining,65536))
    assert(chunk and #chunk>0,'Log changed or could not be read: '..name)
    remaining=remaining-#chunk
    if remaining==0 and limit and size>limit then chunk=whole(chunk)end
    write(chunk)
   end
   assert(input:close(),'Log close failed');input=nil
   if limit and size>limit then write('\n[TRUNCATED after '..limit..' bytes]')end
   write('\n===== END '..name..' =====\n')
  end
  for _,name in ipairs(names)do
   if name:lower():match('%.log$')and not name:find('[/\\%z]')then
    write('\n===== '..name..' =====\n')
    local why;input,why=host.open(join(directory,name),false)
    if not input then missing=missing+1;write('[UNAVAILABLE: '..tostring(why)..']\n')
    else copy(name);copied=copied+1 end
   end
  end
  assert(copied>0,'No readable logs found')
  -- A state file that is not there is named as missing: a session that never
  -- reached its first second wrote none. One that cannot be opened, or opens
  -- and cannot be read through, is said so in its place. The logs are the
  -- report, and a state file never costs them or counts among them.
  for _,name in ipairs(M.STATE_FILES)do
   local why;input,why=host.open(join(directory,'../Transmog/'..name),false)
   if not input then
    if why==2 or why==3 then write('\n[MISSING: '..name..']\n')
    else write('\n[UNAVAILABLE: '..name..': '..tostring(why)..']\n')end
   else
    write('\n===== '..name..' =====\n')
    if not pcall(copy,name)then
     if input then pcall(input.close,input);input=nil end
     write('\n[UNAVAILABLE]\n===== END '..name..' =====\n')
    end
   end
  end
  -- The save files: name, size and first line of each, then whole copies of
  -- transmog.state, every <word>-v<digit>*.state (the stores of each schema,
