  local directory=loader and loader.log_directory
  if type(directory)~='string' or #directory==0 then
   -- MDL's loader shim omits log_directory; use the same conventional location.
   local local_app=os.getenv('LOCALAPPDATA')
   assert(type(local_app)=='string' and #local_app>0,'log directory unavailable')
   directory=local_app..'/CowboyBingus/Helldivers2/Logs'
