  elseif #block.order>=M.PROBLEMS then block.dropped=block.dropped+1;self.problem_news=self.problem_news+1
  else
   e={key=k,value=v,seq=seq,first=utc,last=utc,count=1};entries[text]=e;block.order[#block.order+1]=e
   self.problem_news=self.problem_news+1
  end
  self.problem_version=self.problem_version+1
  return true
 end
 local function write_line(key,value,noted)
  if not file or limited then return end
  sequence=sequence+1
  local utc=os.time()
  local line=render(key)..'='..render(value)..' [seq='..sequence..' utc='..utc..']\n'
  if bytes+#line>8*1024*1024 then line='log.limit=8 MiB session limit reached\n';limited=true end
  file:write(line);bytes=bytes+#line
  if stamp and utc>stamp then flushes=math.min(M.FLUSH_BURST,flushes+(utc-stamp)*M.FLUSH_RATE)end
  stamp=utc
