  elseif noted then file:flush();self.unflushed=0
  else self.unflushed=self.unflushed+1 end
 end
 function self:report(key,value)
  local ok,noted=pcall(note,key,value,file and not limited and sequence+1 or nil)
  pcall(write_line,key,value,ok and noted)
 end
 -- Two blocks, no trailing newline:
 --   Shown to the player: <n> | none
 --   <first UTC> x<count> seq=<seq> notice=<text>
 --   Problems this session: <n> distinct | none
 --   <first UTC> x<count> seq=<seq> <key>=<value>
 -- each followed by `... and <n> more` when entries were not kept. `seq=` is
 -- left out for a line that was not written to the file.
 local function render_block(out,block)
  for i=1,#block.order do
   local e=block.order[i]
   out[#out+1]=os.date('!%Y-%m-%dT%H:%M:%SZ',e.first)..' x'..e.count..(e.seq and' seq='..e.seq or'')..' '
    ..e.key..'='..e.value:sub(1,M.PROBLEM_VALUE)
