 end
 function self:problems()
  local ok,text=pcall(function()
   local out={'Shown to the player: '..(#shown.order>0 and #shown.order or'none')}
   render_block(out,shown)
   out[#out+1]='Problems this session: '..(#failed.order>0 and #failed.order..' distinct'or'none')
   render_block(out,failed)
   return table.concat(out,'\n')
  end)
