 return raw
end
function M.decode(S,raw)
 if raw==OFF then return false end
 if type(raw)~='string'or #raw>4096 then return nil,'invalid equipped record'end
 local registered_id,payload,logical,last_native
 if raw:sub(1,#LOGICAL_HEADER)==LOGICAL_HEADER then
  registered_id,last_native,payload=raw:sub(#LOGICAL_HEADER+1):match('^([^\n]+)\n([^\n]+)\n(.*)$')
  if registered_id=='-'then registered_id=nil
  elseif not clothing_id(registered_id)then return nil,'invalid clothing identity'end
  if last_native=='-'then last_native=nil
  elseif not native_id(last_native)then return nil,'invalid native provenance'end
  logical=true
 elseif raw:sub(1,#CLOTHING_HEADER)==CLOTHING_HEADER then
  registered_id,payload=raw:sub(#CLOTHING_HEADER+1):match('^([^\n]+)\n(.*)$')
  if not clothing_id(registered_id)then return nil,'invalid clothing identity'end
 elseif raw:sub(1,#HEADER)==HEADER then payload=raw:sub(#HEADER+1)
 else return nil,'invalid equipped record'end
 local state,why=S.decode(payload);if not state then return nil,why end
 if next(state.catalog)or next(state.owned)then return nil,'equipped record contains catalog data'end
 local label,request=next(state.presets)
 if not label or next(state.presets,label)or not same(request,state.requested)
  or (logical and not logical_uuid(request.appearance_id))
  or (not logical and not native_id(request.appearance_id))then return nil,'invalid equipped variant'end
 return {label=label,request=request,target_id=not logical and request.appearance_id or nil,
  logical_id=logical and request.appearance_id or nil,clothing_id=registered_id,id=request.id,
  last_native_id=last_native,
  version=state.decoded_version}
end
-- Logical intent never caches or persists a carrier. The host resolves a fresh
-- native target only after it has established the current binding.
function M.resolve_target(record,context)
 if not record then return nil end
 if not record.logical_id then return native_id(record.target_id)and record.target_id or nil end
 context=context or{}
 local item=(context.logical_clothing or{})[record.logical_id]
 if not(item and item.uuid==logical_uuid(record.logical_id))then return nil end
 if type(context.logical_target)~='function'then return nil end
