  registered=(context.logical_clothing or{})[record.logical_id]
  if not(registered and registered.uuid==logical_uuid(record.logical_id))then return false end
 else registered=(context.registered_clothing or {})[record.target_id]end
 if record.clothing_id and not(registered and registered.id==record.clothing_id)then return false end
