 -- What is restored and selected again is asked for by label: the one the
 -- variant has today.
 if request then record.label=label end
 if not request and registered and type(registered.id)=='string'and record.label=='@clothing/'..registered.id then
  request=(context.clothing_presets or {})[record.label]
