 return same(request,record.request)
end
function M.matches(record,domain,armor,context)
 local target=M.resolve_target(record,context)
 return target~=nil and target==armor and M.definition_matches(record,domain,context)or false
end
-- The game's stock B-01 can replace an experimental reserved item at login.
-- This exception requires a current registered clothing identity and an intact
-- saved definition; it never authorizes replay over an arbitrary ordinary look.
function M.startup_matches(record,domain,armor,context)
 if not M.definition_matches(record,domain,context)then return false end
 local target=M.resolve_target(record,context)
 if not target then return false end
 if target==armor then return true end
 -- Yesterday's bound record is only a startup guard. It never selects the
 -- garment or substitutes for today's freshly resolved target.
 if record.logical_id and record.last_native_id==armor then return true end
 local registered=context and (record.logical_id and(context.logical_clothing or{})[record.logical_id]
  or(context.registered_clothing or {})[record.target_id])
 local login=({[Category.armor]=Login.armor,[Category.helmet]=Login.helmet,[Category.cape]=Login.cape})[context and context.category or Category.armor]
 local fallback=login and'armor:'..login
 return registered~=nil and armor==fallback
end
function M.new(fs,S,report,filename)
 filename=filename or 'equipped.state'
 assert(filename=='equipped.state'or filename=='equipped-helmet.state'or filename=='equipped-cape.state','invalid equipment slot file')
 report=report or function()end
 -- A record of an older version is kept aside before it is first replaced.
 local writer=S.writer(fs,filename)
 local raw,reason=fs.read(filename)
 local prior_raw=raw
