  -- Preserve the exact current legacy bytes, including when a v1 backup
  -- already exists. A hash collision or failed verification refuses migration.
  if value:sub(1,#LOGICAL_HEADER)==LOGICAL_HEADER and prior_raw
   and prior_raw:sub(1,#LOGICAL_HEADER)~=LOGICAL_HEADER then
