   local base,extension=filename:match('^(.-)%.([^.]+)$')
   local aside=base..'-v'..version..'-'..S.label_id(prior_raw)..'.'..extension
   local have,error=fs.read(aside)
   if have and have~=prior_raw then return nil,'legacy equipped backup differs'end
   if not have then
