    local kept,err=fs.write_atomic(aside,prior_raw)
    if not kept then return nil,'legacy equipped backup failed: '..tostring(err)end
   end
   if fs.read(aside)~=prior_raw then return nil,'legacy equipped backup verification failed'end
  end
