end
local field_keys={name=true,bit=true,width=true,max=true,label=true,description=true,choices=true}
-- Display metadata for a host options menu. Optional, never packed: nothing here
-- reaches the 128-bit word, the wire format, `resolve` or the content hash.
local function display(f,max)
 assert(f.label==nil or(type(f.label)=='string'and #f.label>0 and #f.label<=40),'toggle label must be 1..40 characters')
 assert(f.description==nil or(type(f.description)=='string'and #f.description>0 and #f.description<=400),'toggle description must be 1..400 characters')
 if f.choices==nil then return nil end
 local list=f.choices
 assert(plain(list),'toggle choices must be plain data')
 local n=0
 for k in pairs(list)do
  assert(type(k)=='number'and k%1==0 and k>=1 and k<=max+1,'bounded dense toggle choices required');n=n+1
 end
 assert(#list==n and n==max+1,'toggle choices must name every value 0..'..max)
 local out={}
 for i=1,n do
  local name=list[i]
  assert(type(name)=='string'and #name>0 and #name<=48,'toggle choice name must be 1..48 characters')
  out[i]=name
 end
 return out
end
-- Declared fields must not overlap, must fit in 128 bits, width 1..32, and each
-- value must be <= max, defaulting to 2^width-1.
function M.schema(toggles)
 local ok,value=pcall(function()
  local list=toggles
  if list==nil then list={}end
  assert(plain(list),'toggle schema must be plain data')
  local n=0
  for k in pairs(list)do
   assert(type(k)=='number'and k%1==0 and k>=1 and k<=M.MAX_FIELDS,'bounded dense toggle schema required');n=n+1
  end
  assert(#list==n,'bounded dense toggle schema required')
  local used,names,out={},{},{}
  for i=1,n do
   local f=list[i]
   assert(plain(f),'toggle field must be plain data')
   for key in pairs(f)do
    assert(field_keys[key],'unknown toggle field: '..tostring(key))
   end
   assert(type(f.name)=='string'and #f.name>0 and #f.name<=32 and f.name:match('^[a-z][a-z0-9_]*$'),'toggle name required')
   assert(not names[f.name],'duplicate toggle name: '..f.name);names[f.name]=true
   assert(type(f.bit)=='number'and f.bit%1==0 and f.bit>=0 and f.bit<M.BITS,'toggle bit out of range')
   assert(type(f.width)=='number'and f.width%1==0 and f.width>=1 and f.width<=32,'toggle width must be 1..32')
   assert(f.bit+f.width<=M.BITS,'toggle field exceeds the 128-bit space')
   local limit=pow[f.width]-1
   local max=f.max;if max==nil then max=limit end
   assert(type(max)=='number'and max%1==0 and max>=0 and max<=limit,'toggle max exceeds its declared width')
   for b=f.bit,f.bit+f.width-1 do
    assert(not used[b],'toggle fields overlap at bit '..b);used[b]=true
   end
   out[i]={name=f.name,bit=f.bit,width=f.width,max=max,label=f.label,description=f.description,choices=display(f,max)}
  end
