 end)
 if not ok then return nil,reason(value)end
 return value
end
local function locate(schema,name)
 for i=1,#schema do if schema[i].name==name then return schema[i]end end
end
function M.names(schema)
 local out={};for _,f in ipairs(schema)do out[#out+1]=f.name end;table.sort(out);return out
end
function M.defaults(schema)
 local out={};for _,f in ipairs(schema)do out[f.name]=0 end;return out
end
function M.pack(schema,values)
 local ok,value=pcall(function()
  assert(type(schema)=='table','toggle schema required')
  local given=values;if given==nil then given={}end
  assert(plain(given),'toggle values must be plain data')
  local v={0,0,0,0};local count=0
  for name,raw in pairs(given)do
   count=count+1;assert(count<=M.MAX_FIELDS,'too many toggle values')
   local f=locate(schema,name);assert(f,'undeclared toggle: '..tostring(name))
   assert(type(raw)=='number'and raw%1==0 and raw>=0,'toggle '..f.name..' must be a non-negative integer')
   assert(raw<=f.max,'toggle '..f.name..' exceeds its declared maximum')
