end
-- Undeclared bits are ignored and never surface to the pack.
function M.unpack(schema,v)
 local ok,value=pcall(function()
  assert(type(schema)=='table','toggle schema required')
  assert(M.limbs(v),'toggle word required')
  local out={}
  for _,f in ipairs(schema)do
   local i=math.floor(f.bit/32)+1;local o=f.bit%32
   local take=math.min(f.width,32-o)
   local raw=math.floor(v[i]/pow[o])%pow[take]
   if f.width>take then raw=raw+(v[i+1]%pow[f.width-take])*pow[take]end
   assert(raw<=f.max,'toggle '..f.name..' exceeds its declared maximum')
   out[f.name]=raw
  end
