end)()
local ClothingLook = (function()
-- A declared look: a piece's `resolve` given as data. The whole of it is
-- checked here against the closure the piece declares, every value of every
-- group, so nothing is left to be found at the first selection; what comes
-- back evaluates a selection without running any pack code. Pure data: this
-- module asks the game for nothing.
local M={MAX_EFFECTS=256,MAX_MATERIALS=64}
local bodies={[0]='muscle',[1]='lean'}
local parts={units=true,remaps=true,materials=true,template=true}
local function plain(t)
 assert(type(t)=='table'and getmetatable(t)==nil,'plain data table required');return t
end
local function fields(t,allowed)
 plain(t);for key in pairs(t)do assert(allowed[key],'unknown clothing field: '..tostring(key))end
end
local function reason_of(value)return(tostring(value):gsub('^.-%.lua:%d+: ',''))end
-- The length of a dense array of 1..max members; nil for anything else.
local function dense(t,max)
 if type(t)~='table'or getmetatable(t)~=nil then return nil end
 local n=0
 for k in pairs(t)do
  if type(k)~='number'or k%1~=0 or k<1 or k>max then return nil end
  n=n+1
 end
 if n==0 then return nil end
 for i=1,n do if t[i]==nil then return nil end end
 return n
end
local function flat(t)
 if t==nil or next(t)==nil then return nil end
 local r={};for k,v in pairs(t)do r[k]=v end;return r
end
-- item: a manifest piece whose bodies and binding the registry has checked.
-- schema: Identity.schema(item.toggles). Returns function(selection), where
-- selection is {body=0|1,toggles={name=value}}, or nil and the reason.
function M.compile(program,item,schema)
 local ok,value=pcall(function()
  fields(program,{base=true,groups=true})
  local binding=item.binding
  local declared=binding and binding.remaps
  -- A unit's hash is the one its remap entries give its path. A path
  -- declared under two hashes has no one hash, and a swap of such a unit
  -- would leave the remaps that name the other hash on the old unit.
  local hash_of,forked,targets={},{},{}
  for _,entry in pairs(declared or{})do
   targets[entry.hash]=true
   local first=hash_of[entry.path]
   if first==nil then hash_of[entry.path]=entry.hash elseif first~=entry.hash then forked[entry.path]=true end
  end
  local alternatives=binding and binding.materials or{}
  local templates={}
  if binding then
   templates[binding.template]=true
   for _,template in ipairs(binding.templates or{})do templates[template]=true end
  end
  -- Every key any value of any group can bind is counted once: no selection
  -- can then reach more than the bound.
  local keys,key_count={},0
  -- What the base and an effect say the same way.
  local function overlay(part)
   if part.remaps~=nil then
    assert(declared,'declared remap is outside the declared asset closure')
    for old,hash in pairs(plain(part.remaps))do
     assert(declared[old]and type(hash)=='string'and targets[hash],'declared remap is outside the declared asset closure')
    end
   end
   if part.materials~=nil then
    for packaged,alternative in pairs(plain(part.materials))do
     assert(type(packaged)=='string'and #packaged==16 and packaged:match('^[0-9a-f]+$')and alternatives[alternative],
      'declared material is outside the declared asset closure')
     if not keys[packaged]then
      keys[packaged]=true;key_count=key_count+1
      assert(key_count<=M.MAX_MATERIALS,'a look binds at most 64 materials')
     end
    end
   end
   assert(part.template==nil or templates[part.template],'declared template is outside the declared asset closure')
  end
  local base=program.base
  if base==nil then base={}end
  fields(base,parts);overlay(base)
  local start={}      -- body -> the units shown with every toggle at 0
  for name,body in pairs(item.bodies)do start[name]=body.units end
  if base.units~=nil then
   local outside='base unit is outside the declared asset closure'
   for name,list in pairs(plain(base.units))do
    local body=item.bodies[name];assert(body,outside)
    assert(dense(list,#body.units),outside)
    local allowed,seen={},{}
    for _,unit in ipairs(body.units)do allowed[unit]=true end
    for _,unit in ipairs(list)do assert(allowed[unit]and not seen[unit],outside);seen[unit]=true end
    start[name]=list
   end
  end
  local place={}      -- body -> unit -> its position in the base list
  for name,list in pairs(start)do
   local own,at={},{}
   for i,unit in ipairs(list)do own[i]=unit;at[unit]=i end
   start[name]=own;place[name]=at
  end
  local by_name={};for _,field in ipairs(schema)do by_name[field.name]=field end
  local groups=program.groups
  if groups==nil then groups={}end
  plain(groups)
  local swap='unit swap is outside the declared asset closure'
  local swapper={}    -- shown unit -> the one group that swaps it
  local source={}     -- body -> swapped-in unit -> the one unit it stands in for
  for name in pairs(item.bodies)do source[name]={}end
  local stands_in={}  -- every unit a swap puts in, in whichever body
  local steps={}      -- group -> value+1 -> what that value does, as this module's own data
  for name,group in pairs(groups)do
   local field=by_name[name];assert(field,'declared look names an undeclared toggle')
   assert(field.max<M.MAX_EFFECTS,'a group needs a toggle of at most 256 values')
   assert(dense(group,field.max+1)==field.max+1,'a group names every value of its toggle')
   steps[name]={}
   for index=1,field.max+1 do
    local effect=group[index]
    assert(type(effect)=='table','a group names every value of its toggle')
    fields(effect,parts);overlay(effect)
    -- A swap is settled per body here: it acts where the base shows the
    -- unit, and what stands in is a unit of that body no other can become.
    -- No unit is both swapped in and swapped out, in any body: a unit a
    -- swap put in the list is then never the `shown` of another, so "where
    -- the base shows it" and "where the list shows it" are one rule.
    -- The remaps are not per body: the record is composed from one set for
    -- every body, and bodies that answer differently are refused there. So
    -- what a swap retargets is gathered over all bodies and applied in each.
    local moves,retargets={},{}
    if effect.units~=nil then
     for shown,instead in pairs(plain(effect.units))do
      assert(swapper[shown]==nil or swapper[shown]==name,swap);swapper[shown]=name
      assert(not stands_in[shown],swap)
      local held=false
      for body_name,body in pairs(item.bodies)do
       local at=place[body_name][shown]
       if at then
        held=true
        local known=false
        for _,unit in ipairs(body.units)do if unit==instead then known=true end end
        assert(known and not place[body_name][instead]and swapper[instead]==nil,swap);stands_in[instead]=true
        local taken=source[body_name]
        assert(taken[instead]==nil or taken[instead]==shown,swap);taken[instead]=shown
        if binding then
         local from,to=hash_of[shown],hash_of[instead]
         assert(from and to,'a swapped unit needs a remap entry')
         assert(not forked[shown]and not forked[instead],'a swapped unit needs one remap entry')
         retargets[from]=to
        end
        local list=moves[body_name]
        if not list then list={};moves[body_name]=list end
        list[#list+1]={at=at,unit=instead}
       end
      end
      assert(held,swap)
     end
    end
    steps[name][index]={moves=moves,retargets=flat(retargets),remaps=flat(effect.remaps),materials=flat(effect.materials),
     template=effect.template}
   end
  end
  local order={}      -- the groups in the order their toggles are declared
  for _,field in ipairs(schema)do if steps[field.name]then order[#order+1]=field.name end end
  local base_remaps,base_materials,base_template=flat(base.remaps),flat(base.materials),base.template
  return function(selection)
   local body=bodies[selection.body]
   local first=start[body];if not first then return nil end
   local units={};for i=1,#first do units[i]=first[i]end
   local remaps,materials,template=nil,nil,base_template
   if binding then
    remaps={}
    if base_remaps then for old,hash in pairs(base_remaps)do remaps[old]=hash end end
   end
   if base_materials then materials={};for packaged,alternative in pairs(base_materials)do materials[packaged]=alternative end end
   local values=selection.toggles
   for _,name in ipairs(order)do
    local step=steps[name][(values and values[name]or 0)+1]
    if step then
     local moves=step.moves[body]
     if moves then for _,move in ipairs(moves)do units[move.at]=move.unit end end
     if step.retargets then
      for old,hash in pairs(remaps)do local to=step.retargets[hash];if to then remaps[old]=to end end
     end
     if step.remaps then for old,hash in pairs(step.remaps)do remaps[old]=hash end end
     if step.materials then
      materials=materials or{}
      for packaged,alternative in pairs(step.materials)do materials[packaged]=alternative end
     end
     if step.template~=nil then template=step.template end
    end
   end
   return{units=units,remaps=remaps,template=template,materials=materials}
  end
 end)
 if not ok then return nil,reason_of(value)end
 return value
end
return M

end)()
local IdString = (function()
-- The engine's identifier hashes.
--
-- A resource, unit or setting name is stored as murmur64A of its text with
-- seed 0 (IdString64, shown by the engine as `#ID[...]`); the short form used
-- for viewport templates, render resources and shading settings (IdString32)
-- is the upper 32 bits of the same hash. Confirmed against the running game
-- on 2026-10-02 (research/114): `default`, `overlay` and `ui_3d` are keys of
-- the viewport template table, and a registered clothing unit path hashes to
-- the id of the unit the game spawned for it.
--
-- 64-bit values are uint64_t cdata. Only multiplication, division and
-- remainder are done on them; exclusive-or goes through 32-bit halves, so
-- nothing depends on 64-bit support in the `bit` library.
local M={}
local ffi=require('ffi')
local bxor=require('bit').bxor
local MULTIPLIER=0xc6a4a7935bd1e995ULL
local HALF=0x100000000ULL
local SHIFT47=0x800000000000ULL
local function xor(a,b)
 local high=bxor(tonumber(a/HALF),tonumber(b/HALF))
 local low=bxor(tonumber(a%HALF),tonumber(b%HALF))
 if high<0 then high=high+4294967296 end
 if low<0 then low=low+4294967296 end
 return ffi.new('uint64_t',high)*HALF+low
end
-- murmur64A(text, seed 0) as uint64_t cdata.
function M.hash(text)
 assert(type(text)=='string','identifier text required')
 local length=#text
 local bytes=ffi.cast('const uint8_t *',text)
 local hash=ffi.new('uint64_t',length)*MULTIPLIER
