 MAX_LENGTH=512,MAX_REV=2147483647,FIELD_LENGTH=83}
local function reason(value)return(tostring(value):gsub('^.-%.lua:%d+: ',''))end
local function hex(s,n)return type(s)=='string'and #s==n and s:match('^[0-9a-f]+$')~=nil end
local function counter(n,floor)return type(n)=='number'and n%1==0 and n>=floor and n<=M.MAX_REV end
