 if text==nil or text==''then return{vanilla=true,absent=true,rev=0,lrev=0,body=0}end
 if type(text)~='string'then return nil,'malformed'end
 if #text>M.MAX_LENGTH then return nil,'oversized'end
 local version=text:match('^v(%d+)|')
 if not version then return nil,'malformed'end
 if version~='4'then return nil,'unsupported_version'end
 local parts,at={},1
 while true do
  local stop=text:find('|',at,true)
