      fields(spare,{carrier=true,package=true})
      assert(type(spare.carrier)=='string'and #spare.carrier==8 and spare.carrier:match('^[0-9a-f]+$'),'spare record identity required')
      assert(type(spare.package)=='string'and #spare.package==16 and spare.package:match('^[0-9a-f]+$'),'spare package identity required')
      assert(not seen_spares[spare.carrier],'duplicate spare record');seen_spares[spare.carrier]=true
