 local pieces,slots={},{}
 for _,body in ipairs(record.bodies)do if body.type==BodyType.any or body.type==body_type then
  for _,p in ipairs(body.pieces)do
   assert(#pieces<Catalog.collector_capacity,'native piece collection capacity exceeded')
   assert(p.slot>=Slot.helmet and p.slot<=Slot.right_shoulder and p.kind>=Kind.armor and p.kind<=Kind.accessory and p.weight>=Weight.light and p.weight<=Weight.heavy,'unsupported native piece fields')
