local function cut(s,from,to)return s:sub(from+1,to or -1)end
local function collect(record,kind)
 local out,order={},{}
 for _,body in ipairs(record.bodies)do if body.type==BodyType.any or body.type==kind then
  for _,piece in ipairs(body.pieces)do
   assert((piece.slot==Slot.helmet or piece.slot==Slot.cape) and piece.kind>=Kind.armor and piece.kind<=Kind.accessory and piece.weight>=Weight.light and piece.weight<=Weight.heavy,'unsupported helmet piece')
   local key=piece.slot..':'..piece.kind
   assert(not out[key],'ambiguous helmet piece')
   out[key]=piece;order[#order+1]=piece
  end
 end end
 assert(#order>0 and #order<=Catalog.collector_capacity,'helmet body pieces unavailable')
 return out,order
end
function M.compose(source,stats)
 assert(source.category==stats.category and (source.category==Category.helmet or source.category==Category.cape),'matching accessory category required')
 local out={bodies={},appearance_topology_preserved=true,slot_weights_preserved=true,base_weight_sequence_preserved=true}
 for _,kind in ipairs({BodyType.muscle,BodyType.lean})do
  local look,order=collect(source,kind);local donor=collect(stats,kind);local pieces={}
  for key in pairs(donor)do assert(look[key],'helmet stats topology differs')end
  for _,p in ipairs(order)do
   local d=assert(donor[p.slot..':'..p.kind],'helmet stats topology differs')
   pieces[#pieces+1]=cut(p.bytes,0,Piece.weight)..cut(d.bytes,Piece.weight,Piece.weight+4)..cut(p.bytes,Piece.weight+4)
  end
  out.bodies[#out.bodies+1]={type=kind,pieces=pieces}
