    local ok,counts=pcall(port.counts,ids)
    if ok and type(counts)=='table'then
     for _,id in ipairs(ids)do if counts[id]==0 then lose(id,'the game no longer counts the lease')end end
    end
   end
  end
  local lost
  if #gone>0 then lost=gone;gone={}end
  if in_use then for id,lease in pairs(held)do if in_use[id]then lease.used=now end end end
  -- One lease a pass: the game reads the package's files when it is asked.
  if next(asked)then
   local wanted=next_asked(now)
   if wanted then take(wanted,now)end
  end
