end
-- Whether an instance needs looking at though no row wants anything of it.
local function busy(inst)return not inst.failed and(inst.unread==true or carried(inst)>0)end
function M.new(opts)
 opts=opts or{}
 local source,report=opts.port,opts.report or function()end
 local self={}
 local owned,held={},{}  -- the owner's rows in its order; key -> a row held by someone else
 local order={}          -- every row: the owner's, then the held ones by key
 local groups,group_order={},{}  -- place -> {world=,hash=,map=,wanting=,ready=,ambiguous=,who=} of the rows that name a resource
 local places={}         -- every place a row names -> whether a row wants a material there
 local wanting=false     -- whether any row has a material choice
 -- {unit=,at=<place>,name=,packaged={{mesh=,index=,id=}},read={},sent={},keys={},tries={},asked={},
 --  whys={},settled=,unread=,failed=,check=,gave=}: an instance seen, what it was packaged with, what each
 -- position was last read as (`read`), which id the port took a bind of since that reading (`sent`), which
 -- id is being tried how often (`asked`, `tries`) and why the port did not bind it last (`whys`). `check`
 -- counts the readings a unit given up in pass `gave` is still owed.
 local known={}
 local blind={}          -- place -> a unit listed there in the last pass could not be read at first sight
 local pass=0            -- the working passes so far
 local told={ambiguous={},unavailable={},unbound={},unreadable={}}  -- what was reported and still holds
 local erred={}          -- the reasons a pass failed with, each said once
 local noted             -- row name -> why a unit of it could not be read, in the pass under way
