 local stalled=false     -- the last pass that was due had no port or failed: nothing known is current
 local function arrange()
  order={}
  for _,row in ipairs(owned)do order[#order+1]=row end
  local keys={};for key in pairs(held)do keys[#keys+1]=key end
  table.sort(keys);for _,key in ipairs(keys)do order[#order+1]=held[key]end
  groups,group_order,places,wanting={},{},{},false
  for _,row in ipairs(order)do
   wanting=wanting or row.wanting
   for place,hash in pairs(row.places)do
    places[place]=places[place]or row.wanting
    local group=groups[place]
    if row.handles then -- its units are its own
    elseif not group then
     groups[place]={world=row.world,hash=hash,map=row.materials,wanting=row.wanting,ready=row.ready,ambiguous=false,who=row.who}
     group_order[#group_order+1]=place
    else
