 local function held_back(row)
  local unavailable=row.wanting and not row.ready
  if not row.handles then
   for place in pairs(row.places)do
    local group=groups[place]
    if group.ambiguous then return'ambiguous'end
    if row.wanting and not group.ready then unavailable=true end
   end
  end
  return unavailable and'unavailable'or nil
 end
 -- Instances seen, positions bound and the state of one row.
 local function reading(row)
  local seen,bound,failed,pending=0,0,false,dirty or stalled
  for _,inst in ipairs(known)do
   if row.places[inst.at]then
    seen=seen+1;bound=bound+carried(inst)
    failed=failed or inst.failed==true;pending=pending or not inst.settled
   end
  end
  -- A row that names its units is not settled without every one of them, nor
  -- any row while a unit listed for it could not be read.
  if row.handles and seen<#row.handles then pending=true end
  for place in pairs(row.places)do if blind[place]then pending=true end end
  return seen,bound,failed and'failed'or held_back(row)or seen==0 and'no instance'or pending and'pending'or'settled'
