end
function M.format(status)
 local lines={'HD2TM_CLOTHING_MATERIALS 1','rows='..tostring(status.rows)..' instances='..tostring(status.instances)
  ..' bound='..tostring(status.bound)..' ambiguous='..tostring(status.ambiguous)..' failed='..tostring(status.failed)
  ..' unavailable='..tostring(status.unavailable)}
