 local template=b and assert(data.kits[tonumber(b.template,16)],'visual template missing from catalog')
 assert(not template or template.category==carrier.category,'binding category differs')
 local out=copy(carrier);out.bodies={}
 for body_type=BodyType.muscle,BodyType.lean do
  local weights=M.topology(carrier,body_type)
  local active=item~=nil and item.bodies[bodies_by_type[body_type]]~=nil
  local source=active and template or carrier
  local source_body=active and b.body_source or body_type
  if source_body==nil then source_body=body_type end
  local pieces,seen={},{}
  for _,body in ipairs(source.bodies)do if body.type==BodyType.any or body.type==source_body then
   for _,original in ipairs(body.pieces)do
    local piece=copy(original);local key=piece.slot..':'..piece.type
    local weight=piece_weight(weights,piece)
    assert(not seen[key]and weight~=nil,'unsupported fallback piece topology');seen[key]=true
    local raw=bytes(piece.raw)
