     for _,offset in ipairs(Piece.hashes)do
      local replacement=b.remaps[hex(raw:sub(offset+1,offset+8):reverse())]
      if replacement then raw=raw:sub(1,offset)..bytes(replacement.hash):reverse()..raw:sub(offset+9)end
     end
