    assert(#raw==Piece.size and u32(raw,Piece.slot)==piece.slot and u32(raw,Piece.kind)==piece.type,'unsupported fallback piece descriptor')
    piece.path=hex(cut(raw,Piece.path,Piece.path+8):reverse());piece.raw=hex(raw);piece.weight=weight
