-- A look never changes a carrier's stats: its stat-bearing pieces stay inside
-- the carrier's topology; additional native underlayers use a same-slot weight.
function M.check(reference,carrier)
 assert(reference.item_id==carrier.item_id and reference.package==carrier.package,'variant carrier identity differs')
 assert(#reference.bodies==2,'variant must describe both native profiles')
 for index,body in ipairs(reference.bodies)do
  assert(body.type==index-1,'unsupported variant body order')
  local weights=M.topology(carrier,body.type);local keys={}
  assert(#body.pieces>0 and #body.pieces<=Catalog.collector_capacity,'native body collector capacity exceeded')
  for _,piece in ipairs(body.pieces)do
   local key=piece.slot..':'..piece.type
   assert(not keys[key]and piece_weight(weights,piece)==piece.weight,'variant piece is outside the carrier topology');keys[key]=true
   local raw=bytes(piece.raw)
   assert(#raw==Piece.size and u32(raw,Piece.slot)==piece.slot and u32(raw,Piece.kind)==piece.type and u32(raw,Piece.weight)==piece.weight,
    'variant piece fields differ from the carrier topology')
