end
local function record_of(kit)
 local out={category=kit.category,bodies={}}
 for _,body in ipairs(kit.bodies)do
  local pieces={}
  for _,piece in ipairs(body.pieces)do
   pieces[#pieces+1]={bytes=bytes(piece.raw),slot=piece.slot,kind=piece.type,weight=piece.weight}
  end
  out.bodies[#out.bodies+1]={type=body.type,pieces=pieces}
