 local composed
 if kit.category==categories.armor then
  local uniform=ArmorLayout.uniform(stats)
  if uniform then
   composed={bodies={}}
   for _,body in ipairs(source.bodies)do
    local pieces={}
    for _,piece in ipairs(body.pieces)do
     pieces[#pieces+1]=piece.kind==Kind.armor and cut(piece.bytes,0,Piece.weight)..p32(uniform)..cut(piece.bytes,Piece.weight+4)or piece.bytes
    end
    composed.bodies[#composed.bodies+1]={type=body.type,pieces=pieces}
   end
  else composed=ArmorLayout.compose(source,stats)end
 else composed=HelmetLayout.compose(source,stats)end
