 for _,body in ipairs(composed.bodies)do
  local pieces={}
  for _,raw in ipairs(body.pieces)do
   assert(#raw==Piece.size,'composed piece descriptor size differs from the current layout')
   pieces[#pieces+1]={path=hex(cut(raw,Piece.path,Piece.path+8):reverse()),slot=u32(raw,Piece.slot),type=u32(raw,Piece.kind),weight=u32(raw,Piece.weight),raw=hex(raw)}
  end
  assert(#pieces>0 and #pieces<=Catalog.collector_capacity,'native body collector capacity exceeded')
