end
function M.ready(bridge)
 local ok,value=pcall(function()
  if not bridge.verify()then return false end
  local at=ptr(bridge.read(bridge.armor_catalog,8),0);if at<65536 then return false end
  local head=bridge.read(at+Object.entries,Array.head);local first,n=ptr(head,Array.pointer),u32(head,Array.count)
  return first>=65536 and n>0 and n<=Object.max_entries
