end
-- Everything a look needs from the pack, resolved inside its declared closure
-- for every body the piece declares.
local function variant_item(piece,values,resolve)
 local native=piece.binding
 local paths={}
 for _,entry in pairs(native.remaps or{})do paths[entry.hash]=entry.path end
 local item={id=piece.id,name=piece.name,slot=piece.slot,bodies={},
  binding={carrier=native.carrier,template=native.template,package=native.package,body_source=native.body_source,remaps={}}}
 local selected_template
 for body_type=BodyType.muscle,BodyType.lean do
  local name=bodies_by_type[body_type]
  if piece.bodies[name]then
   local resolved,why=resolve(piece.uuid,{body=body_type,toggles=values})
   assert(resolved,why)
   assert(type(resolved.units)=='table','resolved descriptor has no units')
   local template=resolved.template or native.template
   assert(selected_template==nil or selected_template==template,'resolved template differs between bodies')
   selected_template=template;item.binding.template=template
   for old,hash in pairs(resolved.remaps or{})do
    local path=assert(paths[hash],'resolved remap target has no declared resource path')
    local held=item.binding.remaps[old]
    assert(not held or held.hash==hash,'resolved remap differs between bodies: '..old)
    item.binding.remaps[old]={hash=hash,path=path}
   end
   -- The materials the look binds in place of packaged ones: one map for the
   -- look, since a unit of either body may be the one an actor stands in.
   for packaged,alternative in pairs(resolved.materials or{})do
    item.materials=item.materials or{}
    local chosen=item.materials[packaged]
    assert(chosen==nil or chosen==alternative,'resolved materials differ between bodies: '..tostring(packaged))
    item.materials[packaged]=alternative
   end
   item.bodies[name]={units=copy(resolved.units)}
  end
 end
