end
-- One patch object for the variant session, bound on `plan` to whichever
-- engine owns the appearance: a claimed carrier composes through its owner,
-- everything else through the native composition.
function M.dispatch(owner,native)
 local inner
 return{plan=function(_,result,request,label)
   local item=owner and owner.bound[request.appearance_id]
   inner=owner and owner.logical and type(request.appearance_id)=='string'and request.appearance_id:match('^clothing:')and owner:patch()or item and not item.spare and owner:patch()or native()
   return inner:plan(result,request,label)
  end,
  apply=function(_,handle)return inner:apply(handle)end,
  reset=function()if not inner then return true,{status='no_active_patch'}end;return inner:reset()end,
  is_active=function()if not inner then return false end;return inner:is_active()end}
end
-- `<uuid> [name=value,...]`; an omitted list is the piece's base word.
function M.parse_set(input)
 if type(input)~='string'then return nil,'expected: <uuid> [name=value,...]'end
 local uuid,rest=input:match('^%s*(%x+)%s*(.-)%s*$')
 if not uuid or not Identity.uuid(uuid:lower())then return nil,'expected a 32-hex clothing uuid'end
 local values={}
 for pair in tostring(rest):gmatch('[^,%s]+')do
  local name,value=pair:match('^([a-z][a-z0-9_]*)=(%d+)$')
  if not name or #value>10 then return nil,'expected name=value pairs, got '..pair end
  values[name]=tonumber(value)
 end
 return uuid:lower(),values
end
function M.parse_uuid(input)
 local uuid=type(input)=='string'and input:match('^%s*(%x+)%s*$')
 if not uuid or not Identity.uuid(uuid:lower())then return nil,'expected a 32-hex clothing uuid'end
