     local listed,reason=pcall(enlist,native,record)
     if not listed then report('clothing.record_unavailable',native.id..':'..reason_of(reason))end
    end
   end end
   -- A home must be a record the Armory can show a card for. Not readable
   -- this early on every launch; then any reserved record will do.
   if type(opts.offered)=='function'then
    local read,value=pcall(opts.offered);offered=read and type(value)=='table'and next(value)~=nil and value or nil
   end
   local previous={}
   if not self.logical and opts.homes then local read,value=pcall(opts.homes.load);previous=read and type(value)=='table'and value or{}end
   -- Pieces that remember a home are housed first, so a piece that does not
   -- can never take a record a later one is known by.
   local homes={}
   for round=1,2 do
    for _,piece in ipairs(registry.list())do
     if piece.binding and piece.uuid and(previous[piece.uuid]~=nil)==(round==1)then
      local housed,home=pcall(admit,piece,previous[piece.uuid])
      if housed then homes[piece.uuid]=home
      else self.failed[piece.id]=reason_of(home);report('clothing.binding_failed',piece.id..':'..reason_of(home))end
     end
    end
   end
   local free={}
   for _,id in ipairs(ids_of())do
    local entry=carriers[id]
    if not entry.home then
     -- A pool record: nobody's home, never an entitlement.
     self.bound[id]={slot=entry.slot,carrier=id,spare=true};free[entry.slot]=(free[entry.slot]or 0)+1
    end
   end
   report('clothing.pool','armor='..(free.armor or 0)..' helmet='..(free.helmet or 0)..' cape='..(free.cape or 0))
   if not self.logical and opts.homes and next(homes)then
    for uuid,id in pairs(previous)do if homes[uuid]==nil then homes[uuid]=id end end
    pcall(opts.homes.save,homes)
   end
  end)
  self.phase=ok and'ready'or'failed';self.failure=not ok and tostring(why)or nil
  return ok,self.failure
 end
 function self:watch(key,observer)
  assert(type(key)=='table'and type(observer)=='function','a keyed clothing observer is required')
  observers[key]=observer
 end
 local function expected(entry)return entry.head..entry.applied.passive..entry.tail..entry.applied.descriptor end
 function self:verify(id)
  local entry=carriers[id]
  if self.phase~='ready'or not entry then return false end
  -- A pool record the account owns and wears as the armor it natively is
  -- holds what the game or a native variant put there: not ours to vouch for.
  if not self.logical and wearing[entry.slot]==id and not entry.home then return true end
  local ok,live=pcall(bridge.read,entry.at,Kit.size)
  if ok and type(live)=='string'and #live==Kit.size and live~=expected(entry)
   and not entry.applied.passive_owned
   and head_of(live)==entry.head and tail_of(live)==entry.tail
   and descriptor_of(live)==entry.applied.descriptor then
   -- A passive provider can finish after clothing discovery. Only adopt its
   -- passive word when we never selected a passive on this record, all other
   -- bytes and the catalog still match, and the enum is recognized. This is
   -- observation, not a write or a repair of an explicit Transmog variant.
   local enum=u32(live,Kit.passive)
   if data.passives[enum]and catalog_unchanged()and bridge.read(entry.at,Kit.size)==live then
    local passive=passive_of(live)
    entry.passive=passive;entry.applied.passive=passive
    for _,kit in ipairs({entry.native,entry.applied.reference})do
     kit.passive_enum=enum;kit.passive_variant_id=data.passives[enum].variant_id
     kit.header=cut(kit.header,0,Kit.passive*2)..hex(passive)..cut(kit.header,(Kit.passive+4)*2)
    end
    report('clothing.passive_observed',id..':'..tostring(enum))
   end
  end
  return ok and live==expected(entry)and bridge.verify()==true
 end
 function self:reference(id)
  local entry=carriers[id]
  return entry and(entry.applied.reference or entry.native)or nil
 end
 function self:applied(id)
  local entry=carriers[id]
  if not entry then return nil end
  return{look=copy(entry.applied.look),stats_id=entry.applied.stats_id,passive=hex(entry.applied.passive),
   pristine=entry.applied.descriptor==entry.pristine,rendered=entry.applied.rendered}
 end
 -- What the record's appearance is composed from right now: the token the
 -- Armory preview compares to know its model was built from an older record.
 function self:look_word(id)
  local entry=carriers[id];if not entry then return nil end
  local look=entry.applied.look
  return look and(self.logical and look.uuid or look.uuid:sub(1,8))..':'..look.word or'stock'
 end
 -- The passive a carrier shipped with, whatever its variant composed on it.
 function self:pristine_passive(id)
  local entry=carriers[id];return entry and entry.passive or nil
 end
 -- Fresh immutable buffers per descriptor: a live actor may still be reading the
 -- previous ones, so nothing is ever mutated in place, freed or reused.
 local function publish(kit)
  local descriptors={}
  for _,body in ipairs(kit.bodies)do
   local raw={};for _,piece in ipairs(body.pieces)do raw[#raw+1]=bytes(piece.raw)end
   local allocation=assert(writer.allocate(table.concat(raw)))
   descriptors[#descriptors+1]=p32(body.type)..p32(0)..pp(allocation.address)..p32(#raw)..p32(0)
  end
  local allocation=assert(writer.allocate(table.concat(descriptors)))
  return pp(allocation.address)..p32(#descriptors)..p32(0)
 end
 local function swap(at,before,replacement)
  local wrote=writer.write(at,replacement)==true
  local after=bridge.read(at,#before)
  if wrote and after==replacement then return true end
  if after~=before and after~=replacement then return nil,'carrier field is neither before nor after the write'end
  if after==replacement then writer.write(at,before)end
  return nil,'carrier write/readback failed'
 end
 -- The pack's own units a kit names, {hash=true}: the root unit of every part
 -- that is a private resource of the piece, whichever body it belongs to.
 local function own_units(piece,kit)
  local targets,out=piece.targets,{}
  if not targets then
   targets={};for _,entry in pairs(piece.binding.remaps or{})do targets[entry.hash]=true end
  end
  for _,body in ipairs(kit.bodies)do for _,part in ipairs(body.pieces)do
   if targets[part.path]then out[part.path]=true end
  end end
  return out
 end
 -- A look resolved for this record, or the stock kit when there is none. Any
 -- installed piece of the record's slot: the record lends only its layout.
 local function dress(entry,wanted)
  if not wanted then return nil,M.reference(nil,entry.native,templates)end
  local piece=assert(pieces[wanted.uuid],'look names no installed piece')
  assert(piece.slot==entry.slot,'look belongs to another slot')
  local word,bad=Identity.pack(piece.toggles,wanted.values);assert(word,bad)
  local values=assert(Identity.unpack(piece.toggles,word))
  local item=variant_item(piece,values,registry.resolve)
  local kit=M.reference(item,entry.native,templates)
  M.check(kit,entry.native)
  local known
  if kept(piece)then
   -- From the kit about to be written, every time: what a pack resolves for a
   -- word is its own code's answer and may differ from the last one.
   known=needs_for(piece,Identity.tohex(word),item,kit)
   -- Loaded from the start and leased by nobody: every resource is asked
   -- about all the same, and watched once the look is on. One that is not
   -- there, or whose host somebody holds, is leased from now on.
   if piece.resident and not resident_still(piece,known)then demote(piece)end
   if not piece.resident then
    local ready,why=assets(known,clock)
    if ready==false then error(M.LOADING,0)end
    assert(ready,why)
   end
  elseif bridge.clothing_resource_present then
   for _,body in pairs(item.bodies)do for _,path in ipairs(body.units)do
    assert(bridge.clothing_resource_present(path)==true,'private clothing unit is unavailable')
   end end
  end
  return{uuid=piece.uuid,values=values,word=Identity.tohex(word)},kit,known,item.materials
 end
 -- The record as it is right now, when it is not where or what this session
 -- last left it: found again through the catalog, and whatever is on it taken
 -- as the bytes about to be replaced. Only the kit's identity has to hold.
 local function adopt(entry)
  if not catalog_unchanged()then
   local records,observed=observe();shape=observed
   entry.at=assert(records[entry.native.item_id],'fallback record missing').at
  end
  local live=bridge.read(entry.at,Kit.size)
  if live==expected(entry)then return end
  local tail_at=Kit.passive+4
  assert(cut(live,0,Kit.name_upper)==cut(entry.head,0,Kit.name_upper)
   and cut(live,Kit.category,Kit.bodies)==cut(entry.tail,Kit.category-tail_at,Kit.bodies-tail_at),'carrier identity changed underneath')
  entry.head,entry.tail=head_of(live),tail_of(live)
  local before=entry.applied
  entry.applied={descriptor=descriptor_of(live),passive=passive_of(live)}
  -- Somebody wrote beside the descriptor: what it depicts, and what that
  -- needs loaded, is still what this owner put there.
  if before.descriptor==entry.applied.descriptor then
   entry.applied.look,entry.applied.needs,entry.applied.reference=before.look,before.needs,before.reference
   entry.applied.materials,entry.applied.units=before.materials,before.units
  elseif before.materials then
   -- The look is gone with the bytes, and with it what it bound. The write
   -- that follows may fail and tell nobody, so the revision moves here: who
   -- follows it by number (the step that tells the applier of materials) is
   -- told all the same. No observer is called in the middle of a composition.
   self.revision=self.revision+1
  end
  report('clothing.adopted',entry.id)
 end
 -- The only writer. `spec.look` is a selection or nil for stock pieces,
 -- `spec.stats` a verified donor record or nil for the carrier's own weights,
 -- `spec.passive` four bytes or nil for the carrier's own. `spec.forced` is the
 -- selection path: the clothing layer may not refuse it, so a look that fails
 -- is dropped and a record that moved or changed is taken as it is.
 function self:compose(id,spec)
  local ok,result=pcall(function()
   local entry=assert(carriers[id],'not a clothing carrier')
   spec=spec or{}
   -- Taking a look off because its resources went is never refused: the
   -- stock kit is what a record the account owns holds anyway.
   assert(spec.evicted or not self.logical or native_configured and not held[id],'native ownership is unconfigured or excludes this carrier')
   local dressed,look,kit,known,materials=pcall(dress,entry,spec.look)
   if not dressed then
    if self.logical or not spec.forced then error(look,0)end
    report('clothing.look_dropped',id..': '..reason_of(look))
    look,kit=nil,M.reference(nil,entry.native,templates)
   end
   if spec.stats then kit=M.weighted(kit,spec.stats)end
   local descriptor=look==nil and spec.stats==nil and entry.pristine or publish(kit)
   local passive=spec.passive or entry.passive
   assert(#passive==4,'passive is four bytes')
   if(spec.forced and not self.logical)or spec.evicted then adopt(entry)
   else
    assert(catalog_unchanged(),'catalog changed before clothing composition')
    assert(bridge.read(entry.at,Kit.size)==expected(entry),'carrier record changed underneath')
   end
   if descriptor~=entry.applied.descriptor then
    local wrote,why=swap(entry.at+Kit.bodies,entry.applied.descriptor,descriptor);assert(wrote,why)
   end
   if passive~=entry.applied.passive then
    local wrote,why=swap(entry.at+Kit.passive,entry.applied.passive,passive)
    if not wrote then swap(entry.at+Kit.bodies,descriptor,entry.applied.descriptor);error(why,0)end
   end
   -- A later catalog scan must describe exactly what this owner wrote. A
   -- preview can retain a selected passive after its visual look is cleared;
   -- publishing the pristine header here made that legitimate reserved record
   -- disappear as a header mismatch when the player switched to stock gear.
   local reference=descriptor==entry.pristine and copy(entry.native)or kit
   reference.header=cut(reference.header,0,Kit.passive*2)..hex(passive)..cut(reference.header,(Kit.passive+4)*2)
   -- The catalog's passive entitlement remains the shipped one. Donor reads
   -- use pristine_passive; the current selected enum is in the live bytes.
   entry.applied={descriptor=descriptor,passive=passive,
    passive_owned=spec.passive_owned~=false and spec.passive~=nil,
    look=look,reference=reference,needs=known,
    -- What the look binds in place of packaged materials, and the pack's own
    -- units the record names for it: neither exists without a look.
    materials=look and materials or nil,units=look and own_units(pieces[look.uuid],kit)or nil,
    stats_record=spec.stats,stats_id=spec.stats and spec.stats.reference and spec.stats.reference.id or nil,rendered=false}
   -- The look taken off because its resources went away, to be put back.
   entry.evicted=spec.evicted and spec.evicted.uuid and spec.evicted or nil
   if known then
    -- The pack's units this record now names, per host: what is looked for
    -- in the worlds before a host is given back.
    -- Under every host of the look, not only the unit's own: a texture kept
    -- in another host is drawn by the same actor.
    for unit in pairs(entry.applied.units)do
     for _,host in ipairs(known.ids)do named[host]=named[host]or{};named[host][unit]=true end
    end
    -- The same for the alternative materials it binds: an instance may carry
    -- one after the look left every record.
    for _,alternative in pairs(materials or{})do
     for _,host in ipairs(known.ids)do bound_from[host]=bound_from[host]or{};bound_from[host][alternative]=true end
    end
   end
   data.kits[entry.native.item_id]=reference
   self.bound[id].variant=look and look.word or nil
   self.composes=self.composes+1
   notify()
   return(look and look.word or'stock')..(spec.stats and'+'..tostring(entry.applied.stats_id)or'')
  end)
  if not ok then
   -- A base word that will not go on (a piece its pack disabled, a unit that
   -- is gone) is said once and not asked for again: the record keeps what it has.
   -- Assets on their way are no failure: whoever asked asks again.
   if reason_of(result)==M.LOADING then return nil,M.LOADING end
   if spec and spec.floor and carriers[id]then
    carriers[id].unfloorable=true;report('clothing.floor_failed',tostring(id)..': '..reason_of(result))
   else report('clothing.compose_failed',tostring(id)..': '..reason_of(result))end
   return nil,reason_of(result)
  end
  report('clothing.composed',tostring(id)..' '..result)
  return true,result
 end
 function self:restore(id)return self:compose(id,{})end
 -- A peer's look, lent to a record this client chose for that peer. It is
 -- composed by the reconciler exactly like a local desired look, but only
 -- while this client does not wear the record: the local look always outranks
 -- a lend. Nil takes the lend off. Nothing here redraws; the remote module
 -- points the peer's actor at the record.
 local function packed(look)
  local piece=type(look)=='table'and pieces[look.uuid]
  if not piece then return nil,'the look names no installed piece'end
  local limbs,bad=Identity.pack(piece.toggles or{},look.values or{})
  if not limbs then return nil,bad end
  return{uuid=piece.uuid,values=copy(look.values or{}),word=Identity.tohex(limbs)},piece
 end
 function self:lend(id,look)
  local entry=carriers[id];if not entry then return nil,'not a reserved record'end
  if look==nil then lends[id]=nil;return true end
  if self.logical and(player_leases[entry.slot]==id or preview_leases[entry.slot]==id)then return nil,'record is reserved locally'end
  if held[id]then return nil,'the account owns this record: it is an armor of its own'end
  local lent,piece=packed(look);if not lent then return nil,piece end
  if piece.slot~=entry.slot then return nil,'a lend must name a piece of the record\'s slot'end
  lent.source=look.source;lends[id]=lent
  return true
 end
 function self:lent(id)return lends[id]~=nil end
 -- The identity word a look packs to: what tells two saved variants of one
 -- piece apart. By the piece's home record, or by its uuid.
 function self:word(id,values)
  local entry=carriers[id];local piece=entry and entry.home or pieces[id]
  if not piece then return nil end
  local limbs=Identity.pack(piece.toggles or{},values or{})
  return limbs and Identity.tohex(limbs)or nil
 end
 -- Installed visual content can be staged or lent without a local home.
 -- Expose copied identity metadata, never a native allocation or descriptor.
 function self:installed_pieces()
  local out={};for _,piece in pairs(pieces)do out[#out+1]=copy(piece)end
  table.sort(out,function(a,b)return a.id<b.id end);return out
 end
 -- Is a piece of this registry identity installed? Asked for every row the
 -- registry reports, so it copies nothing.
 function self:installed_id(id)
  for _,piece in pairs(pieces)do if piece.id==id then return true end end
  return false
 end
 function self:installed(uuid)
  local piece=pieces[uuid]
  return piece and{id=piece.id,uuid=piece.uuid,slot=piece.slot,record=piece.record,
   status=piece.record and'local_binding_ready'or'installed_unhoused'}or nil
 end
 -- What a record depicts right now, as {uuid=,word=}, or nil for the stock kit.
 function self:depicts(id)
  local entry=carriers[id];local look=entry and entry.applied.look
  return look and{uuid=look.uuid,word=look.word}or nil
 end
 -- The pool records of a slot (nobody's home), in a stable order; with
 -- `homes` the home records after them. What peers and thumbnails draw from.
 function self:records(slot,homes)
  local out,last={},{}
  for _,id in ipairs(ids_of(slot))do
   if carriers[id].home then if homes then last[#last+1]=id end
   elseif not held[id]and not capture_leases[id]and(not self.logical or native_configured and player_leases[carriers[id].slot]~=id and preview_leases[carriers[id].slot]~=id)then out[#out+1]=id end
  end
  for _,id in ipairs(last)do out[#out+1]=id end
  return out
 end
 function self:slot_of(id)local entry=carriers[id];return entry and entry.slot or nil end
 -- The reserved records per slot, counted now: a piece's home, or free (a
 -- record the account owns is kept out of the pool and not counted).
 function self:pool()
  local out={}
  for _,slot in ipairs(M.SLOTS)do
   local n={records=0,homes=0,free=0}
   for _,id in ipairs(ids_of(slot))do
    if carriers[id].home then n.homes=n.homes+1 elseif not held[id]then n.free=n.free+1 end
   end
   n.records=n.homes+n.free;out[slot]=n
  end
  return out
 end
 -- Pool records the account owns (the catalog says which): armors in their own
 -- right, which the local actor or anybody else may wear as they are. Nothing
 -- is lent to, shown on or composed on one.
 function self:hold(ids)
  if self.logical then return self:configure_native_owned(ids)end
  held={}
  for id in pairs(type(ids)=='table'and ids or{})do
   if carriers[id]and not carriers[id].home then held[id]=true;lends[id]=nil;shows[id]=nil end
  end
  return true
 end
 -- Logical leases are role-stable for this bounded local mode. There is no
 -- release API: native quiescence for role reuse is not established here.
 function self:configure_native_owned(ids)
  if not self.logical then return nil,'logical mode is disabled'end
  if type(ids)~='table'then return nil,'native ownership map required'end
  local next_held={}
  for id,value in pairs(ids)do if value==true and carriers[id]then next_held[id]=true end end
  -- Changed ownership quarantines an existing reservation; never migrate it
  -- silently or compose on newly owned stock gear.
  held=next_held;native_configured=true
  for _,leases in ipairs({player_leases,preview_leases})do for _,id in pairs(leases)do
   if held[id]then return nil,'reserved record became natively owned'end
  end end
  return true
 end
 local function occupied(id)
  if type(opts.occupied)=='function'then
   local ok,value=pcall(opts.occupied,id)
   if not ok or value~=false then return true end
  end
  return false
 end
 local function reserve(slot,leases,other)
  if not self.logical or self.phase~='ready'then return nil,'logical owner is not ready'end
  if not native_configured then return nil,'native ownership is not configured'end
  if not categories[slot]then return nil,'unknown equipment slot'end
  local retained=leases[slot]
  if retained then
   if held[retained]or not self:verify(retained)then return nil,'reserved record requires attention'end
   return retained
  end
  local seen=self:equipment()
  -- Unknown local equipment cannot prove an unworn record is free.
  if not seen or type(seen[slot])~='string'then return nil,'local equipment is unreadable'end
  local actual=seen[slot]:lower()
  for _,id in ipairs(ids_of(slot))do
   if not held[id]and other[slot]~=id and not capture_leases[id]and not lends[id]and not shows[id]
    and actual~=id and wearing[slot]~=id and not occupied(id)and(offered==nil or offered[id])and self:verify(id)then
    leases[slot]=id;return id
   end
  end
  return nil,'no safe free '..slot..' record'
 end
 function self:player_record(slot)return reserve(slot,player_leases,preview_leases)end
 function self:preview_record(slot)return reserve(slot,preview_leases,player_leases)end
 function self:is_player_record(id)local entry=carriers[id];return entry~=nil and player_leases[entry.slot]==id end
 function self:is_preview_record(id)local entry=carriers[id];return entry~=nil and preview_leases[entry.slot]==id end
 -- The reserved record the local actor is on, per slot: the id, false when it
 -- wears something else, nil while that was never readable. Read once per
 -- reconciler step; an unreadable moment (an armor change still streaming)
 -- keeps the last reading.
 local function read_worn()
  local seen=self:equipment();if not seen then return end
  for slot in pairs(categories)do
   local on=seen[slot]
   if type(on)=='string'then local id=on:lower();wearing[slot]=carriers[id]~=nil and id or false end
  end
 end
 -- That record when it is a piece's home: the only reserved record the local
 -- actor wears as a modded piece. A pool record the account owns and wears
 -- as the armor it natively is belongs to the game.
 local function mine_of(slot)
  local id=wearing[slot]
  if self.logical then
   if id and player_leases[slot]==id and carriers[id].applied.look then return id end
   if id==nil then return nil end
   return false
  end
  if id and not carriers[id].home then return false end
  return id
 end
 function self:is_held(id)return held[id]==true end
 -- Whether the local actor is on this record, whoever dresses it.
 function self:worn(id)
  local entry=carriers[id];return entry~=nil and wearing[entry.slot]==id
 end
 -- The piece's home the local actor wears in a slot, as the eight hex digits
 -- the wire carries, or nil. With a uuid: only when that is the piece on it,
 -- so the wire never names a piece the actor does not wear.
 function self:wearing(slot,uuid)
  local id=mine_of(slot)
  local piece=id and(self.logical and carriers[id].applied.look or carriers[id].home)
  if not id or(uuid~=nil and(not piece or piece.uuid~=uuid))then return nil end
  return id:sub(7)
 end
 -- The piece on the local actor in a slot: its uuid, false when the actor
 -- wears no piece's home, nil while that was never readable.
 function self:on(slot)
  local id=mine_of(slot)
  if not id then return id end
  return(self.logical and carriers[id].applied.look or carriers[id].home).uuid
 end
 -- The alternative materials the look on a record binds, {packaged=
 -- alternative}, or nil: for stock, and for a look that binds none.
 function self:materials_of(id)
  local entry=carriers[id]
  return entry and copy(entry.applied.materials)or nil
 end
 -- How many records depict a look that binds an alternative material: counted
 -- on asking, over records that are only read. Nothing is made.
 function self:material_looks()
  local n=0
  for _,id in ipairs(all_ids())do if carriers[id].applied.materials then n=n+1 end end
  return n
 end
 -- Whether every texture the wanted alternatives bring is loaded: asked of
 -- the engine each time. An alternative that names none is ready as it is;
 -- one the piece does not declare cannot be shown to be loaded.
 local function materials_ready(piece,map)
  local declared=piece and piece.binding.materials
  for _,alternative in pairs(map)do
   local entry=declared and declared[alternative]
   if not entry then return false end
   for _,path in ipairs(entry.textures or{})do if not there('texture',path)then return false end end
  end
  return true
 end
 -- What the applier of materials is told: one row for every record that
 -- depicts a look and that an actor in the main world stands on or may stand
 -- on, whoever dresses it. The record the local actor wears in each slot --
 -- while that was never readable, every home of the slot: any may be it --
 -- then every record lent to a peer, then every record a remote actor
 -- renders or streams toward with no lend on it (a peer on its own record, a
 -- peer who renders natively): `opts.standing` answers with those, as
 -- {record id=true}, and is asked for nothing else. Without it nobody is
 -- taken to stand anywhere; when it raises, anybody may stand on anything.
 -- Two wearers of one unit must both be told, or one's choice is bound on
 -- the other. A look that binds nothing has a row too, with an empty map: it
 -- is how a unit that lives on gets its packaged materials back. A home at
 -- rest that nobody stands on has none. A stable order, and a new array of
 -- copies each time.
 function self:depictions()
  local out,listed={},{}
  local function tell(id,role)
   local entry=carriers[id];local applied=entry and entry.applied
   if listed[id]or not(applied and applied.look and applied.units)then return end
   listed[id]=true
   local piece=pieces[applied.look.uuid]
   local map=copy(applied.materials)or{}
   out[#out+1]={key=id,world='main',units=copy(applied.units),materials=map,ready=materials_ready(piece,map),
    piece=piece and piece.id or nil,role=role}
  end
  local ids=all_ids()
  for _,slot in ipairs(M.SLOTS)do
   local mine=wearing[slot]
   if mine then tell(mine,'local')
   elseif mine==nil then
    for _,id in ipairs(ids)do if carriers[id].slot==slot and carriers[id].home then tell(id,'local')end end
   end
  end
  local lent={};for id in pairs(lends)do lent[#lent+1]=id end;table.sort(lent)
  for _,id in ipairs(lent)do tell(id,'peer')end
  local asked,stood=true,nil
  if type(opts.standing)=='function'then asked,stood=pcall(opts.standing)end
  if type(stood)~='table'then stood=nil end
  for _,id in ipairs(ids)do
   if not listed[id]and carriers[id].applied.look and(not asked or stood~=nil and stood[id]==true)then tell(id,'peer')end
  end
  return out
 end
 -- A look shown on a pool record, so the Armory renders its own thumbnail of
 -- it (the game draws one image per record). A peer's lend always outranks
 -- what is shown, and so does the local actor; nil takes it off. Composed at
 -- once when nothing is in flight, because the list that borrows the record is
 -- built right after.
 local function show_record(id,look,lease)
  if capture_leases[id]and capture_leases[id]~=lease then return nil,'preview generation owns this pool record'end
  local entry=carriers[id];if not(entry and not entry.home and not held[id])then return nil,'not a pool record'end
  if self.logical and(not native_configured or player_leases[entry.slot]==id)then return nil,'record is reserved for the local player'end
  if look==nil then shows[id]=nil
  else
   local shown,piece=packed(look);if not shown then return nil,piece end
   if piece.slot~=entry.slot then return nil,'look belongs to another slot'end
   shows[id]=shown
  end
  if lends[id]or self.phase~='ready'or self:in_flight()or wearing[entry.slot]==id then return true,'deferred'end
  local want=shows[id]
  if same(want,entry.applied.look)then return true end
  local ok,why=self:compose(id,{look=want and{uuid=want.uuid,values=want.values}or nil,
   stats=entry.applied.stats_record,passive=entry.applied.passive,passive_owned=entry.applied.passive_owned==true})
  if not ok then return true,'deferred: '..tostring(why)end
  entry.applied.rendered=true
  return true
 end
 function self:show(id,look)return show_record(id,look)end
 function self:preview_leased(id)return capture_leases[id]~=nil end
 -- A rebuild may compose a pool record temporarily. Its token protects the
 -- desired thumbnail look from another UI caller; peers and worn equipment
 -- retain their existing priority. All bytes still flow through compose().
 function self:preview_acquire(id,look)
  local entry=carriers[id]
  if not(entry and not entry.home and not held[id])then return nil,'free pool record required'end
  if capture_leases[id]or lends[id]or wearing[entry.slot]==id then return nil,'pool record is in use'end
  local want,why=packed(look);if not want then return nil,why end
  if pieces[want.uuid].slot~=entry.slot then return nil,'look belongs to another slot'end
  local lease={id=id,prior=copy(shows[id]),look=want}
  capture_leases[id]=lease
  local ok,reason=show_record(id,want,lease)
  if not ok then capture_leases[id]=nil;return nil,reason end
  return lease
 end
 function self:preview_ready(lease)
  if type(lease)~='table'or capture_leases[lease.id]~=lease then return nil,'preview composition lease expired'end
  local entry=carriers[lease.id]
  if held[lease.id]or lends[lease.id]or wearing[entry.slot]==lease.id then return nil,'pool record acquired a higher-priority owner'end
  if self.phase~='ready'then return false,'clothing owner not ready'end
  if not same(entry.applied.look,lease.look)then return false,'composition not applied yet'end
  if not self:verify(lease.id)then return false,'record bytes not verified'end
  return true
 end
 function self:preview_release(lease)
  if type(lease)~='table'then return nil,'preview composition token required'end
  if lease.closed then return true end
  if capture_leases[lease.id]~=lease then return nil,'preview composition token changed'end
  -- Native ownership clears shows itself. Never compose over that transition.
  -- The second value says when the record is put back later, not now.
  local later
  if not held[lease.id]then
   local ok,why=show_record(lease.id,lease.prior,lease)
   if not ok then return nil,why end
   later=why
  end
  capture_leases[lease.id]=nil;lease.closed=true
  return true,later
 end
 -- Whether the record holds the look lent to it (or, on a pool record, what
 -- it rests at once the lend came off): the remote module writes a peer's
 -- slot only then, so the actor streams what was composed for it and never
 -- re-streams for a composition that was still on its way.
 function self:lend_settled(id)
  local entry=carriers[id];if not entry then return true end
  local have=entry.applied.look
  if lends[id]then return same(have,lends[id])end
  if not entry.home then return same(have,shows[id])end
  return true
 end
 -- A piece's base look: what its home rests at.
 local function base_of(piece)
  piece.floor=piece.floor or{uuid=piece.uuid,values={},word=Identity.tohex((Identity.pack(piece.toggles or{},{})))}
  return piece.floor
 end
 -- The native variant path composes through here: one patch object per
 -- composition, the four calls the native engine answers to, and the same
 -- carrier state underneath. Every write it asks for is forced.
 function self:patch()
  local owner,patch,plans,active=self,{},{},nil
  function patch:plan(result,request,label)
   if active then return nil,'an active patch must be reset before planning another'end
   local ok,handle,plan=pcall(function()
    -- The piece is the one whose home the request names, worn on that home.
    local carrier=request.appearance_id
    local uuid=owner.logical and type(carrier)=='string'and carrier:match('^clothing:(%x+)$')
    local piece=uuid and pieces[uuid]
    if owner.logical then
     assert(piece,'unknown logical clothing identity')
     local reason;carrier,reason=owner:player_record(piece.slot);assert(carrier,reason)
    end
    local entry=assert(carriers[carrier],'not a clothing carrier')
    piece=piece or assert(entry.home,'not a clothing piece')
    assert(type(result)=='table'and type(result.records)=='table'and type(result.owned)=='table','fresh catalog result required')
    if not owner.logical then assert(result.owned[carrier]==true,'clothing carrier is not currently owned')end
    local stats_hex=tostring(request.stats_id):match('^native%-stats:(%x%x%x%x%x%x%x%x)$')
    local stats_id=stats_hex and'armor:'..stats_hex
    local stats=stats_id and result.records[stats_id]
    assert(stats and result.owned[stats_id]==true,'base stats donor is not currently owned')
    local passive_id
    local ids={};for kid in pairs(result.catalog)do ids[#ids+1]=kid end;table.sort(ids)
    for _,kid in ipairs(ids)do
     if result.owned[kid]==true and(not owner.logical or not carriers[kid]or held[kid])and result.catalog[kid].passive_variant_id==request.passive_variant_id then passive_id=kid;break end
    end
    local passive=passive_id and result.records[passive_id]
    assert(passive,'exact passive donor is not currently owned')
    if owner.logical then
     assert(stats.category==categories[piece.slot]and passive.category==categories[piece.slot],'native donor category differs')
     assert(not carriers[stats_id]or held[stats_id],'base stats donor is not natively owned')
     assert(not carriers[passive_id]or held[passive_id],'passive donor is not natively owned')
     assert(type(result.verify_owned)=='function'and result.verify_owned({stats_id,passive_id})==true,'native donor ownership changed')
    end
    -- A claimed donor's live passive is whatever its variant composed; the
    -- passive it stands for is the one it shipped with.
    local passive_bytes=carriers[passive_id]and carriers[passive_id].passive or passive_of(passive.bytes)
    local rows;if opts.defaults then local read,value=pcall(opts.defaults,label);rows=read and value or nil end
    local sequence
    if owner.logical then sequence=(player_sequences[piece.slot]or 0)+1;player_sequences[piece.slot]=sequence end
    local plan={carrier=carrier,sequence=sequence,slot=piece.slot,result=result,stats=stats,stats_id=stats_id,passive=passive_bytes,passive_id=passive_id,
     look=M.default_look(rows,piece),
     request={appearance_id=request.appearance_id,stats_id=request.stats_id,passive_variant_id=request.passive_variant_id}}
    return{source_id=owner.logical and request.appearance_id or carrier,target_id=carrier,stats_source_id=stats_id,passive_source_id=passive_id,request=copy(plan.request),
     appearance_labels_preserved=true,package_identity_preserved=true,requires_re_equip=true},plan
   end)
   if not ok then return nil,tostring(handle)end
   plans[handle]=plan
   return handle
  end
  function patch:apply(handle)
   if active then return nil,'an active patch must be reset first'end
   local plan=plans[handle];if not plan then return nil,'unknown or consumed patch plan'end
   plans[handle]=nil
   if owner.logical and(not native_configured or held[plan.carrier]or player_sequences[plan.slot]~=plan.sequence or not plan.result.verify_owned({plan.stats_id,plan.passive_id}))then
    return nil,'logical lease or native donor ownership changed'
   end
   local ok,why=owner:compose(plan.carrier,{look=plan.look,stats=plan.stats,passive=plan.passive,forced=true})
   if not ok then return nil,why end
   -- The refresh that asked for this composition commits the carrier next, so
   -- the native apply renders it; no redraw of ours follows.
   local entry=carriers[plan.carrier]
   entry.applied.rendered=true
   -- The actor is about to be put on this record: what an unreadable moment
   -- answers with.
   wearing[entry.slot]=plan.carrier
   active=plan
   if owner.logical then retained[plan.carrier]=true end
   return true,{status='memory_readback_verified',source_id=owner.logical and plan.request.appearance_id or plan.carrier,target_id=plan.carrier,
    passive_source_id=plan.passive_id,passive_variant_id=plan.request.passive_variant_id}
  end
  function patch:reset()
   if not active then return true,{status='no_active_patch'}end
   if owner.logical then
    -- Keep the currently rendered bytes until the next guarded composition.
    -- Resetting a coordinator handle is not native actor retirement.
    retained[active.carrier]=nil
    active=nil;return true,{status='logical_handle_retired_memory_retained'}
   end
   -- Retired from its variant, a home goes straight back to its piece's base
   -- look and its own stats: never through the placeholder kit, which the
   -- Armory would draw on its card in the meantime. (A piece kept on demand
   -- whose base look is not loaded right now is the exception: the selection
   -- path cannot wait, so the stock kit goes on and the reconciler dresses it.)
   local entry=carriers[active.carrier]
   local rest=entry.home and not entry.unfloorable and base_of(entry.home)or nil
   local ok,why=owner:compose(active.carrier,{look=rest and{uuid=rest.uuid,values=rest.values}or nil,forced=true})
   if not ok then return nil,why end
   active=nil
   return true,{status='original_memory_restored'}
  end
  function patch:is_active()
   if not active then return false end
   local entry=carriers[active.carrier]
   if owner.logical and player_sequences[active.slot]~=active.sequence then return nil,'logical operation was superseded'end
   if not(owner:verify(active.carrier)and entry.applied.stats_id==active.stats_id and entry.applied.passive==active.passive
    and(not owner.logical or entry.applied.look and entry.applied.look.uuid==active.look.uuid))then
    return nil,'retained patch requires attention: carrier composition changed'
   end
   return true,{status='memory_readback_verified',source_id=owner.logical and active.request.appearance_id or active.carrier,target_id=active.carrier}
  end
  return patch
 end
 function self:set(input)
  local uuid,values=M.parse_set(input);if not uuid then return nil,values end
  local ok,why=registry.set_state{uuid=uuid,toggles=values}
  if not ok then return nil,tostring(why)end
  return uuid,values
 end
 function self:clear(input)
  local uuid,why=M.parse_uuid(input);if not uuid then return nil,why end
  local ok,failure=registry.clear_state(uuid)
  if not ok then return nil,tostring(failure)end
  return uuid
 end
 -- The floor: a slot with nothing desired wears a base word -- at the start of
 -- the session, after a variant switch wiped the slot, after a clear. The piece
 -- is the one whose home the actor wears, else the lowest identity of the
 -- slot. A floor put down before the actor could be read is moved to the piece
 -- it turns out to wear, so the slot never names a piece that is not on.
 local floored={}           -- slot -> uuid of the piece this floor was given to
 local function floor_piece(slot)
  local mine=mine_of(slot)
  if mine then return self.logical and pieces[carriers[mine].applied.look.uuid]or carriers[mine].home end
  if self.logical then return nil end
  local best
  for _,piece in pairs(pieces)do if piece.record and piece.slot==slot and(best==nil or piece.id<best.id)then best=piece end end
  return best
 end
 local function dress_bare(state)
  local changed=false
  for _,slot in ipairs(M.SLOTS)do
   local on=state.desired and state.desired[slot]
   local piece=floor_piece(slot)
   local ours=on and floored[slot]==on.uuid and on.word==M.BASE_WORD
   if piece and(not on or(ours and piece.uuid~=on.uuid))then
    local set,why=registry.set_state{uuid=piece.uuid,toggles={}}
    if set then floored[slot]=piece.uuid;changed=true
    else report('clothing.base_failed',piece.id..': '..tostring(why))end
   elseif on and not ours then floored[slot]=nil end
  end
  return changed
 end
 -- The reconciler: the registry's desired state says what look each slot
 -- wears (desired, not the rate-limited published copy the wire carries: a
 -- variant's default is composed before the registry publishes it, and the
 -- carrier must not fall back to the stale look in between); the carrier keeps
 -- whatever stats and passive its variant composed. A redraw follows a worn
 -- carrier's change; an unworn one is simply rewritten and renders when it is
 -- next put on. Nothing is rolled back -- what is written is what was asked
 -- for -- and nothing is written while a native refresh is in flight.
 local function refresher()return opts.refresh end
 local function busy()
  if type(opts.busy)~='function'then return false end
  local ok,value=pcall(opts.busy);return ok and value==true
 end
 -- A worn look change goes on at once and the actor re-streams at once; the
 -- transport is told to publish on the next frame so peers compose it soon,
 -- and every observer rebuilds this actor itself (research/104).
 local function announce()if type(opts.announce)=='function'then pcall(opts.announce)end end
 local function degraded()
  local read=opts.health
  if type(read)~='function'then return nil end
  local ok,value=pcall(read,'report')
  if ok and type(value)=='table'and value.degraded==true then return tostring(value.reason or'the session is degraded')end
  return nil
 end
 -- One reading of the local actor: the body the registry must describe and what
 -- is worn per slot. Nil is not readable yet, which is never "not worn".
 function self:equipment()
  if type(opts.observe)~='function'then return nil end
  local ok,seen=pcall(opts.observe)
  return ok and type(seen)=='table'and seen or nil
 end
 -- Whether the local actor renders this record: the record it was last seen
 -- on, and while that was never readable any home record may be it.
 local function worn(entry)
  local mine=wearing[entry.slot]
  if mine==nil then return entry.home~=nil end
  return mine==entry.id
 end
 local function sync_body(now)
  if next_body and now<next_body then return end
  next_body=now+M.BODY_INTERVAL
  local seen=self:equipment();local value=seen and seen.body
  if(value~=BodyType.muscle and value~=BodyType.lean)or self.body==value then return end
  local set,why=registry.set_body(value)
  if not set then report('clothing.body_failed',tostring(why));return end
  self.body=value;report('clothing.body',tostring(value))
 end
 -- The local re-stream (a cached-armor write the game follows without a
 -- replicated flip) is preferred; the headless refresh is the fallback.
 local function redraw(entry,now)
  local run=opts.restream
  if type(run)=='function'then
   local started,why=pcall(run,'redraw')
   if started then
    flight={id=entry.id,deadline=now+M.REDRAW_TIMEOUT,run=run}
    report('clothing.redraw',entry.id..' (restream)')
    return true
   end
   report('clothing.restream_fallback',entry.id..': '..reason_of(why))
  end
  run=refresher();if not run then return nil,'headless refresh is unavailable'end
  local started,why=pcall(run,'redraw')
  if not started then return nil,reason_of(why)end
  flight={id=entry.id,deadline=now+M.REDRAW_TIMEOUT,run=run}
  report('clothing.redraw',entry.id)
  return true
 end
 local function advance(now)
  local run=flight.run or refresher()
  local ok,status=pcall(run,'status')
  local outcome=ok and tostring(status):match('outcome=(%S+)')or'failed'
  if outcome=='pending'then
   if now>flight.deadline then outcome='timeout'else return end
  end
  local entry=carriers[flight.id];flight=nil
  if outcome=='complete'then entry.applied.rendered=true;self.redraws=self.redraws+1;report('clothing.rendered',entry.id)
  else retry_at=now+M.RETRY;report('clothing.redraw_failed',entry.id..': '..outcome)end
 end
 function self:in_flight()return flight~=nil or busy()end
 -- The needs of a look, resolved and laid out the way a record of its slot
 -- would depict it: which record lends the layout changes no resource. The
 -- last answer for the look's word is kept: this one only decides whether to
 -- wait, and may be asked every frame. Second, whether the answer was a kept
 -- one; `afresh` has the pack asked again whatever is kept.
 local function resolve_needs(piece,look,native,afresh)
  local packed=assert(Identity.pack(piece.toggles,look.values or{}))
  local word=Identity.tohex(packed)
  local by=remembered[piece.uuid]
  local known=not afresh and by and by.words[word]
  if known then return known,true end
  local values=assert(Identity.unpack(piece.toggles,packed))
  local item=variant_item(piece,values,registry.resolve)
  return needs_for(piece,word,item,M.reference(item,native,templates))
 end
 -- The needs of a look something wants, when its piece is kept on demand; nil
 -- for any other look. Remembered by the look table itself, which whoever
 -- wants the look keeps until it changes: this answer only decides whether to
 -- wait, the composition works its own out from what it writes.
 local function needs_of(look,entry)
  local known=needs_by_look[look]
  if known~=nil then return known or nil end
  local piece=pieces[look.uuid]
  if not hosted(piece)then needs_by_look[look]=false;return nil end
  local ok,found=pcall(resolve_needs,piece,look,entry.native)
  -- A look that does not resolve is the composition's to refuse and report.
  needs_by_look[look]=ok and found or false
  return ok and found or nil
 end
 -- A record whose look lost its resources goes back to its stock kit now, and
 -- remembers the look: the reconciler puts it on again when they are back.
 -- The record is taken as it is found (a passive written late, a catalog that
 -- moved): that it stops naming what is not loaded outranks everything else.
 local function evict(entry,why)
  local look,known=entry.applied.look,entry.applied.needs
  report('clothing.assets_gone',entry.id..': '..why)
  if known and hosts then hosts:unsettle(known.key)end
  local ok,failure=self:compose(entry.id,{stats=entry.applied.stats_record,passive=entry.applied.passive,
   passive_owned=entry.applied.passive_owned==true,
   evicted=look and{uuid=look.uuid,values=look.values,word=look.word}or{}})
  if not ok then report('clothing.evict_failed',entry.id..': '..tostring(failure))end
  return ok
 end
 -- Every record that depicts a look with these needs, at once.
 local function evict_all(known,why)
  for _,id in ipairs(all_ids())do
   local entry=carriers[id]
   if entry.applied.needs==known then
    evict(entry,why)
    local piece=pieces[known.uuid]
    if piece and piece.resident then demote(piece)end
   end
  end
 end
 -- Whether a unit a record named from this host is still in a world: asked
 -- before the host is given back. Unknown counts as still there.
 local function standing(host)
  -- A material kept in the host that an instance still carries holds it as
  -- well: only the applier's yes counts, it knows every instance it bound.
  local materials,carried=bound_from[host],bridge.clothing_materials_bound
  if materials and type(carried)=='function'and carried(materials)==true then return true end
  local units=named[host]
  if not units or next(units)==nil then return false end
  local any=bridge.clothing_units_alive
  if type(any)=='function'then return any(units)~=false end
  local ask=bridge.clothing_unit_alive
  for hash in pairs(units)do
   if type(ask)~='function'or ask(hash)~=false then return true end
  end
  return false
 end
 self.standing=standing
 -- Whether a record's last composition of this look failed: it is not tried
 -- again for the same look, and nothing is loaded or kept for it meanwhile.
 local function latched(entry,want)
  local failed=entry.failed
  return failed~=nil and failed.uuid==(want and want.uuid)and failed.word==(want and want.word)
 end
 -- Whether nobody can be looking at a record the actor does not wear: the
 -- Armory is known to have been closed for a while.
 local function idle()return closed_since~=nil and clock-closed_since>=M.RETIRE end
 -- The look a record should depict, and whether that is a piece at rest.
 local want_of,rest_of,in_use={},{},{}
 local function want_for(entry,id,state,mine)
  local desired=state.desired[entry.slot]
  if desired and not pieces[desired.uuid]then desired=nil end
  -- What is on the record, or what was until its resources went away.
  local on=entry.applied.look or entry.evicted
  if on and on.uuid==nil then on=nil end
  -- A home depicts its own piece: the look the slot asks for when that names
  -- this piece, else the base word, whether the actor wears it or not (the
  -- look stage previews an unworn piece there). A home the actor does not
  -- wear takes a peer's lent look first -- never while what is worn cannot
  -- be read: it may be worn. A pool record holds a peer's lent look, else a
  -- look shown for a thumbnail, else the stock kit; one the account owns is
  -- an armor of its own and holds the stock kit unless the actor wears it.
  if self.logical and player_leases[entry.slot]==id then
   -- How long the actor has been off the record while it held a look: the
   -- stamp is taken only then, and dropped the moment it is worn or bare.
   local seen=wearing[entry.slot]
   if on==nil or seen==id or seen==nil then entry.unworn=nil else entry.unworn=entry.unworn or clock end
   if not held[id]and mine[entry.slot]==id and desired and on and desired.uuid==on.uuid then return desired end
   -- Taken off and held by no variant: an on-demand look is let go after a while.
   if on and entry.unworn and not retained[id]and clock-entry.unworn>=M.RETIRE and hosted(pieces[on.uuid])then return nil end
   return on
  elseif entry.home then
   if lends[id]and mine[entry.slot]~=nil and mine[entry.slot]~=id then return lends[id]end
   -- A home the actor is known not to wear, with the Armory long closed, shows
   -- its piece to nobody: one kept on demand goes back to stock until looked at.
   local unseen=idle()and mine[entry.slot]~=nil and mine[entry.slot]~=id and hosted(entry.home)
   if desired and desired.uuid==entry.home.uuid then
    if unseen then return nil end
    return desired
   end
   if entry.unfloorable then return on end
   if unseen then return nil end
   -- What is worn cannot be read yet and the Armory is long closed: nothing
   -- is loaded for a piece nobody is known to wear or look at. The record
   -- keeps what it has until the actor can be read.
   if mine[entry.slot]==nil and idle()and hosted(entry.home)then return on end
   return base_of(entry.home),true
  elseif wearing[entry.slot]==id then return on
  elseif not held[id]then
   local shown=shows[id]
   -- A look composed for a card image is somebody's work in progress, wherever the Armory is.
   if shown and idle()and not capture_leases[id]and hosted(pieces[shown.uuid])then shown=nil end
   return lends[id]or shown
  end
  return nil
 end
 -- The guard: run first in every pass, whatever else is going on. A host
 -- whose lease is gone is leased again at once, and every record that stood
 -- on it goes back to stock (what the game's reset unloaded may read as
 -- present for a moment longer: no single reading is trusted). Once a second
 -- every composed look is asked whether its resources are still there.
 -- `quiet` lets leases nothing needs be given back; never while a redraw is
 -- in flight or the game is busy.
 local function guard(now,quiet)
  local ids=all_ids()
  for host in pairs(in_use)do in_use[host]=nil end
  for _,id in ipairs(ids)do
   local entry=carriers[id]
   local known=entry.applied.needs
   if known then for _,host in ipairs(known.ids)do in_use[host]=true end end
   -- A look something was last seen to want keeps its hosts as well, also
   -- while the pass is held back -- unless it cannot be had right now or
   -- would not go on: then its hosts may go back.
   local want=want_of[id]
