   once('not_equipped',piece.uuid..': '..tostring(piece.slot))
   local held=index[piece.uuid]or{}
   local back=held[row.name]or 0
   return push(host(injected),row,row.kind=='choice'and back+1 or back)
  end
  if type(value)~='number'or value%1~=0 then return once('range',row.id..': '..tostring(value))end
  local toggle=row.kind=='choice'and value-1 or value
  if toggle<0 or toggle>row.max then return once('range',row.id..': '..tostring(value))end
