 function self:status()
  local out={phase=self.phase,panels=self.panels,rows=self.rows,skipped=self.skipped,
   refused=self.refused,pushes=self.pushes,changes=self.changes,items={}}
  for _,uuid in ipairs(order)do
   local piece=pieces[uuid]
   local entry={uuid=uuid,slot=piece.slot,name=piece.name,rows={}}
   for _,row in ipairs(piece.rows)do
    entry.rows[#entry.rows+1]={id=row.id,name=row.name,kind=row.kind,max=row.max,
     value=row.value,toggle=row.kind=='choice'and row.value-1 or row.value}
