end
local function clean(value)return(tostring(value):gsub('%c',' '))end
function M.format_status(status)
 local lines={'HD2TM_CLOTHING_OPTIONS 1',
  'phase='..tostring(status.phase)..' panels='..tostring(status.panels)
  ..' rows='..tostring(status.rows)..' skipped='..tostring(status.skipped)
  ..' refused='..tostring(status.refused)..' pushes='..tostring(status.pushes)
  ..' changes='..tostring(status.changes)}
