local ClothingBindingsMenu = (function()
-- Native key bindings for the look the player is wearing. The host has no press
-- callback: `is_down` is polled from the update hook and a row fires on the
-- false -> true edge only. Slots are always left nil so the host assigns a free
-- native action and keeps it across sessions. Cycling publishes desired state on
-- the registry; the variant driver still owns the rebind and the forced redraw.
local M={CATEGORY='HD2 Transmog',LABEL=128}
M.actions={{kind='piece',id='hd2tm.piece',label='Select Next Transmog Piece'},
 {kind='next',id='hd2tm.next',label='Next Transmog Variant'},
 {kind='previous',id='hd2tm.previous',label='Previous Transmog Variant'},
 {kind='refresh',id='hd2tm.refresh',label='Refresh Transmog Look'}}
local function reason_of(value)return(tostring(value):gsub('^.-%.lua:%d+: ',''))end
-- One step through a piece's whole variant space, first declared toggle moving
-- fastest, wrapping at both ends. Toggles with nothing to choose carry through.
function M.cycle(schema,values,delta)
 local out,span={},0
 for _,toggle in ipairs(schema)do
  local max=type(toggle.max)=='number'and toggle.max or 0
  local held=values and values[toggle.name]
  if type(held)~='number'or held<0 or held>max or held%1~=0 then held=0 end
  out[toggle.name]=held
  if max>0 then span=span+1 end
 end
 if span==0 then return nil,'clothing has no variants to cycle'end
 local carry=delta
 for _,toggle in ipairs(schema)do
  if carry==0 then break end
  local max=type(toggle.max)=='number'and toggle.max or 0
  if max>0 then
   local total=out[toggle.name]+carry
   out[toggle.name]=total%(max+1);carry=math.floor(total/(max+1))
  end
 end
 return out
end
local function host(injected)
 local api=injected or rawget(_G,'ModBindingsMenu')
 return type(api)=='table'and api or nil
end
function M.new(opts)
 assert(type(opts)=='table','clothing bindings menu options required')
 local registry=assert(opts.registry,'clothing registry required')
 local report=opts.report or function()end
