 local self={phase='idle',bound=0,refused=0,fires=0,focus=nil,redraws=0}
 local rows,down,told={},{},{}
 local function once(kind,message)
  local key=kind..':'..tostring(message)
  if told[key]then return end
  told[key]=true;report('clothing.bindings.'..kind,tostring(message))
 end
 local function refresher()
  return refresh
 end
 -- Every registered piece, in the registry's own order, whether or not it is
 -- worn: a binding that could only reach the worn piece could never change it.
 local function catalogue()
  local ok,list=pcall(registry.list)
  if not ok then once('list_error',reason_of(list));return{}end
  local out={}
  for _,item in ipairs(list)do if item.uuid then out[#out+1]=item end end
  return out
 end
 local function held(uuid)
  local ok,state=pcall(registry.state)
  if not ok or type(state)~='table'then
   if not ok then once('state_error',reason_of(state))end
   return nil
  end
  for _,field in ipairs({'desired','applied'})do
   local group=state[field]
   if type(group)=='table'then
    for _,entry in pairs(group)do
     if entry.uuid==uuid and type(entry.values)=='table'then return entry.values end
    end
   end
  end
  return nil
 end
 local function selected(list)
  if #list==0 then return nil end
  for position,item in ipairs(list)do if item.uuid==self.focus then return item,position end end
  self.focus=list[1].uuid
  return list[1],1
 end
 local function advance(list)
  local item,position=selected(list)
  if not item then return once('focus','no clothing is registered')end
  local next_item=list[position%#list+1]
  self.focus=next_item.uuid
  report('clothing.bindings.focus',next_item.uuid..' '..tostring(next_item.name))
 end
 local function roll(list,delta)
  local item=selected(list)
  if not item then return once('focus','no clothing is registered')end
  local schema=type(item.toggles)=='table'and item.toggles or{}
  local values,why=M.cycle(schema,held(item.uuid),delta)
  if not values then return once('cycle',item.uuid..': '..tostring(why))end
  local ok,failure=registry.set_state{uuid=item.uuid,toggles=values}
  if ok~=true then return once('rejected',item.uuid..': '..tostring(failure))end
 end
 local function redraw()
  local run=refresher()
  if not run then return once('refresh','headless refresh is unavailable')end
  local ok,value=pcall(run,'redraw')
  if not ok then return once('refresh',reason_of(value))end
  self.redraws=self.redraws+1
 end
 local function fire(kind)
  self.fires=self.fires+1
  if kind=='refresh'then return redraw()end
  local list=catalogue()
  if kind=='piece'then return advance(list)end
  return roll(list,kind=='next'and 1 or-1)
 end
 local function register(api)
  for _,action in ipairs(M.actions)do
   if rows[action.id]==nil then
    local ok,accepted,why=pcall(api.register_binding,action.id,action.label,nil,
     {category=M.CATEGORY})
    if not ok then rows[action.id]=false;self.refused=self.refused+1
     once('refused',action.id..': '..reason_of(accepted))
    elseif accepted~=true then rows[action.id]=false;self.refused=self.refused+1
     once('refused',action.id..': '..tostring(why or'refused'))
    else rows[action.id]=action;self.bound=self.bound+1 end
   end
  end
 end
 local function poll(api)
  for _,action in ipairs(M.actions)do
   if rows[action.id]then
    local ok,state=pcall(api.is_down,action.id)
    if not ok then once('poll_error',action.id..': '..reason_of(state));state=false end
    state=state==true
    if state and not down[action.id]then fire(action.kind)end
    down[action.id]=state
   end
  end
 end
 function self:step()
  local api=host(injected)
  if not api then self.phase='absent';return self.phase end
  local ok,ready=pcall(api.ready)
  if not ok then self.phase='waiting';once('ready_error',reason_of(ready));return self.phase end
  if ready~=true then self.phase='waiting';return self.phase end
  self.phase='ready'
  register(api)
  poll(api)
  return self.phase
 end
 function self:status()
  local out={phase=self.phase,bound=self.bound,refused=self.refused,fires=self.fires,
   redraws=self.redraws,focus=self.focus,items={}}
  for _,action in ipairs(M.actions)do
   out.items[#out.items+1]={id=action.id,kind=action.kind,label=action.label,
    bound=rows[action.id]~=nil and rows[action.id]~=false,down=down[action.id]==true}
  end
  return out
 end
 return self
end
function M.format_status(status)
 local lines={'HD2TM_CLOTHING_BINDINGS 1',
  'phase='..tostring(status.phase)..' bound='..tostring(status.bound)
  ..' refused='..tostring(status.refused)..' fires='..tostring(status.fires)
  ..' redraws='..tostring(status.redraws)..' focus='..tostring(status.focus or'none')}
 for _,item in ipairs(status.items)do
  lines[#lines+1]=table.concat({item.id,item.kind,item.label,
   'bound='..tostring(item.bound),'down='..tostring(item.down)},'\t')
 end
 return table.concat(lines,'\n')..'\n'
end
return M

end)()
local ClothingHealth = (function()
-- Preflight: is this session sound enough to drive native state and to persist
-- what it assembled?
--
-- Written after a lockout that survived restarts. The addon equipped a carrier
-- at load, the native settings buffers were left with an uncommitted armor
-- change (`profile_armor_id ~= request_armor_id`), every refresh path asserts
-- that equality *before it starts*, and the addon re-created the condition on
-- the next load. Nothing detected it, and the addon kept persisting around it.
--
-- Availability is reported separately from unsafe native state:
--
--   pass      read, and good
--   partial   some registered pieces are unavailable; healthy pieces can run
--   unknown   cannot be read yet
--   degraded  read, and bad
--
-- **`unknown` is never `degraded`.** Startup is full of unreadable moments -- the
-- catalog still resolving, the Armory never opened, a pack not registered yet --
-- and treating any of them as a fault would hold every load forever. Only a
-- reading that was actually taken and actually disagrees degrades a session.
--
-- Nothing here touches native memory. It is handed readings and decides. In
-- particular a native mismatch is never repaired by us: detect, refuse, report.
-- Repair belongs to the game -- the operator changes equipment through the
-- Armory, which commits the profile properly. Anything else is the addon
-- guessing at native invariants it does not own, which is how the original
-- lockout happened.
--
-- Re-evaluated, never latched, so a session recovers by itself once a condition
-- clears.
local M={PASS='pass',PARTIAL='partial',UNKNOWN='unknown',DEGRADED='degraded',
 HEADER='HD2TM_CLOTHING_HEALTH 1',LOADER_API=1,INTERVAL=1000,
 CHECKS={'loader','catalog','native_selection','binding','packs'}}
local function pass()return M.PASS,nil end
local function unknown(why)return M.UNKNOWN,why end
local function degraded(why)return M.DEGRADED,why end
local function id(v)return type(v)=='string'and #v>0 and v or nil end
-- Loader: the one dependency the addon cannot run without. Its api field is a
-- plain table value that is there the moment the loader is, so a present loader
-- that cannot name its API is a fault rather than a timing window.
local function loader_check(r)
 if type(r)~='table'then return unknown('the loader has not been read')end
 if r.present==nil then return unknown('loader presence is unavailable')end
 if r.present~=true then return degraded('Bingus Shared Loader is absent')end
 local api=tonumber(r.api)
 if api==nil then return degraded('Bingus Shared Loader reports no API version')end
 if api<M.LOADER_API then
  return degraded('Bingus Shared Loader API '..api..' is below the required '..M.LOADER_API)
 end
 return pass()
end
-- Catalog: `resolving` is the ordinary startup phase and is unknown; `failed`
-- is a resolution that gave up, and a signature that stops verifying means the
-- game moved underneath every address this session holds.
local function catalog_check(r)
 if type(r)~='table'then return unknown('the native catalog has not been read')end
 if r.phase==nil then return unknown('the native catalog phase is unavailable')end
 if r.phase=='failed'then
  return degraded('native catalog resolution failed'..(r.failure and': '..tostring(r.failure)or''))
 end
 if r.phase~='ready'then
  return unknown('the native catalog is still resolving ('..tostring(r.phase)..')')
 end
 if r.verified==nil then return unknown('the native catalog signature has not been read')end
 if r.verified~=true then return degraded('the native catalog signature no longer verifies')end
 return pass()
end
-- Native selection. `profile_armor_id` is the committed profile buffer and
-- `controller_armor_id` the pending one; they differ exactly while the game
-- holds an armor change it has not committed. That is the original lockout, and
-- it is degraded whoever caused it -- we refuse to act and say so, we never
-- write those buffers to "fix" them.
--
-- A request that has not caught up is an ordinary in-flight switch and is only
-- degraded once the reading says it settled and the two still disagree.
local function selection_check(r)
 if type(r)~='table'then return unknown('the native equipment selection has not been read')end
 local profile,controller=id(r.profile_armor_id),id(r.controller_armor_id)
 if not(profile and controller)then
  return unknown('the native settings selection is not readable here')
 end
 if profile~=controller then
  return degraded('native settings hold an uncommitted armor change: profile '..profile
   ..' controller '..controller..'; change armor in the Armory to let the game commit it')
 end
 local request=id(r.request_armor_id)
 if not request then return unknown('the requested armor is not readable yet')end
 if profile==request then return pass()end
 if r.settled~=true then return unknown('the native armor selection is still transitioning')end
 return degraded('the committed profile armor '..profile
  ..' disagrees with the settled request '..request)
end
-- Clothing binding. `pending` and `binding` are startup; `failed` is a binding
-- run that gave up. A bound carrier that stops verifying means the record this
-- session wrote a descriptor into is no longer the record it verified.
local function binding_check(r)
 if type(r)~='table'then return unknown('the clothing binding has not been read')end
 if r.phase==nil then return unknown('the clothing binding phase is unavailable')end
 if r.phase=='failed'then
  return degraded('clothing binding failed'..(r.failure and': '..tostring(r.failure)or''))
 end
 if r.phase~='ready'then
  return unknown('clothing binding is not ready yet ('..tostring(r.phase)..')')
 end
 if type(r.carriers)~='table'then return unknown('bound carriers are unavailable')end
 local waiting
 for _,entry in ipairs(r.carriers)do
  if entry.verified==false then
   return degraded('bound carrier '..tostring(entry.id)..' no longer verifies')
  elseif entry.verified~=true then waiting=waiting or tostring(entry.id)end
 end
 -- Admission failures concern individual installed pieces, not the integrity
 -- of the verified records that remain usable. Never turn this into the global
 -- mutation/persistence gate used for a corrupt native selection.
 local unavailable={}
 for piece,why in pairs(type(r.failures)=='table'and r.failures or{})do
  unavailable[#unavailable+1]={id=tostring(piece),reason=tostring(why)}
 end
 table.sort(unavailable,function(a,b)return a.id<b.id end)
 if #unavailable>0 then
  return M.PARTIAL,tostring(#unavailable)..' registered clothing pieces unavailable: '
   ..unavailable[1].id..': '..unavailable[1].reason,unavailable
 end
 if waiting then return unknown('bound carrier '..waiting..' has not been verified yet')end
 return pass()
end
-- Packs. A saved row records the content digest and the toggle layout it was
-- written against. New content under the same layout is a pack update: the
-- row decodes as before and nothing is said. Another layout cannot decode it:
-- the store sets that row aside and keeps it in the file (variant_appearance),
-- so it is one look that is off, named here, and never a reason to hold the
-- session. A row naming a piece nobody registered says nothing.
local function packs_check(r)
 if type(r)~='table'then return unknown('the persisted rows have not been read')end
 if type(r.rows)~='table'then return unknown('the persisted rows are unavailable')end
 if type(r.pieces)~='table'then return unknown('the registered clothing is unavailable')end
 for _,row in ipairs(r.rows)do
  local piece=r.pieces[row.uuid]
  if piece and row.schema_digest and piece.schema_digest and row.schema_digest~=piece.schema_digest then
   return M.PARTIAL,'the saved '..tostring(row.slot)..' look of '..tostring(row.label or'a variant')
    ..' was made for another toggle layout of '..tostring(row.uuid)..' ('..row.schema_digest
    ..', the registered piece is '..piece.schema_digest..') and is not applied; set the look again to replace it'
  end
 end
 return pass()
end
M.checks={loader=loader_check,catalog=catalog_check,native_selection=selection_check,
 binding=binding_check,packs=packs_check}
-- Each check is a pure function of one reading, so it can be exercised on its
-- own without a session behind it.
function M.check(name,reading)
 local check=M.checks[name]
 if not check then return M.UNKNOWN,'unknown check: '..tostring(name)end
 return check(reading)
end
function M.new(opts)
 assert(type(opts)=='table','clothing health options required')
 local readers=opts.readers or opts
 local report=opts.report or function()end
 local self={evaluations=0}
 local cached,cached_at,said=nil,nil,{}
 -- A reader that raises, returns nothing, or is not wired at all has failed to
 -- *read*; that is unknown. Nothing a reader can do makes a check degraded
 -- except handing back a reading that actually disagrees.
 local function readout(name)
  local reader=readers[name]
  if type(reader)~='function'then return nil end
  local ok,value=pcall(reader)
  if not ok then return nil end
  return value
 end
 -- Reported once per episode in each direction: a condition that clears and
 -- returns is worth a second line, a condition that simply persists is not.
 local function announce(name,verdict,why)
  if verdict==M.DEGRADED or verdict==M.PARTIAL then
   local key=verdict..'\t'..name..'\t'..tostring(why)
   if said[name]~=key then said[name]=key;pcall(report,'clothing.health.'..verdict,name..': '..tostring(why))end
  elseif said[name]then
   said[name]=nil;pcall(report,'clothing.health.recovered',name)
  end
 end
 function self:evaluate(now)
  if cached and type(now)=='number'and type(cached_at)=='number'
   and now>=cached_at and now-cached_at<M.INTERVAL then return cached end
  self.evaluations=self.evaluations+1
  local checks,state,reasons,warnings={},M.PASS,{},{}
  for _,name in ipairs(M.CHECKS)do
   local verdict,why,unavailable=M.check(name,readout(name))
   local entry={name=name,state=verdict,reason=why,unavailable=unavailable}
   checks[#checks+1]=entry;checks[name]=entry
   if verdict==M.DEGRADED then
    state=M.DEGRADED;reasons[#reasons+1]=name..': '..tostring(why)
   elseif verdict==M.PARTIAL then
    warnings[#warnings+1]=name..': '..tostring(why)
    if state~=M.DEGRADED then state=M.PARTIAL end
   elseif verdict==M.UNKNOWN and state==M.PASS then state=M.UNKNOWN end
   announce(name,verdict,why)
  end
  cached={state=state,degraded=state==M.DEGRADED,partial=#warnings>0,checks=checks,reasons=reasons,warnings=warnings,
   reason=reasons[1]or warnings[1],evaluations=self.evaluations,at=now}
  cached_at=type(now)=='number'and now or nil
  return cached
 end
 function self:status(now)return self:evaluate(now)end
 -- The gate every caller uses: a reason while degraded, nil otherwise. Unknown
 -- partial and pass return nil, because only an unsafe native fault holds a session.
 function self:blocked(now)
  local value=self:evaluate(now)
  if not value.degraded then return nil end
  return value.reason or 'the session is degraded'
 end
 return self
end
local function clean(value)return(tostring(value):gsub('[\t\r\n]',' '))end
function M.format(status)
 if type(status)~='table'then return M.HEADER..'\nstate=unavailable\n'end
 local out={M.HEADER,
  'state='..tostring(status.state)..' degraded='..tostring(status.degraded==true)
  ..' evaluations='..tostring(status.evaluations)}
 for _,entry in ipairs(status.checks or{})do
  out[#out+1]='check\t'..entry.name..'\t'..tostring(entry.state)..'\t'..clean(entry.reason or'-')
  for _,piece in ipairs(entry.unavailable or{})do
   out[#out+1]='unavailable\t'..clean(piece.id)..'\t'..clean(piece.reason)
  end
 end
 for _,reason in ipairs(status.reasons or{})do out[#out+1]='degraded\t'..clean(reason)end
 for _,reason in ipairs(status.warnings or{})do out[#out+1]='partial\t'..clean(reason)end
 return table.concat(out,'\n')..'\n'
end
return M

end)()
local ClothingLink = (function()
-- The Steam lobby link. This client's wire state goes on its own lobby member
-- key; every other member's key is read back as untrusted input and parsed only
-- through clothing_wire. State, never events: the current value is published
-- when it changes, on a lobby change and on a slow heartbeat, and every linked
-- client publishes presence even in stock gear. A publish bumps `rev`; only a
-- look change bumps `lrev`, which is what tells an observer to rebuild the
-- peer's actor from its own composition (research/104). Peers are cached per
-- lobby, so a revision is never compared across lobbies; a malformed peer is
-- rejected whole and logged once per value; a peer that leaves is delivered as
-- gone; a member without a value (no mod, or the previous contract) is absent. Nothing here names a resource, a path
-- or a handle. The Steam shim is injected, so the whole state machine runs in
-- CI without FFI; the production shim is `M.steam()` below.
local M={KEY='hd2tm',INTERVAL=500,HEARTBEAT=15000,MAX_MEMBERS=8,ERROR_BACKOFF=5000,MAX_VALUE=1024}
local function reason_of(value)return(tostring(value):gsub('^.-%.lua:%d+: ',''))end
local function steamid(value)return type(value)=='string'and #value==16 and value:match('^[0-9a-f]+$')~=nil end
function M.new(opts)
 assert(type(opts)=='table'and type(opts.steam)=='table'and type(opts.wire)=='table','link steam shim and wire required')
 local steam,wire=opts.steam,opts.wire
 local report=opts.report or function()end
 local on_peer=opts.on_peer or function()end
 local self={state='starting',lobby=nil,self_id=nil,rev=0,lrev=0,publishes=0,peer_updates=0,stale=0,rejected=0,error=nil,published=nil}
 local desired={body=0}            -- the local wire state without revisions
 local probe=assert(wire.encode{rev=1,lrev=0,body=0}) -- desired at fixed revisions: the content key
 local look=wire.look_key(desired) -- the part of desired that peers compose
 local last_probe,last_look=nil,nil -- keys of the last publish in this lobby
 local published_at=nil
 local peers={}                    -- steamid -> {raw,state,rev,seen_at,changed_at,rejected}
 local synthetic={}                -- steamid -> raw, injected as if read from Steam
 local next_tick,failed=0,false
 local function deliver(id,state,previous)
  local ok,why=pcall(on_peer,id,state,previous)
  if not ok then report('clothing.peer_observer_failed',id:sub(-6)..':'..reason_of(why))end
 end
 local function void_peers()
  local ids={};for id in pairs(peers)do ids[#ids+1]=id end;table.sort(ids)
  for _,id in ipairs(ids)do local entry=peers[id];peers[id]=nil;if entry.state then deliver(id,nil,entry.state)end end
 end
 -- The local state to publish. Validated by a trial encode; a state that will
 -- not encode is refused here rather than failing at publish time.
 function self:set_state(state)
  if type(state)~='table'then return nil,'wire state required'end
  local trial={rev=1,lrev=0,body=state.body or 0}
  for _,slot in ipairs(wire.SLOTS)do trial[slot]=state[slot]end
  local text,why=wire.encode(trial);if not text then return nil,why end
  desired=trial;desired.rev=nil;desired.lrev=nil;probe=text;look=wire.look_key(desired);return true
 end
 function self:inject(id,raw)
  if not steamid(id)then return nil,'a 16-digit hex SteamID is required'end
  if raw~=nil and type(raw)~='string'then return nil,'a raw wire value or nil is required'end
  synthetic[id]=raw;return true
 end
 local function read_peer(id,raw,now)
  local entry=peers[id]or{seen_at=now}
  entry.seen_at=now
  if entry.raw==raw then peers[id]=entry;return end
  entry.raw=raw
  local state,why=wire.decode(raw)
  if not state then
   -- A newer contract we do not speak is not hostile: the peer is simply
   -- absent to us. Anything else is rejected whole and logged once per value.
   if not wire.ignorable(why)then
    self.rejected=self.rejected+1
    if entry.rejected~=raw then entry.rejected=raw;report('clothing.peer_rejected',id:sub(-6)..':'..tostring(why))end
   end
   local previous=entry.state;entry.state,entry.rev=nil,nil;peers[id]=entry
   if previous then deliver(id,nil,previous)end
   return
  end
  entry.rejected=nil
  -- An empty key is absence, not a revision. Versioned stock-gear presence
  -- still carries a revision and must not replace a newer appearance.
  if not state.absent and entry.state and not wire.fresh(entry.rev,state.rev)then self.stale=self.stale+1;peers[id]=entry;return end
  local previous=entry.state
  entry.state,entry.rev,entry.changed_at=state,state.rev,now;peers[id]=entry
  self.peer_updates=self.peer_updates+1
  deliver(id,state,previous)
 end
 local function publish(lobby,text,now)
  assert(steam.write(lobby,text)==true,'lobby member data write refused')
  self.publishes=self.publishes+1;self.published=text;published_at=now;last_probe=probe
 end
 function self:step(now)
  if type(now)~='number'or now<next_tick then return end
  next_tick=now+M.INTERVAL
  local ok,why=pcall(function()
   self.self_id=self.self_id or steam.self()
   assert(steamid(self.self_id),'own SteamID unavailable')
   local lobby=steam.lobby()
   if lobby~=self.lobby then
    void_peers();self.lobby=lobby;self.rev,self.lrev=0,0;last_probe,last_look=nil,nil
    self.published=nil;published_at=nil
   end
   if not lobby then self.state='no-lobby';return end
   self.state='linked'
   local seen={}
   local members=steam.members(lobby)
   for i,id in ipairs(members)do
    if i>M.MAX_MEMBERS then break end
    if id~=self.self_id and steamid(id)and not synthetic[id]then
     seen[id]=true;read_peer(id,steam.read(lobby,id)or'',now)
    end
   end
   for id,raw in pairs(synthetic)do seen[id]=true;read_peer(id,raw,now)end
   for id,entry in pairs(peers)do
    if not seen[id]then peers[id]=nil;if entry.state then deliver(id,nil,entry.state)end end
   end
   -- Publish: on a content change (new revision), after a lobby change, and on
   -- the heartbeat. Stock gear publishes presence like any other state.
   if probe~=last_probe then
    self.rev=self.rev+1
    if look~=last_look then self.lrev=self.lrev+1;last_look=look end
    local text=assert(wire.encode(setmetatable({rev=self.rev,lrev=self.lrev},{__index=desired})))
    publish(lobby,text,now)
   elseif published_at and now-published_at>=M.HEARTBEAT then
    publish(lobby,self.published,now)
   end
  end)
  if ok then failed=false;self.error=nil
  else
   self.state='error';self.error=reason_of(why)
   if not failed then failed=true;report('steam_link.error',self.error)end
   next_tick=now+M.ERROR_BACKOFF
  end
 end
 -- Force the next step to publish the current state again, whatever changed.
 function self:republish()last_probe=nil;next_tick=0;return true end
 -- Present peers: members whose key carries this contract. A member with no
 -- value, or one on another contract, is neither waited for nor listed.
 function self:peers()
  local out={}
  for id,entry in pairs(peers)do
   if entry.state and entry.state.present then out[id]={state=entry.state,rev=entry.rev,seen_at=entry.seen_at,changed_at=entry.changed_at}end
  end
  return out
 end
 function self:present()
  for _,entry in pairs(peers)do if entry.state and entry.state.present then return true end end
  return false
 end
 function self:status()
  local list={}
  for id,entry in pairs(peers)do
   local state=entry.state
   list[id]={rev=entry.rev,lrev=state and state.lrev or nil,present=state and state.present or false,
    vanilla=state and state.vanilla or nil,rejected=entry.rejected~=nil,seen_at=entry.seen_at,changed_at=entry.changed_at}
  end
  return{state=self.state,lobby=self.lobby,self_id=self.self_id,rev=self.rev,lrev=self.lrev,
   present=self:present(),publishes=self.publishes,peer_updates=self.peer_updates,stale=self.stale,rejected=self.rejected,
   error=self.error,published=self.published,peers=list}
 end
 return self
end
function M.format(status)
 local out={'HD2TM_CLOTHING_LINK 1','state='..tostring(status.state),'lobby='..tostring(status.lobby),
  'self='..tostring(status.self_id and status.self_id:sub(-6)),'rev='..tostring(status.rev),'lrev='..tostring(status.lrev),
  'publishes='..tostring(status.publishes),'peer_updates='..tostring(status.peer_updates),
  'stale='..tostring(status.stale),'rejected='..tostring(status.rejected),
