  local out={local_slot=local_slot}
  for slot=0,Layout.slot_count-1 do
   local info=ptr(read(manager+Infos.base+slot*Infos.stride,8))
   local entity=info and u32(read(info+Info.entity,4),0) or nil
   local st={present=info~=nil,live=entity~=nil and entity~=Info.entity_not_live,request={},cache={},at={}}
