  local effects=passive_ok and(lines_held and'held'or true)
  local progression=ptr(bridge.progression)
  local progression_slot=watch(bridge.progression,8)
  local count=u32(watch(progression+Progression.offer_count,4),0)
  assert(count and count>=1 and count<=Progression.max_offers,'progression count rejected')
  local ownership,ownership_proofs={},{}
  -- Only Armor ownership is consumed by this provider. Read offer columns in
  -- bounded batches, then inspect states for matched armor identities. Cache
  -- no ownership across observations; the selected fields are reread below.
  local entry_batch,batch_first,batch_count
  for i=0,count-1 do
   if not entry_batch or i>=batch_first+batch_count then
    batch_first=i;batch_count=math.min(128,count-i)
    local at=progression+Progression.offers+i*Offer.stride
    entry_batch=read(at,(batch_count-1)*Offer.stride+Offer.columns)
    watched[#watched+1]={at=at,size=#entry_batch,bytes=entry_batch,stride=Offer.stride,width=Offer.columns,count=batch_count}
   end
   local offset=(i-batch_first)*Offer.stride
   local entry=cut(entry_batch,offset,offset+Offer.columns)
   local index,item=u32(entry,Offer.index),u32(entry,Offer.item)
   assert(index<count,'progression index rejected')
   local kit=matched_kits[item]
   if kit and (kit.category==Category.armor or kit.category==Category.helmet or kit.category==Category.cape) then
   local state=progression+Progression.states+index*OfferState.stride
   local status=u32(watch(state+OfferState.status,4),0)
   local enabled=watch(state+OfferState.disabled,1):byte()==0
   local allowed=OfferState.owned[status]and enabled
   -- Several offers may grant the same item. Mirror the reference's positive
   -- per-item union: one enabled status-2/4 offer proves ownership; an unrelated
   -- locked/disabled offer for that item never revokes the positive evidence.
   if item~=0 and allowed then
    ownership[item]=true
    if not ownership_proofs[item]then
     ownership_proofs[item]={entry_address=progression+Progression.offers+i*Offer.stride,entry_bytes=entry,state_address=state}
    end
   end
   end
  end
  -- Re-read only observed spans; a race invalidates the entire result.
  for _,span in ipairs(watched)do
   local current=read(span.at,span.size)
   if span.stride then
    -- Unused offer payload bytes were read only to batch the known columns.
    -- They are neither interpreted nor promoted into compatibility evidence.
    for i=0,span.count-1 do
     local first=i*span.stride+1;local last=first+span.width-1
     assert(current:sub(first,last)==span.bytes:sub(first,last),'catalog or ownership changed during observation')
    end
   else assert(current==span.bytes,'catalog or ownership changed during observation')end
  end
  if bridge.verify then assert(bridge.verify(),'catalog compatibility evidence changed')end
  local catalog,owned,owned_count={}, {},0
  for key,kit in pairs(matched_kits)do if kit.category==Category.armor then
   catalog[kit.id]={appearance_id=kit.id,stats_id='native-stats:'..id(key),passive_variant_id=kit.passive_variant_id}
   if ownership[key] then owned[kit.id]=true;owned_count=owned_count+1 end
  end end
  local labels,details,stats_profiles,passive_variants=field_labels({kits=matched_kits,passives=data.passives},bridge,pause,effects)
  local accessories={}
  for category=Category.helmet,Category.cape do
   local catalog,owned={},{}
   for key,kit in pairs(matched_kits)do if kit.category==category then
    catalog[kit.id]={appearance_id=kit.id,stats_id='native-stats:'..id(key),passive_variant_id=kit.passive_variant_id}
    if ownership[key]then owned[kit.id]=true end
   end end
   local l,d,s,p=field_labels({kits=matched_kits,passives=helmet_passives},bridge,pause,lines_held and'held'or true,category)
   local caps=Helmets.capabilities(matched_kits,helmet_passives,category)
   local total,unlocked=0,0
   for _ in pairs(catalog)do total=total+1 end
   for _ in pairs(owned)do unlocked=unlocked+1 end
   report('catalog.'..(category==Category.helmet and 'helmets'or 'capes'),
    'verified='..total..',owned='..unlocked..',creator='..tostring(caps.enabled)
    ..',passives_present='..tostring(caps.passives_present)..',gameplay_changed='..tostring(caps.stats_or_passive_changed))
   accessories[category]={category=category,catalog=catalog,owned=owned,records=records,record_index=record_index,passives=live_passives,
    context={category=category,labels=l,details=d,stats_profiles=s,passive_variants=p},
    capabilities={kit_records_verified=true,ownership_verified=true,accessory_transmog_enabled=caps.enabled,
     helmet_transmog_enabled=category==Category.helmet and caps.enabled or false,cape_transmog_enabled=category==Category.cape and caps.enabled or false},detected=caps}
  end
  -- Fast freshness checks for a later application transaction. These functions
  -- are called outside our coroutine: never use the yielding reader here.
  -- Preserve only the selected progression evidence, never serialize it.
  local function session_valid()
   return type(bridge.verify)=='function' and bridge.verify()
    and bridge.read(bridge.armor_catalog,8)==catalog_slot
    and bridge.read(catalog_at+Object.entries,Array.head)==header
    and bridge.read(bridge.progression,8)==progression_slot
  end
  local function verify_session()
   local ok,value=yieldable_pcall(session_valid);return ok and value==true
  end
  local function verify_owned(ids)
   local ok,value=yieldable_pcall(function()
    if not session_valid()or type(ids)~='table' or u32(bridge.read(progression+Progression.offer_count,4),0)~=count then return false end
    local requested={};local checked=0
    for key,value in pairs(ids)do
     local kit_id=type(key)=='number' and value or (value==true and key or nil)
     if type(kit_id)~='string'then return false end
     requested[kit_id]=true;checked=checked+1;if checked>16 then return false end
    end
    for kit_id in pairs(requested)do
     local record=records[kit_id]
     local proof=record and ownership_proofs[record.item_id]
     -- Recheck the qualifying offer retained above. If it changes, demand a
     -- new observation even if another offer may now grant the same item.
     if not proof or (record.category~=Category.armor and record.category~=Category.helmet and record.category~=Category.cape) or bridge.read(record.slot_address,8)~=record.slot_bytes
      or bridge.read(proof.entry_address,Offer.columns)~=proof.entry_bytes then return false end
     local status=u32(bridge.read(proof.state_address+OfferState.status,4),0)
     if not OfferState.owned[status]or bridge.read(proof.state_address+OfferState.disabled,1)~='\0' then return false end
    end
    return checked>0 and session_valid()
   end)
   return ok and value==true
  end
  self.result={catalog=catalog,owned=owned,records=records,record_index=record_index,passives=live_passives,
   context={labels=labels,details=details,stats_profiles=stats_profiles,passive_variants=passive_variants,
    catalog_status=(unknown_count+changed_count>0)and 'verified native subset; other records unavailable'or 'native kit and ownership observed'},
   diagnostics=diagnostics,
   source_commit=data.source_commit,counts={kits=n,observed=n,matched=matched_count,unavailable=unknown_count+changed_count,
    unknown=unknown_count,changed=changed_count,missing_reference=reference_count-matched_count-changed_count,
    verified_armors=matched_armors,owned_armors=owned_count,progression=count},
   capabilities={kit_records_verified=true,ownership_verified=true,numeric_stats_verified=false,exact_passive_effects_verified=effects==true},
   verify_session=verify_session,verify_owned=verify_owned}
  self.result.helmets,self.result.capes=accessories[Category.helmet],accessories[Category.cape]
  for _,slot in pairs(accessories)do
   slot.verify_session=verify_session
   slot.verify_owned=function(ids)
    if not verify_owned(ids)then return false end
    for key,value in pairs(ids)do
     local id=type(key)=='number'and value or value==true and key
     if not(id and records[id]and records[id].category==slot.category)then return false end
    end
    return true
   end
   -- Effect definitions belong to the game/provider. Changing one does not
   -- revoke an owned helmet or cape. Composition copies the donor's enum and
   -- verifies its kit bytes; it never writes these shared effect arrays.
   slot.verify_passive_effects=function(ids)
    if not slot.verify_owned(ids)then return false end
    local ok,value=yieldable_pcall(function()
     local seen={}
     for key,value in pairs(ids)do
      local id=type(key)=='number'and value or value==true and key
      local record=id and records[id]
      if not(record and record.category==slot.category)then return false end
      local enum=record.reference.passive_enum
      if not seen[enum]then
       local spans=accessory_passive_spans[enum];if not spans then return false end
       for _,span in ipairs(spans)do if bridge.read(span.at,span.size)~=span.bytes then return false end end
       seen[enum]=true
      end
     end
     return verify_session()
    end)
    return ok and value==true
   end
  end
  -- Ownership may change while a composed carrier remains live. Refresh only
  -- progression evidence; the kit records above are pristine reset baselines.
  local ownership_worker
  local function ownership_session_valid()
   return type(bridge.verify)=='function'and bridge.verify()
    and read(bridge.armor_catalog,8)==catalog_slot and read(catalog_at+Object.entries,Array.head)==header
    and read(bridge.progression,8)==progression_slot
  end
  local function refresh_owned()
   assert(ownership_session_valid(),'catalog session changed during ownership refresh')
   local spans={}
   local function observed(at,n)
    local value=read(at,n);spans[#spans+1]={at=at,bytes=value};return value
   end
   local next_count=u32(observed(progression+Progression.offer_count,4),0)
   assert(next_count and next_count>=1 and next_count<=Progression.max_offers,'progression count rejected')
   local next_owned,next_proofs,next_helmets,next_capes={},{},{},{}
   local next_total=0
   for i=0,next_count-1 do
    local entry_at=progression+Progression.offers+i*Offer.stride
    local entry=observed(entry_at,Offer.columns)
    local index,item=u32(entry,Offer.index),u32(entry,Offer.item)
    assert(index and index<next_count,'progression index rejected')
    local kit=matched_kits[item]
    if kit and (kit.category==Category.armor or kit.category==Category.helmet or kit.category==Category.cape) then
     local record=records[kit.id]
     assert(observed(record.slot_address,8)==record.slot_bytes,'catalog record slot changed')
     local state=progression+Progression.states+index*OfferState.stride
     local status=u32(observed(state+OfferState.status,4),0)
     local enabled=observed(state+OfferState.disabled,1):byte()==0
     if OfferState.owned[status]and enabled then
      if kit.category==Category.armor then
       if not next_owned[kit.id]then next_total=next_total+1 end
       next_owned[kit.id]=true
      elseif kit.category==Category.helmet then next_helmets[kit.id]=true else next_capes[kit.id]=true end
      if not next_proofs[item]then
       next_proofs[item]={entry_address=entry_at,entry_bytes=entry,state_address=state}
      end
     end
    end
   end
   for _,span in ipairs(spans)do
    assert(read(span.at,#span.bytes)==span.bytes,'ownership changed during refresh')
   end
   assert(ownership_session_valid(),'catalog session changed during ownership refresh')
   local changed=self.result.capabilities.ownership_verified~=true
   for category,owned in pairs({[Category.helmet]=next_helmets,[Category.cape]=next_capes})do
    local slot=accessories[category]
    if not slot.capabilities.ownership_verified then changed=true end
    for id in pairs(owned)do if not slot.owned[id]then changed=true end end
    for id in pairs(slot.owned)do if not owned[id]then changed=true end end
    slot.owned=owned;slot.capabilities.ownership_verified=true
    -- Retained effect text is only a snapshot. Do not advertise old values
    -- as current after a provider composes a different worn set.
    local checked_effects={}
    for id in pairs(owned)do
     local kit=slot.catalog[id]
     local passive=kit and slot.context.passive_variants[kit.passive_variant_id]
     if passive and not checked_effects[passive]and passive.live_effects_verified and not slot.verify_passive_effects({id})then
      passive.live_effects_verified=false
      passive.effects={'Effect values changed during this session; see the native equipment details.'}
      slot.context.details.passive_variant_id[kit.passive_variant_id]=passive.effects
     end
     if passive then checked_effects[passive]=true end
    end
   end
   for key in pairs(next_owned)do if not self.result.owned[key]then changed=true end end
   for key in pairs(self.result.owned)do if not next_owned[key]then changed=true end end
   count=next_count;ownership_proofs=next_proofs
   self.result.owned=next_owned
   self.result.counts.owned_armors=next_total;self.result.counts.progression=next_count
   self.result.capabilities.ownership_verified=true
   return changed
  end
  function self.result.refresh_ownership()
   if not ownership_worker then ownership_worker=coroutine.create(refresh_owned)end
   deadline=os.clock()+0.006;reads=0;read_bytes=0
   local ok,value=coroutine.resume(ownership_worker)
   if not ok then
    ownership_worker=nil;ownership_proofs={};self.result.owned={}
    for _,slot in pairs(accessories)do slot.owned={};slot.capabilities.ownership_verified=false end
    self.result.counts.owned_armors=0;self.result.capabilities.ownership_verified=false
    return 'failed',tostring(value)
   end
   if coroutine.status(ownership_worker)=='dead'then ownership_worker=nil;return 'ready',value end
   return 'resolving'
  end
  self.phase='ready';watched={}
  report('catalog.owned_armors',owned_count);report('catalog.status',(unknown_count+changed_count>0)and 'native_catalog_subset_verified'or 'native_catalog_verified')
 end
 local worker=coroutine.create(run)
 function self:step()
  if self.phase=='ready'then return 'ready',self.result end
  if self.phase=='failed'then return 'failed',self.failure end
  deadline=os.clock()+0.006;reads=0;read_bytes=0
  local ok,why=coroutine.resume(worker)
  if not ok then self.failure=tostring(why);self.phase='failed';watched={};report('catalog.status',self.failure)end
  return self.phase,self.result or self.failure
 end
 return self
end
return M

end)()
local NativeDisassembler = (function()
