    local row=(entry.id or'-')..'\t'..escaped..'\t'..slot..'\t'..entry.uuid..'\t'..values_text(values)
    if entry.digest~=nil or entry.schema_digest~=nil then
     assert(fingerprint(entry.digest)and fingerprint(entry.schema_digest),
      'variant appearance fingerprints must be 8 lowercase hex digits')
