end
-- Every malformed shape returns a reason instead of raising: a truncated, empty
-- or hand-edited file is an ordinary startup path, not a fault.
function M.decode(raw)
 if type(raw)~='string'or #raw==0 or #raw>M.MAX_BYTES then return nil,'invalid variant appearance record'end
 local head,rest=raw:match('^([^\n]*)\n(.*)$')
 if head~=M.HEADER and head~=M.OLD_HEADER then return nil,'invalid variant appearance record'end
 local version=head==M.HEADER and 2 or 1
 local out,labels,rows={},0,0
 for line in tostring(rest):gmatch('[^\n]+')do
  rows=rows+1
  if rows>M.MAX_VARIANTS*3 then return nil,'too many variant appearance rows'end
  local id
  if version==2 then
   id,line=line:match('^([^\t]+)\t(.*)$')
   if id=='-'then id=nil
   elseif not(id and id:match('^v%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x$'))then return nil,'invalid variant appearance id'end
  end
  local escaped,slot,uuid,tail=tostring(line):match('^([^\t]+)\t([a-z]+)\t([0-9a-f]+)\t(.*)$')
  local label=escaped and unescape(escaped)
  if not label or #label==0 or #label>M.MAX_LABEL then return nil,'invalid variant appearance label'end
  if not slots[slot]then return nil,'invalid variant appearance slot'end
  if not Identity.uuid(uuid)then return nil,'invalid variant appearance uuid'end
  local toggles,digest,layout=tail,nil,nil
  if tail:find('\t',1,true)then
   toggles,digest,layout=tail:match('^([^\t]*)\t([0-9a-f]+)\t([0-9a-f]+)$')
   if not(fingerprint(digest)and fingerprint(layout))then return nil,'invalid variant appearance fingerprint'end
  end
  local values={}
  if toggles~='-'then
   local count=0
   for pair in toggles:gmatch('[^,]+')do
    count=count+1
    if count>M.MAX_TOGGLES then return nil,'too many variant appearance toggles'end
    local name,text=pair:match('^([a-z][a-z0-9_]*)=(%d+)$')
    if not name or #name>32 or #text>10 then return nil,'invalid variant appearance toggle: '..pair end
    values[name]=tonumber(text)
   end
   if count==0 then return nil,'invalid variant appearance toggle list'end
  end
  if not out[label]then
   labels=labels+1
   if labels>M.MAX_VARIANTS then return nil,'too many stored variant appearances'end
   out[label]={}
  end
  if out[label][slot]then return nil,'duplicate variant appearance slot: '..slot end
  out[label][slot]={uuid=uuid,values=values,digest=digest,schema_digest=layout,id=id}
 end
 return out,version
end
function M.new(opts)
 assert(type(opts)=='table','variant appearance options required')
