 -- published right now. A temporary look a clothing mod substituted is published
 -- the same way, so this is deliberately never called on its own.
 function self:save(label)
  if type(label)~='string'or #label==0 or #label>M.MAX_LABEL then return nil,'variant label required'end
  local read,state=pcall(registry.state)
  if not read then return nil,reason_of(state)end
  prune()                     -- what is written goes by today's names and layouts
  local rows={}
  for slot,entry in pairs(state.desired or{})do
   if slots[slot]then rows[slot]={uuid=entry.uuid,values=copy(entry.values)}end
  end
  stamp(rows);identify(label,rows)
  local candidate=copy(saved or{})
  local count=0;for _ in pairs(candidate)do count=count+1 end
  if candidate[label]==nil and count>=M.MAX_VARIANTS then return nil,'too many stored variant appearances'end
  candidate[label]=rows
  -- The label now is exactly the look that is on: nothing of it stays aside.
  local wrote,why=commit(candidate,aside_without(label))
  if not wrote then return nil,why end
  return true,copy(rows)
 end
 -- The wizard's explicit save: exactly the rows given, stamped with this
 -- build's fingerprints, merged into the label's other slots. Validated as a
 -- whole record before anything in memory changes, so a refused save leaves
 -- the store exactly as it was.
 function self:save_rows(label,rows)
  if type(label)~='string'or #label==0 or #label>M.MAX_LABEL then return nil,'variant label required'end
  if type(rows)~='table'or not next(rows)then return nil,'variant appearance rows required'end
  local fresh={}
  for slot,entry in pairs(rows)do
   if not slots[slot]then return nil,'unknown clothing slot: '..tostring(slot)end
   if type(entry)~='table'or not Identity.uuid(entry.uuid)then return nil,'clothing uuid required for '..tostring(slot)end
   fresh[slot]={uuid=entry.uuid,values=copy(entry.values or{})}
  end
  prune()                     -- what is written goes by today's names and layouts
  stamp(fresh);identify(label,fresh)
  local candidate=copy(saved or{})
  local count=0;for _ in pairs(candidate)do count=count+1 end
  if candidate[label]==nil and count>=M.MAX_VARIANTS then return nil,'too many stored variant appearances'end
  candidate[label]=candidate[label]or{}
  for slot,entry in pairs(fresh)do candidate[label][slot]=entry end
  local wrote,why=commit(candidate,aside_without(label,fresh))
  if not wrote then return nil,why end
  return true,copy(saved[label])
 end
 function self:forget(label,slot)
  if type(label)~='string'or #label==0 then return nil,'variant label required'end
  if not slot_ok(slot)then return nil,'unknown clothing slot: '..tostring(slot)end
  prune()
  if not(saved and saved[label])and not stale[label]then return true end
  local candidate=copy(saved or{})
  if candidate[label]then
   if slot then
    candidate[label][slot]=nil
    if not next(candidate[label])then candidate[label]=nil end
   else candidate[label]=nil end
  end
  return commit(candidate,aside_without(label,slot and{[slot]=true}or nil))
 end
 -- Every row the store answers for, for the preflight's pack check: those in
 -- use and those set aside, each with the fingerprints it carries.
 function self:fingerprints()
  prune()
  local out={}
  local function list(source,aside)
   for _,label in ipairs(ordered(source or{}))do
    for _,slot in ipairs(ordered(source[label]))do
     local entry=source[label][slot]
     out[#out+1]={label=label,slot=slot,uuid=entry.uuid,digest=entry.digest,schema_digest=entry.schema_digest,aside=aside}
    end
   end
  end
  list(saved,nil);list(stale,true)
  table.sort(out,function(a,b)if a.label~=b.label then return a.label<b.label end;return a.slot<b.slot end)
  return out
 end
 function self:status()
  prune()
  return{file=file,phase=self.phase,writes=self.writes,switches=self.switches,
   discards=self.discards,label=self.label,active=copy(self.active),
   fault=self.fault,quarantined=self.quarantined,loaded=copy(self.loaded),stored=copy(saved),aside=copy(stale),
   notes=copy(self.notes)}
 end
 return self
end
local function rows(kind,variants,out)
 for _,label in ipairs(ordered(variants or{}))do
  for _,slot in ipairs(ordered(variants[label]))do
   local entry=variants[label][slot]
   out[#out+1]=kind..'\t'..escape(label)..'\t'..slot..'\t'..tostring(entry.uuid)..'\t'
    ..values_text(entry.values)..'\t'..tostring(entry.digest or'-')..'/'..tostring(entry.schema_digest or'-')
  end
 end
end
function M.format_status(status)
 local out={M.HEADER,
  'file='..tostring(status.file)..' phase='..tostring(status.phase)
  ..' writes='..tostring(status.writes)..' switches='..tostring(status.switches)
  ..' discards='..tostring(status.discards)
  ..' variant='..tostring(status.label or'none')
  ..' active='..tostring(status.active and status.active.armor or'-')..'/'..tostring(status.active and status.active.helmet or'-')
  ..'/'..tostring(status.active and status.active.cape or'-')
  ..' fault='..tostring(status.fault or'none')
  ..' quarantine='..tostring(status.quarantined or'none')}
 rows('loaded',status.loaded,out)
 rows('stored',status.stored,out)
 rows('aside',status.aside,out)
 for _,key in ipairs(status.notes or{})do out[#out+1]='note\t'..(key:gsub('[\t\r\n]',' '))end
 return table.concat(out,'\n')..'\n'
end
return M

end)()
local AppearancePatch = (function()
-- Resource-stable composition: the appearance is always its own carrier.
-- Never redirect packages, localization or visual resource paths.
-- All addresses come from fresh observations or retained private data buffers.
-- No native function calls, code patches, file I/O or ownership changes.
-- bridge.verify(result, request, source_id, target_id, phase) MUST check fresh
-- ownership for plan/apply/readback, and session/identity for rollback/reset.
-- Successful apply proves memory readback only, never rendered appearance.
local M = {}
local layout=ArmorLayout or error('module is not bundled: src.armor_layout')
local helmet_layout=HelmetLayout or error('module is not bundled: src.helmet_layout')
local Catalog=GameCatalogLayout or error('module is not bundled: src.game.catalog_layout')
local Kit,Body,Piece=Catalog.kit,Catalog.body,Catalog.piece
local Category,BodyType,Slot,Kind,Weight=Catalog.category,Catalog.body_type,Catalog.slot,Catalog.kind,Catalog.weight

local function u32(s, offset)
    if type(s) ~= 'string' or #s < offset+4 then return nil end
    local a,b,c,d=s:byte(offset+1,offset+4)
    return a+b*256+c*65536+d*16777216
end
local function pointer(s, offset)
    local lo,hi=u32(s,offset),u32(s,offset+4)
    if not hi or hi>=32768 then return nil end
    local value=lo+hi*4294967296
    return value>=65536 and value or nil
end
local function cut(s,from,to)return s:sub(from+1,to or -1)end
local function integer(value)
    return type(value)=='number' and value>=0 and value<=4294967295 and value%1==0
end
local function request_copy(request)
    assert(type(request)=='table','variant request required')
    local copy={}
    for _,field in ipairs({'appearance_id','stats_id','passive_variant_id'}) do
        local value=request[field]
        assert(type(value)=='string' and #value>0 and #value<=128 and not value:find('[%c%s]'),'invalid variant identity')
        copy[field]=value
    end
    return copy
end
local function span(address, bytes, size)
    assert(type(address)=='number' and address%1==0 and address>=65536 and address+size<140737488355328,'invalid observation address')
    assert(type(bytes)=='string' and #bytes==size,'incomplete observation bytes')
    return {address=address,bytes=bytes,size=size}
end
local function record_spans(record,category)
    category=category or Category.armor
    assert(type(record)=='table' and record.category==category,'matching equipment category required')
    local spans={span(record.address,record.bytes,Kit.size)}
    local raw=record.bytes
    assert(integer(record.item_id) and u32(raw,Kit.id)==record.item_id and u32(raw,Kit.category)==category,'kit identity/category mismatch')
    local bodies=record.bodies
    assert(type(bodies)=='table' and #bodies>=1 and #bodies<=Kit.max_bodies,'invalid body profile')
    assert(u32(raw,Kit.body_count)==#bodies and u32(raw,Kit.body_count_high)==0,'body array count mismatch')
    local bodies_at=assert(pointer(raw,Kit.bodies),'body array unavailable')
    local profile,seen_bodies={},{}
    for i,body in ipairs(bodies) do
        assert(type(body)=='table' and integer(body.type) and not seen_bodies[body.type],'duplicate or invalid body type')
        seen_bodies[body.type]=true
        spans[#spans+1]=span(body.address,body.bytes,Body.size)
        assert(body.address==bodies_at+(i-1)*Body.size and u32(body.bytes,Body.type)==body.type,'body observation mismatch')
        local pieces=body.pieces
        assert(type(pieces)=='table' and #pieces>=1 and #pieces<=Body.max_pieces,'invalid piece profile')
        assert(u32(body.bytes,Body.count)==#pieces and u32(body.bytes,Body.count_high)==0,'piece array count mismatch')
        local pieces_at=assert(pointer(body.bytes,Body.pieces),'piece array unavailable')
        local seen_pieces={}
        for j,piece in ipairs(pieces) do
            assert(type(piece)=='table' and integer(piece.slot) and integer(piece.kind) and integer(piece.weight),'invalid piece fields')
            local key=body.type..':'..piece.slot..':'..piece.kind
            assert(not seen_pieces[key],'duplicate body/slot/kind profile')
            seen_pieces[key]=true
            spans[#spans+1]=span(piece.address,piece.bytes,Piece.size)
            assert(piece.address==pieces_at+(j-1)*Piece.size,'piece observation address mismatch')
            assert(u32(piece.bytes,Piece.slot)==piece.slot and u32(piece.bytes,Piece.kind)==piece.kind and u32(piece.bytes,Piece.weight)==piece.weight,'piece observation fields mismatch')
            profile[#profile+1]=key..':'..piece.weight
        end
    end
    table.sort(profile)
    return spans,table.concat(profile,'|')
end
local function packed32(n)
    assert(integer(n),'invalid uint32')
    local out={};for i=1,4 do out[i]=string.char(n%256);n=math.floor(n/256)end;return table.concat(out)
end
local function packed_pointer(n)
    assert(type(n)=='number'and n%1==0 and n>=65536 and n<140737488355328,'invalid private pointer')
    return packed32(n%4294967296)..packed32(math.floor(n/4294967296))
end
local function weights(record,body_type)
    local out,seen={},0
    for _,body in ipairs(record.bodies)do
        if body.type==BodyType.any or body.type==body_type then
            for _,piece in ipairs(body.pieces)do
                assert(seen<Catalog.collector_capacity,'native stats donor exceeds the verified collection capacity');seen=seen+1
                if piece.kind==Kind.armor and piece.weight~=Weight.none then out[#out+1]=piece.weight end
            end
        end
    end
    return out
end
local function weight_bytes(piece,weight)
    assert(weight>=Weight.light and weight<=Weight.none and weight%1==0,'unsupported native weight')
    return cut(piece.bytes,0,Piece.weight)..packed32(weight)..cut(piece.bytes,Piece.weight+4)
end
-- The average getters collect matching-body/Any pieces (first 20), while the
-- class getter additionally selects the contributing Torso slot. Preserve both.
local function composition(source,target,allocate,capabilities)
    -- Uniform donor profiles have the same mathematical mean and torso class
    -- regardless of piece count (float32 summation may differ in low bits).
    -- Keep the look's original body/slot topology intact and use
    -- the donor's weight on every Armor piece. This avoids artificial pieces
    -- and the unproved fourth UI coefficient when the two looks differ.
    local uniform=source.category==Category.armor and layout.uniform(target);local donor_counts={}
    for _,body_type in ipairs({BodyType.muscle,BodyType.lean})do donor_counts[body_type]=#weights(target,body_type)end
    if uniform~=false and uniform~=nil then
        local spans,descriptors={},{};local sequence_preserved=true
        for _,body_type in ipairs({BodyType.muscle,BodyType.lean})do
            local count,armor_count,torso=0,0,false
            for _,body in ipairs(source.bodies)do if body.type==BodyType.any or body.type==body_type then
                for _,piece in ipairs(body.pieces)do
                    count=count+1
                    if piece.kind==Kind.armor then armor_count=armor_count+1 end
                    if piece.kind==Kind.armor and piece.slot==Slot.torso then torso=true end
                end
            end end
            assert(count<=Catalog.collector_capacity and torso,'uniform look exceeds native collector or has no torso')
            if armor_count~=donor_counts[body_type]then sequence_preserved=false end
            for _,weight in ipairs(weights(target,body_type))do if weight~=uniform then sequence_preserved=false end end
        end
        for _,body in ipairs(source.bodies)do
            local pieces={}
            for _,piece in ipairs(body.pieces)do
                pieces[#pieces+1]=piece.kind==Kind.armor and weight_bytes(piece,uniform)or piece.bytes
            end
            local raw=table.concat(pieces);local allocation,why=allocate(raw);assert(allocation,why)
            spans[#spans+1]=span(allocation.address,raw,#raw)
            descriptors[#descriptors+1]=cut(body.bytes,0,Body.pieces)..packed_pointer(allocation.address)..packed32(#pieces)..packed32(0)
        end
        local raw=table.concat(descriptors);local allocation,why=allocate(raw);assert(allocation,why)
        spans[#spans+1]=span(allocation.address,raw,#raw)
        return packed_pointer(allocation.address)..packed32(#descriptors)..packed32(0),spans,
            {uniform_weight=uniform,appearance_topology_preserved=true,
             base_weight_sequence_preserved=sequence_preserved,weight_none=false,stat_only_pieces=false}
    end
    local composed=(source.category~=Category.armor and helmet_layout or layout).compose(source,target)
    local spans,descriptors={},{}
    for _,body in ipairs(composed.bodies)do
        local raw=table.concat(body.pieces);local allocation,why=allocate(raw);assert(allocation,why)
        spans[#spans+1]=span(allocation.address,raw,#raw)
        descriptors[#descriptors+1]=packed32(body.type)..packed32(0)..packed_pointer(allocation.address)..packed32(#body.pieces)..packed32(0)
    end
    local raw=table.concat(descriptors);local allocation,why=allocate(raw);assert(allocation,why)
    spans[#spans+1]=span(allocation.address,raw,#raw)
    return packed_pointer(allocation.address)..packed32(#descriptors)..packed32(0),spans,composed

end
local function unaffected_kit(raw)
    -- Identity/DLC/set, rarity and category stay native to the carrier.
    -- The three localization hashes belong to the selected appearance.
    return cut(raw,0,Kit.passive)..cut(raw,Kit.passive+4,Kit.bodies)
end
local function appearance_labels(record)
    local reference=record.reference
    assert(type(reference)=='table','verified appearance localization reference required')
    for _,field in ipairs({{'name_upper',Kit.name_upper},{'name_cased',Kit.name_cased},{'description_loc',Kit.description}})do
        assert(integer(reference[field[1]])and u32(record.bytes,field[2])==reference[field[1]],
            'appearance localization fields differ from verified kit reference')
    end
    return cut(record.bytes,Kit.name_upper,Kit.rarity)
end
local function attributable(current, original, intended)
    if type(current)~='string' or #current~=#original then return false end
    for i=1,#current do
        local byte=current:byte(i)
        if byte~=original:byte(i) and byte~=intended:byte(i) then return false end
    end
    return true
end

-- Pure compatibility preflight. It uses immutable catalog evidence and fake
-- addresses solely to validate the layout; it never allocates native memory.
function M.compatible(result,request)
    if result and result.logical_clothing and result.logical_clothing[request.appearance_id]then
        return result.logical_compatible(request)
    end
    local ok,why=pcall(function()
        local wanted=request_copy(request)
        local source=result.records[wanted.appearance_id]
        local stats=result.records['armor:'..(wanted.stats_id:match('^native%-stats:(%x%x%x%x%x%x%x%x)$')or '')]
        assert(source and stats,'Appearance or base stats unavailable')
        record_spans(source,result.category or Category.armor);record_spans(stats,result.category or Category.armor)
        local next_at=0x100000000
        composition(source,stats,function(raw)
            local at=next_at;next_at=next_at+#raw+16;return {address=at}
        end,{})
    end)
    if not ok then return nil,'Armor composition unavailable: '..tostring(why)end
    return true
end

function M.new(bridge)
    assert(type(bridge)=='table' and type(bridge.read)=='function' and type(bridge.write)=='function'
        and type(bridge.verify)=='function','read/write/fresh verification bridge required')
    local self={}
    local plans=setmetatable({}, {__mode='k'})
    local active
    local function read(address,size)
        local value=bridge.read(address,size)
        assert(type(value)=='string' and #value==size,'patch evidence unreadable')
        return value
    end
    local function verify(plan,phase)
        assert(bridge.verify(plan.result,plan.request,plan.source_id,plan.target_id,phase,plan.donors)==true,
            'fresh ownership or compatibility verification failed: '..phase)
    end
    local function check(plan,phase,mode)
        verify(plan,phase)
        for _,observed in ipairs(plan.spans) do
            local value=read(observed.address,observed.size)
            if observed.address==plan.target_address and observed.size==Kit.size then
                if mode=='recover' then
                    assert(unaffected_kit(value)==unaffected_kit(observed.bytes),'target identity changed during recovery')
                else
                    assert(value==(mode=='applied' and plan.applied_bytes or observed.bytes),'target kit evidence changed')
                end
            else assert(value==observed.bytes,'source or body/piece evidence changed') end
        end
    end
    local function evidence(plan,status)
        return {status=status,source_id=plan.source_id,target_id=plan.target_id,
            passive_source_id=plan.passive_source_id,passive_variant_id=plan.request.passive_variant_id,
            appearance_verified=false,numeric_stats_verified=false,
            base_weight_sequence_preserved=plan.weight_evidence.base_weight_sequence_preserved~=false,
            uniform_weight=plan.weight_evidence.uniform_weight,
            appearance_topology_preserved=plan.weight_evidence.appearance_topology_preserved==true,
            slot_weights_preserved=plan.weight_evidence.slot_weights_preserved==true,
            appearance_labels_preserved=true,package_identity_preserved=true,
            passive_bytes_unchanged=plan.passive_unchanged,render_trial=plan.weight_evidence.render_trial==true,
            weight_none=plan.weight_evidence.weight_none,stat_only_pieces=plan.weight_evidence.stat_only_pieces,
            reclassified_pieces=plan.weight_evidence.reclassified_pieces==true}
    end
    local function recover(plan,phase)
        local safe,reason=pcall(check,plan,phase,'recover')
        if not safe then return nil,tostring(reason) end
        local errors={}
        for i=#plan.ranges,1,-1 do
            local range=plan.ranges[i]
            if range.attempted then
                local ok,why=pcall(function()
                    local current=read(range.address,#range.original)
                    if current==range.original then return end
                    verify(plan,phase)
                    assert((range.observed==nil or current==range.observed) and attributable(current,range.original,range.intended),
                        'changed range conflicts with retained evidence')
                    -- Conditional restoration must not overwrite an unrelated
                    -- write that arrived after the failed application.
                    assert(read(range.address,#range.original)==current,'range changed before restoration')
                    local wrote,write_result=pcall(bridge.write,range.address,range.original)
                    local readable,after=pcall(read,range.address,#range.original)
                    if readable and attributable(after,range.original,range.intended) then range.observed=after end
                    assert(wrote and write_result==true and readable and after==range.original,'restoration write/readback failed')
                end)
                if not ok then errors[#errors+1]=tostring(why) end
            end
        end
        local complete,why=pcall(check,plan,phase,'original')
        if not complete then errors[#errors+1]=tostring(why) end
        if #errors>0 then return nil,table.concat(errors,'; ') end
        return true,evidence(plan,'original_memory_restored')
    end
    function self:plan(result,request)
        if active then return nil,'an active patch must be reset before planning another' end
        local ok,handle,plan=pcall(function()
            local wanted=request_copy(request)
            assert(type(result)=='table' and type(result.catalog)=='table' and type(result.owned)=='table'
                and type(result.records)=='table','fresh catalog result required')
            assert(result.capabilities and result.capabilities.kit_records_verified==true
                and result.capabilities.ownership_verified==true,'verified kit records and ownership required')
            local source_id,target_id,passive_id
            local ids={};for id in pairs(result.catalog)do ids[#ids+1]=id end;table.sort(ids)
            for _,id in ipairs(ids)do
                local kit=result.catalog[id]
                if result.owned[id]==true then
                    if kit.appearance_id==wanted.appearance_id then
                        assert(not source_id,'ambiguous appearance donor');source_id=id
                    end
                    if kit.stats_id==wanted.stats_id then
                        assert(not target_id,'ambiguous native stats donor');target_id=id
                    end
                    if kit.passive_variant_id==wanted.passive_variant_id and not passive_id then passive_id=id end
                end
            end
            assert(source_id,'appearance donor is not currently owned')
            assert(target_id,'base stats donor is not currently owned')
            assert(passive_id,'exact passive donor is not currently owned')
            local stats_id=target_id
            target_id=source_id -- Package identity is immutable for the entire process.
            local source,target=result.records[source_id],result.records[target_id]
            local stats=result.records[stats_id]
            local passive=assert(result.records[passive_id],'passive record unavailable')
            local category=result.category or Category.armor
            assert(category==Category.armor or category==Category.helmet and result.capabilities.helmet_transmog_enabled==true
                or category==Category.cape and result.capabilities.cape_transmog_enabled==true,
                'accessory transmog requires observed gameplay differences')
            local source_spans=record_spans(source,category)
            local target_spans=record_spans(stats,category)
            local passive_spans=record_spans(passive,category)
            local labels=appearance_labels(source)
            assert(wanted.stats_id=='native-stats:'..string.format('%08x',stats.item_id),
                'only an identified native stats donor is supported')
            for id,record in pairs(result.records) do
                assert(id==target_id or record.address~=target.address,'target record has an identity alias')
            end
            local spans={}
            for _,list in ipairs({source_spans,target_spans,passive_spans}) do
                for _,observed in ipairs(list) do spans[#spans+1]=observed end
            end
            local donors={source_id,stats_id,passive_id}
            assert(bridge.verify(result,wanted,source_id,target_id,'plan',donors)==true,'fresh donor evidence unavailable')
            assert(type(bridge.allocate)=='function','private variant data allocator unavailable')
            local descriptor,private_spans,weight_evidence
            descriptor,private_spans,weight_evidence=composition(source,stats,bridge.allocate,result.capabilities)
            for _,s in ipairs(private_spans)do spans[#spans+1]=s end
            local passive_bytes=passive.pristine_passive or cut(passive.bytes,Kit.passive,Kit.passive+4)
            local plan={result=result,request=wanted,source_id=source_id,target_id=target_id,donors=donors,
                stats_source_id=stats_id,passive_source_id=passive_id,passive_unchanged=passive_bytes==cut(target.bytes,Kit.passive,Kit.passive+4),
                weight_evidence=weight_evidence,
                target_address=target.address,spans=spans,
                applied_bytes=cut(target.bytes,0,Kit.passive)..passive_bytes..cut(target.bytes,Kit.passive+4,Kit.bodies)..descriptor,ranges={
                    {address=target.address+Kit.passive,original=cut(target.bytes,Kit.passive,Kit.passive+4),intended=passive_bytes},
                    {address=target.address+Kit.bodies,original=cut(target.bytes,Kit.bodies,Kit.size),intended=descriptor},
                }}
            local changed={};for _,r in ipairs(plan.ranges)do if r.original~=r.intended then changed[#changed+1]=r end end;plan.ranges=changed
            for _,range in ipairs(plan.ranges) do
                for _,observed in ipairs(spans) do
                    if observed.address~=target.address then
                        assert(range.address+#range.original<=observed.address or observed.address+observed.size<=range.address,
                            'write range aliases observed data')
                    end
                end
            end
            check(plan,'plan','original')
            return {source_id=source_id,target_id=target_id,stats_source_id=stats_id,passive_source_id=passive_id,request=request_copy(wanted),
                base_weight_sequence_preserved=weight_evidence.base_weight_sequence_preserved~=false,
                uniform_weight=weight_evidence.uniform_weight,
                appearance_topology_preserved=weight_evidence.appearance_topology_preserved==true,
                slot_weights_preserved=weight_evidence.slot_weights_preserved==true,
