  tabs={appearance=true,stats=true,passive=true,presets=true}}
 local listeners={restored={},saved={}}
 function store.listen(event,fn)local list=assert(listeners[event],'unknown store event');list[#list+1]=fn end
 local function tell(event)for _,fn in ipairs(listeners[event])do fn()end end
 local function decode(bytes)
  local tab,payload=bytes:match('^HD2TRANSMOG_UI\t1\n([a-z]+)\n(.*)$')
  if not tab or not store.tabs[tab]then return nil,'Unsupported or corrupt saved state'end
  local restored,why=State.decode(payload)
  if not restored then return nil,why end
  return{tab=tab,domain=restored}
 end
 local ring=State.ring(fs,'transmog.state',decode)
 local function damaged(d)report('state.damaged',State.damaged_line(d))end
 local function heard(event,file,detail)
  if event=='rotate_failed'then report('state.rotate_failed',file..': '..detail)
  elseif event=='damaged'then detail.file=file;damaged(detail)end
