  for _,d in ipairs(outcome.damaged)do
   damaged(d)
   if d.kept==State.EMPTY then empty[#empty+1]=d.file else kept[#kept+1]=d.kept or d.file end
  end
  if #kept>0 then notes[#notes+1]=table.concat(kept,', ')..' kept'end
  if #empty>0 then notes[#notes+1]=table.concat(empty,', ')..(#empty>1 and ' were' or ' was')..' empty'end
  for _,u in ipairs(outcome.unreadable)do
   report('state.unreadable_kept',u.file..': '..u.reason)
   notes[#notes+1]=u.file..' could not be read ('..u.reason..') and is left in place'
  end
