  local count=0;for _ in pairs(store.domain.presets)do count=count+1 end
  if restored then
   local schema=outcome.imported and store.domain.decoded_version or State.FILE_SCHEMA
   report('state.loaded','file='..outcome.from..':schema='..tostring(schema)..':current='..State.FILE_SCHEMA..':variants='..count)
   if outcome.imported then report('state.imported','from='..outcome.from..':schema='..tostring(schema)..':variants='..count)end
  elseif #notes==0 then report('state.load','missing');return end
