  if result.failed[ring.file]then
   notice.set('Saved data not cleared - see problems.txt');report('state.clear_failed',result.failed[ring.file])
   return nil,result.failed[ring.file]
  end
  store.domain=State.new();store.tab='appearance';store.saved=false;store.locked=false;store.recovery=nil
  tell('restored')
  local catalog=k:service('catalog');local catalog_result=catalog and catalog.result
  if catalog_result then store.reconcile(catalog_result)end
  if not store.save()then
   notice.set('Saved data not cleared - the fresh file could not be written')
   report('state.clear_failed','the fresh file could not be written')
   return nil,'the fresh file could not be written'
  end
  notice.set(#failed>0 and 'Saved data cleared with errors - restart the game; see problems.txt' or 'Saved data cleared - restart the game to finish')
