local BootClothing = (function()
-- Stage `clothing`: the clothing owner (the one writer of the reserved
-- records), the lobby link and peer looks, the per-variant looks, the
-- lifecycle packs read, and the preflight that holds the owner back.
--
-- The owner is built the first time the catalog signatures resolve with at
-- least one registered piece; until it exists the catalog read is held.
--
-- Provides:
--   clothing.owner      the owner, once built
--   clothing.control    {step(now), status(), look(), settled(slot),
--                        desire{uuid,toggles}, set(args), clear(args)}
--   clothing.patch      function(native_patch) -> patch through the owner
--   clothing.transport  {step(now), announce(), publish(), inject(arg), link(), peers()}
--   clothing.variants   {ensure(), store(), switch(label,slot), default(label,slot),
--                        restore(slot), save(label), save_rows{label,rows},
--                        forget(label,slot), status()}
--   clothing.health     {report(), status(), instance()}
--   clothing.lifecycle  function() -> {phase, alive, respawns, safe_now}
--   clothing.preview_lease {get(), set(value)}
--   clothing.preview_probe function(args)
--   clothing.worn       function() -> equipment, once the owner is built
--   clothing.hosts      the holder of package leases for packs that keep their
--                       assets on demand, once the owner is built
--   clothing.materials  the applier of the alternative materials a look binds
--                       on unit instances (clothing_materials)
-- Publishes: HD2Transmog.clothing.lifecycle/pool/variant/variants/apply_variant/restore.
local GameCatalog=GameCatalogLayout or error('module is not bundled: src.game.catalog_layout')
local M={name='clothing',requires={'session','catalog'}}
function M.start(k,env)
 local mods,runtime,report=env.modules,env.runtime,env.report
 local fs=k:need('fs')
 local catalog,actor,scene=k:need('catalog'),k:need('actor'),k:need('scene')
 local registry=k:service('clothing.registry')
 local owner,link,peers,remote,hosts
 -- The engine's word on a resource, and the game's package leases: both come
 -- from the game stage, which is where anything about the game is asked.
 local function resources()
  local game=k:service('game')
  return game and type(game.resources)=='function'and game.resources()or nil
 end
 local function present(kind,path)
  local engine_says=resources()
  return engine_says~=nil and engine_says.present(kind,path)
 end
 local function ready()return runtime.clothing~=nil and owner~=nil and owner.phase=='ready'end
 -- Packs that keep their assets on demand (asset ABI 2): the one holder of
 -- package leases. Only a package of one of the game's own kits is ever
 -- leased. It is built with the stage and not with the owner, which waits for
 -- a pack to register: a pack that asks `capabilities().on_demand_assets`
 -- before it registers anything is told the truth.
 if mods.ClothingHosts then
  local kit_packages
  hosts=mods.ClothingHosts.new{report=report,
   packages=function()
    local game=k:service('game')
    if not(game and type(game.packages)=='function')then return nil,'the game stage is not part of this build'end
    return game.packages()
   end,
   known=function(id)
    if not kit_packages then
     kit_packages={}
     for _,kit in pairs(mods.CatalogData.kits)do if type(kit.package)=='string'then kit_packages[kit.package]=true end end
    end
    return kit_packages[id]==true
   end,
   alive=function(id)return owner==nil or owner.standing(id)end}
  k:provide('clothing.hosts',hosts)
  if registry and type(registry.set_on_demand)=='function'then
   -- Asked by packs whenever they like: the game's table is read once a second at most.
   local answered,answer
   registry.set_on_demand(function()
    local now=fs.now()
    if answered==nil or now-answered>=1000 or now<answered then answered,answer=now,hosts:available(now)==true end
    return answer
   end)
  end
 end
 -- The alternative materials a look binds on unit instances: the one applier.
 -- It reaches the engine through the game stage's material port, asked for
 -- each time it works, and is told by the step below what the owner's records
 -- depict. Built with the stage, like the lease holder: a pack that asks
 -- `capabilities().material_selection` before it registers is told the truth.
 local applier
 local function material_port()
  local game=k:service('game')
  return game and type(game.materials)=='function'and game.materials()or nil
 end
 if mods.ClothingMaterials then
  applier=mods.ClothingMaterials.new{port=material_port,report=report}
  k:provide('clothing.materials',applier)
  if registry and type(registry.set_materials)=='function'then
   -- Asked by packs whenever they like: the port is asked for once a second at most.
   local answered,answer
   registry.set_materials(function()
    local now=fs.now()
    if answered==nil or now-answered>=1000 or now<answered then answered,answer=now,material_port()~=nil end
    return answer
   end)
  end
 end
 -- The owner gives every registered piece its record once, when it starts. A
 -- piece registered after that has none this session: said, never silent.
 local housed={late={}}
 local function late_pieces()
  if not housed.pieces then return housed.late end
  local revision=registry.registration_revision()
  if revision==housed.seen then return housed.late end
  housed.seen=revision
  if revision~=housed.revision then
   for _,piece in ipairs(registry.list())do
    if piece.binding and not housed.pieces[piece.id]and not housed.late[piece.id]then
     housed.late[piece.id]=true;report('clothing.registered_late',piece.id)
    end
   end
  end
  return housed.late
 end
 local function armory()return k:service('armory')end
 local function held()return k.busy.held()==true end
 -- The re-stream lease: the one slot whose redraw goes through the local
 -- re-stream under an open Armory.
 local lease={}
 function lease.get()return lease.value end
 function lease.set(value)lease.value=value end
 k:provide('clothing.preview_lease',lease)
 -- Per-variant appearance defaults. An appearance default belongs to a saved
 -- variant, not to the session: applying a variant wipes the current clothing
 -- look and switches to that variant's stored default through the ordinary
 -- desired-state path, and a variant with no default renders the plain native
 -- look.
 local variants,looks={},nil
 local function look_store(quiet)
  if looks then return looks end
  if not runtime.clothing then
   if quiet then return nil end
   error('Clothing API unavailable',0)
  end
  -- A stored look belongs to a saved variant by its id; the slot's own saved
  -- variants say which label that is today.
  local function saved(slot)local a=armory();return a and a.saved_variants(slot)or nil end
  looks=mods.VariantAppearance.new{
   fs=fs,registry=registry,report=report,keep_original=mods.State.keep_original,
   variants={id_of=function(label,slot)
    local domain=saved(slot);local variant=domain and domain.presets[label]
    return variant and variant.id or nil
   end,label_of=function(id,slot)
    local domain=saved(slot);return domain and mods.State.label_of(domain,id)or nil
   end}}
  return looks
 end
 -- Creates the store only; the clothing owner reads defaults from it.
 function variants.ensure()if look_store(true)then return true end end
 function variants.store()return looks end
