  local rows=look_store():defaults(label);local row=rows and slot and rows[slot]or nil
  return row and{uuid=row.uuid,values=row.values}or nil
 end
 function variants.restore(slot)local ok,why=look_store():restore(slot);assert(ok,why);return 'restored '..tostring(slot or 'all')end
 function variants.save(label)local ok,why=look_store():save(label);assert(ok,why);return 'saved '..tostring(label)end
 function variants.save_rows(args)
  local store=look_store()
  assert(type(args)=='table','save_rows needs {label,rows}')
  local ok,why=store:save_rows(args.label,args.rows);assert(ok,why);return 'saved '..tostring(args.label)
 end
