 k:provide('clothing.variants',variants)
 -- Preflight. Every reading is taken here and handed over as plain values, so
 -- the health module itself never touches native memory and never repairs
 -- anything: a mismatch is detected, acted on by refusing, and reported.
 -- Repair belongs to the game -- the operator changes equipment in the Armory,
 -- which commits the profile properly. A reader that cannot read returns nil,
 -- which is `unknown`, which never holds a session; only a reading that was
 -- actually taken and actually disagrees does.
 local preflight
 local function checks()
  if preflight then return preflight end
  preflight=mods.ClothingHealth.new{
   report=report,
   loader=function()
    local value=rawget(_G,'CowboyBingusModLoader')
    if type(value)~='table' then return{present=false}end
    return{present=true,api=tonumber(value.api)}
   end,
   catalog=function()
    local adapter=catalog.adapter
    if not adapter then return nil end
    local out={phase=adapter.phase,failure=adapter.failure}
    if adapter.phase=='ready' then
     -- A resolver that is ready refuses a data bridge only when its own
     -- code proof no longer holds, so a refusal here is an inability to
     -- verify rather than an inability to read, and that is degraded.
     local made,bridge=pcall(adapter.data_bridge,adapter)
     if not made then out.verified=false;out.failure=tostring(bridge)
     elseif type(bridge)=='table' and type(bridge.verify)=='function' then
      local read,value=pcall(bridge.verify)
      if read then out.verified=value==true else out.verified=false end
     end
    end
    return out
   end,
   -- The committed profile buffer and the pending controller buffer.
   -- They only exist in the Armory commit context, so outside the
   -- Armory this is unreadable rather than wrong.
   native_selection=function()
    local a=armory()
