    alternate=function(field,avoid)
     for _,id in ipairs({GameCatalog.login.armor,GameCatalog.restream_alternate})do
      if id~=avoid and not(owner and owner.bound['armor:'..id])then return id end
     end
     return nil
    end}
   restream=function(action)return runner(action,nil,fs.now)end
  end
  owner=mods.ClothingOwner.new{bridge=bridge,writer=mods.RuntimeWriter.new(bridge,nil,k:need('process')),data=mods.CatalogData,
   logical=fs.read('logical-clothing.enabled')=='HD2TM_LOGICAL_CLOTHING 1\n',
