 local function unlinked()return not(link and peers)end
 function transport.step(now)
  if unlinked()then return nil,'lobby link unavailable'end
  local live=ready()
  if live and now>=transport_next then
   transport_next=now+mods.ClothingLink.INTERVAL
   local worn=owner:equipment()
   if worn then
    local state=registry.wire_state();local out={body=state.body}
    for _,slot in ipairs(mods.ClothingWire.SLOTS)do
     local entry=state[slot]
     if entry and worn[slot]=='armor:'..entry.carrier then out[slot]=entry end
    end
    local ok,why=link:set_state(out);if not ok then report('clothing.wire_refused',tostring(why))end
   end
  end
  link:step(now)
