  assert(id and #id==16,'expected: <16-hex steamid> <raw wire value|clear>')
  if raw=='' or raw=='clear' then raw=nil end
  local ok,why=link:inject(id,raw);assert(ok,why);link:republish()
  return 'injected '..id:sub(-6)..(raw and '' or ' (cleared)')
