 k:provide('clothing.transport',transport)
 -- Read-only lifecycle for packs (research/95 §5.3): where the actor is, whether
 -- it is live, how often it came back, and whether a change would apply now.
 local life={respawns=0}
 local function lifecycle()
  local ship=scene.guard()==true
  local probe=actor.peek();local seen=probe and probe:sample()
  local alive=seen~=nil
  if life.alive==false and alive then life.respawns=life.respawns+1 end
  life.alive=alive
  return{phase=ship and 'ship' or(alive and 'mission' or 'loading'),alive=alive,respawns=life.respawns,
   safe_now=alive and seen.settled~=false and not held()}
 end
 k:provide('clothing.lifecycle',lifecycle)
 if runtime.clothing then
  runtime.clothing.lifecycle=function()return lifecycle()end
  -- The reserved records per slot (spec 2026-10-10 §7.2), once the owner
  -- assigned them: {records, homes, free}, counted at the call.
  runtime.clothing.pool=function()
   if not owner or owner.phase~='ready'then return nil,'records not assigned yet'end
   return owner:pool()
  end
  -- Clothing controls for pack behaviours (spec 2026-09-30): the active
  -- variant and its stored default, every stored default, a default put on
  -- as a temporary look, and the active default put back.
  runtime.clothing.variant=function()
   pcall(variants.ensure)
   local store=variants.store();if not store then return{label=nil,default=nil,slots={}}end
   local out={label=store.label,default=nil,slots={}}
   for _,slot in ipairs({'armor','helmet','cape'})do
    local label=store.active[slot];local ok,rows=pcall(store.defaults,store,label)
    local row=ok and rows and rows[slot]or nil
    out.slots[slot]={label=label,default=row}
