  local slot,uuid,pairs_text,mode=tostring(args):match('^(%a+)%s+(%x+)%s*(%S*)%s*(%a*)$')
  assert(slot=='armor'or slot=='helmet'or slot=='cape','expected: <armor|helmet|cape> <uuid> [name=value,...] [restream|preview] | release')
  if(pairs_text=='restream'or pairs_text=='preview')and mode==''then mode=pairs_text;pairs_text=''end
