local BootRefresh = (function()
-- Stage `refresh`: the headless equipment refresh. Equipment changes and
-- forced actor rebuilds outside the Armory go through here: the variant
-- session cannot commit headlessly at all.
--
-- Guards. Scene: the local actor is live -- a main world exists and the
-- customization probe samples it -- which holds on the ship and in a mission
-- alike. The login restore keeps the ship check because it must not touch the
-- actor before the ship has finished loading. Menu: only the Armory equipment
-- screen holds the headless refresh; Options and the MODS tab do not. The
-- Armory blocks for now because it has its own commit path and the profile
-- reconcile on entry: a headless equip underneath an open grid would put the
-- actor and the Armory's committed profile out of step again mid-visit,
-- exactly the state the reconcile exists to repair.
--
-- Provides: refresh {step(now), busy(), redraw(), equip(id, opts),
-- status(arg), call(action, args, opts)}. `call` is the same surface by
-- action name, for the collaborators that are handed one function.
local M={name='refresh',requires={'session','catalog'}}
function M.start(k,env)
 local mods,report=env.modules,env.report
 local fs,engine=k:need('fs'),k:need('engine')
 local catalog,actor=k:need('catalog'),k:need('actor')
 local driver,player
 local function live_actor_scene()
  local ok,world=pcall(engine.Application.main_world)
  if not(ok and world)then return false end
  return player~=nil and player:sample()~=nil
 end
 local function armory_inactive()
  local armory=k:service('armory')
  return not(armory and armory.screen.active==true)
 end
 local function ensure()
  assert(catalog.result and catalog.ready(),'armor catalog is not ready')
  player=player or actor.new()
  if driver then return driver end
  driver=mods.ArmorRefreshDirect.new{
   report=report,
   catalog=function()return catalog.result end,
   player=function()return player:sample()end,
   -- A number a mod that holds the cached armor passive left there is not
   -- what the worn record carries: a variant's passive while one of ours is
   -- composed on it, the record's own otherwise.
   carried_passive=function(id,cached)
    local authority=k:service('equipment.authority')
    if not(authority and authority.accepts('cached_armor_passive',cached))then return nil end
    local armory=k:service('armory')
    local result=catalog.result
    local entry=result.catalog[id]
    local variant_id=armory and type(armory.passive_on)=='function'and armory.passive_on(id)
     or entry and entry.passive_variant_id
    local passive=variant_id and result.context.passive_variants[variant_id]
    return passive and passive.enum or nil
   end,
   new_refresh=function()
    local armory=k:service('armory');local grid=armory and armory.grid()
    if not(grid and grid.phase=='ready')then
     return nil,'native equipment evidence is not ready'
    end
    -- The same no-Armory bridge the startup restoration uses, with
    -- the headless guards above instead of the login ones.
    local bridge,why=grid:player_refresh_bridge(player,catalog.result,
     catalog.bridge(),live_actor_scene,armory_inactive)
    if not bridge then return nil,why end
    return mods.ArmorRefresh.new(bridge,report)
   end}
  return driver
 end
 local refresh={}
 function refresh.busy()return driver~=nil and driver:is_busy()end
 function refresh.step(now)if driver then driver:step(now or fs.now())end end
 function refresh.redraw()
  local d=ensure()
  local ok,why=d:redraw(fs.now());assert(ok,why)
  return 'forced redraw started; '..mods.ArmorRefreshDirect.format(d:status())
 end
 function refresh.equip(id,opts)
  local d=ensure()
  local ok,why=d:equip(id,fs.now(),opts);assert(ok,why)
  return 'headless equip started; '..mods.ArmorRefreshDirect.format(d:status())
 end
 function refresh.status(arg)
  local d=ensure()
  if arg=='recover' then
   local ok,why=d:recover(fs.now());assert(ok,why)
  end
  return mods.ArmorRefreshDirect.format(d:status())
 end
 function refresh.call(action,args,opts)
  if action=='busy'then return refresh.busy()end
  if action=='step'then return refresh.step()end
  if action=='redraw'then return refresh.redraw()end
  if action=='equip'then return refresh.equip(args,opts)end
  if action=='status'then return refresh.status(args)end
  ensure()
  error('expected: redraw | equip <8hex> | status [recover]')
 end
 k:provide('refresh',refresh)
 k.busy.add('refresh',refresh.busy)
 -- Stepped every frame so a started refresh reaches `complete` rather than
 -- stalling after the first commit.
 k:step{phase='pre',name='refresh',order=60,run=function(now)refresh.step(now)end}
 k:command('force_redraw',function()return refresh.redraw()end)
 k:command('force_equip_kit',function(args)
  assert(type(args)=='string' and args:match('^%x%x%x%x%x%x%x%x$'),'Expected an 8-hex armor id')
  return refresh.equip(args)
 end)
 k:command('refresh_status',function(args)
  assert(args==nil or args=='' or args=='recover','Expected no argument or recover')
  return refresh.status(args~='' and args or nil)
 end)
end
return M

end)()
local EquipmentAuthority = (function()
-- Who holds what around equipment. An authority is a named piece of equipment
-- data, or of behaviour around it; it has one holder at a time. We hold
-- `variants` always and `detail_panel` until another mod takes it; the game
-- holds the rest until a mod takes one. While another mod holds an authority
-- we neither write what it covers nor run the behaviour it names.
--
-- A mod takes part under a key (a table it owns) and an id. Every change of a
-- holder is reported through `changed(name, holder or nil, settled)`; nil is
-- the game.
--
-- No game contact, no kernel: who asks and when is the stage's business.
local M={SELF='hd2transmog',MAX_VALUES=8,
 NAMES={variants={ours=true},detail_panel={ours=true,takeable=true},
  accessory_passives={takeable=true},passive_records={takeable=true},
  cached_armor_passive={takeable=true,values=true}}}
local function text(value,max)
 return type(value)=='string'and #value>=1 and #value<=max and not value:find('%c')
end
-- A dense list of 1..MAX_VALUES distinct passive numbers, copied; nil otherwise.
local function numbers(list)
 if type(list)~='table'or #list<1 or #list>M.MAX_VALUES then return nil end
 local count=0;for _ in pairs(list)do count=count+1 end
 if count~=#list then return nil end
 local out,seen={},{}
 for i=1,#list do
  local value=list[i]
  if type(value)~='number'or value%1~=0 or value<0 or value>255 or seen[value]then return nil end
  seen[value]=true;out[i]=value
 end
 return out
end
local function equal(a,b)
 if #a~=#b then return false end
 for i=1,#a do if a[i]~=b[i]then return false end end
 return true
end
function M.new(opts)
 opts=opts or{}
 local report=opts.report or function()end
 local changed=opts.changed or function()end
 local participants,ids,held={},{},{}
 local self={}
 function self.join(key,identity)
  if type(key)~='table'then return nil,'a table key is required'end
  if type(identity)~='table'or not text(identity.id,64)
   or not identity.id:match('^[a-z0-9][a-z0-9_.-]*/[a-z0-9][a-z0-9_.-]*$')then return nil,"id must look like 'author/mod'"end
  if not text(identity.name,64)then return nil,'name must be 1-64 characters'end
  if not text(identity.version,32)then return nil,'version must be 1-32 characters'end
  local known=participants[key]
  if known then
   if known.id==identity.id and known.name==identity.name and known.version==identity.version then return true end
   return nil,'this key has already joined as '..known.id
  end
  if ids[identity.id]then return nil,'id already joined: '..identity.id end
  participants[key]={id=identity.id,name=identity.name,version=identity.version};ids[identity.id]=key
  report('equipment.joined',identity.id..' '..identity.version)
  return true
 end
 function self.take(key,name,options)
  local who=participants[key]
  if not who then return nil,'join before taking an authority'end
  local spec=M.NAMES[name]
  if not spec then return nil,'unknown authority: '..tostring(name)end
  if not spec.takeable then return nil,name..' cannot be taken'end
  if options~=nil and type(options)~='table'then return nil,'options must be a table'end
  options=options or{}
  for option in pairs(options)do
   if option~='settled'and option~='values'then return nil,'unknown option: '..tostring(option)end
  end
  if options.settled~=nil and type(options.settled)~='boolean'then return nil,'settled must be true or false'end
  local values
  if spec.values then
   values=numbers(options.values)
   if not values then return nil,'values must list 1-8 distinct passive numbers'end
  elseif options.values~=nil then return nil,name..' takes no values'end
  local now=held[name]
  if now then
   if now.key~=key then return nil,name..' is held by '..participants[now.key].id end
   if values and not equal(values,now.values)then return nil,'release '..name..' before taking it with other values'end
   -- Taken again as in place, it is in place. A retake never unsettles.
   if not now.settled and options.settled~=false then return self.settle(key,name)end
   return true
  end
  held[name]={key=key,settled=options.settled~=false,values=values}
  report('equipment.taken',name..' '..who.id)
  changed(name,who.id,held[name].settled)
  return true
 end
 function self.settle(key,name)
  local now=held[name]
  if not now or now.key~=key then return nil,tostring(name)..' is not held by this key'end
  if not now.settled then
   now.settled=true;report('equipment.settled',name..' '..participants[key].id)
   changed(name,participants[key].id,true)
  end
  return true
 end
 function self.release(key,name)
  local now=held[name]
  if not now or now.key~=key then return false end
  held[name]=nil;report('equipment.released',name..' '..participants[key].id)
  changed(name,M.NAMES[name].ours and M.SELF or nil,true)
  return true
 end
 -- Who holds it: a participant's id, ours, or nil for the game.
 function self.holder(name)
  local now=held[name]
  if now then return participants[now.key].id,now.settled end
  local spec=M.NAMES[name]
  return spec and spec.ours and M.SELF or nil,true
 end
 function self.elsewhere(name)return held[name]~=nil end
 function self.unsettled(name)local now=held[name];return now~=nil and not now.settled end
 function self.accepts(name,value)
  local now=held[name]
  if not(now and now.values)then return false end
  for i=1,#now.values do if now.values[i]==value then return true end end
  return false
 end
 function self.list()
  local out={}
  for name,spec in pairs(M.NAMES)do
   local now=held[name]
   if now then
    local values
    if now.values then values={};for i=1,#now.values do values[i]=now.values[i]end end
    out[name]={holder=participants[now.key].id,settled=now.settled,values=values}
   elseif spec.ours then out[name]={holder=M.SELF,settled=true}end
  end
  return out
 end
 return self
end
return M

end)()
local EquipmentView = (function()
-- What a record or a card counts as in play, as another mod reads it: the
-- record, the look on it, the passive number that applies and the stock
-- record whose stats it carries. Built from what the catalog and the sessions
-- already know; nothing here reads the game.
local M={SLOTS={'armor','helmet','cape'}}
function M.kit_of(id)
 local hex=type(id)=='string'and id:match('^armor:(%x%x%x%x%x%x%x%x)$')
 return hex and tonumber(hex,16)or nil
end
function M.id_of(kit)return string.format('armor:%08x',kit)end
-- A request names its stats by a stats id or by the record that lends them.
local function stats_record(stats_id)
 local key=type(stats_id)=='string'and stats_id:match('^native%-stats:(%x%x%x%x%x%x%x%x)$')
 return key and'armor:'..key or stats_id
end
local function passive_of(slot_catalog,variant_id)
 local context=type(slot_catalog)=='table'and slot_catalog.context
 local passives=type(context)=='table'and context.passive_variants
 local passive=type(passives)=='table'and variant_id~=nil and passives[variant_id]
 return type(passive)=='table'and type(passive.enum)=='number'and passive.enum or nil
end
-- `variant` is {label, request} when a saved variant is on the record or
-- stands on the card; without one the record counts as itself.
function M.row(id,variant,slot_catalog)
 if type(id)~='string'then return nil end
 local row={id=id,kit=M.kit_of(id),look=id,custom=false}
 local request=type(variant)=='table'and variant.request
 if type(request)=='table'then
  row.custom=true;row.label=variant.label;row.look=request.appearance_id
  row.passive=passive_of(slot_catalog,request.passive_variant_id)
  row.stats_kit=M.kit_of(stats_record(request.stats_id))
 else
  local entry=type(slot_catalog)=='table'and type(slot_catalog.catalog)=='table'and slot_catalog.catalog[id]
  row.passive=type(entry)=='table'and passive_of(slot_catalog,entry.passive_variant_id)or nil
  row.stats_kit=row.kit
 end
 return row
end
