  if options then return true end
  if not runtime.clothing then
   if quiet then return false end
   error('Clothing API unavailable',0)
  end
  options=mods.ClothingOptionsMenu.new{registry=runtime.clothing,report=report,reserved_panels=1,
   -- The piece on the actor, once the owner can say.
   on_piece=function(slot)
    local owner=k:service('clothing.owner');if not owner then return nil end
    return owner:on(slot)
   end}
  transmog=mods.TransmogOptionsMenu.new{report=report,
   -- The saved files set aside and written fresh; the store says how.
   clear_saved=function()
    local store=k:service('store')
    if not(store and store.clear)then return nil,'saved data unavailable'end
    return store.clear()
   end}
  bindings=mods.ClothingBindingsMenu.new{registry=runtime.clothing,report=report,
   refresh=function(action,args,opts)return k:need('refresh').call(action,args,opts)end}
  return true
 end
 local menu={}
 function menu.step(now)
  if not ensure(true)then return end
  -- The option rows mirror state into a settings panel: a quarter
  -- second keeps them current. Bindings are key edges, read each frame.
  now=now or fs.now()
  if not(next_sync and now<next_sync and now>=next_sync-250)then
   next_sync=now+250
