  ensure()
  local text=mods.TransmogOptionsMenu.format_status(transmog:status())
   ..mods.ClothingOptionsMenu.format_status(options:status())
   ..mods.ClothingBindingsMenu.format_status(bindings:status())
  fs.write_atomic('debug-clothing-menu.txt',text)
  return(text:gsub('\n','; '))
 end
 k:provide('clothing.menu',menu)
 k:step{phase='pre',name='menus',order=100,run=function(now)menu.step(now)end}
 k:command('clothing_menu',function()return menu.status()end)
end
return M

end)()
