-- Private archive lifecycle. LLL owns post-update and cleanup polling; a single
-- revocable wrapper preserves the author's pre-update input veto. The original
-- scheduler still owns its render wrapper and removes it by exact identity.
local M={}
function M.new(bootstrap,options)
 options=options or{}
 local get=options.get or function(name)return rawget(_G,name)end
 local set=options.set or function(name,value)rawset(_G,name,value)end
 local current
 local record={live_lua_api=1}
 local function retire(active)
  if not active then return true end
  -- Captured foreign chains may call this wrapper forever. Retirement is
  -- permanent and precedes any native cleanup or ownership handback.
  active.retired=true
  if active.pre and get('update')==active.pre then set('update',active.previous_update)end
  if active.kernel and active.kernel.schedule then active.kernel.schedule:remove()end
 end
 local function cleanup()
  local active=current
  if not active then return true end
  retire(active)
  if active.kernel then
   local ok,done,why=pcall(active.kernel.shutdown,active.kernel)
   if not ok then active.cleanup_error=tostring(done);return false,active.cleanup_error end
   if done==false then active.cleanup_error=why or'kernel cleanup pending';return false,active.cleanup_error end
   if active.kernel.busy and active.kernel.busy.held then
    local checked,busy,owner=pcall(active.kernel.busy.held)
    if not checked then active.cleanup_error=tostring(busy);return false,active.cleanup_error end
    if busy then active.cleanup_error='native cleanup still held: '..tostring(owner);return false,active.cleanup_error end
   end
  end
  if active.public and get('HD2Transmog')==active.public then set('HD2Transmog',nil)end
  active.cleaned=true;active.cleanup_error=nil
  if current==active then current=nil end
  return true
 end
 function record.on_enable()
  if current then
   assert(not current.retired and current.public and get('HD2Transmog')==current.public,'Transmog activation or cleanup is already owned')
   return true
  end
  assert(get('HD2Transmog')==nil,'Another Transmog activation owns HD2Transmog')
  local active={private_callbacks={},retired=false}
  current=active
  -- Capture update/shutdown without installing their legacy wrappers. Render
  -- remains a genuine engine render callback with the author's exact handback.
  active.host={get=function(name)
   if name=='render'then return get(name)end
   return active.private_callbacks[name]
  end,set=function(name,value)
   if name=='render'then set(name,value)else active.private_callbacks[name]=value end
  end}
  local ok,why=pcall(bootstrap,active)
  if not ok then
   active.enable_error=tostring(why);retire(active)
   local done,problem=cleanup()
   error(active.enable_error..(done and''or'; cleanup pending: '..tostring(problem)),0)
  end
  assert(active.kernel and active.kernel.schedule and active.clock,'Incomplete Transmog activation')
  active.previous_update=get('update')
  local previous_update=active.previous_update
  active.pre=function(...)
   if active.retired or current~=active then
    if previous_update then return previous_update(...)end
    return
   end
   local schedule=active.kernel.schedule
   schedule.dt=(...)
   local vetoed=schedule:run('pre',active.clock(),schedule.dt)
   if not active.retired and current==active and vetoed then
    if active.report then pcall(active.report,'update.vetoed',true)end
    return
   end
   -- The previous chain invokes LLL's on_update after its engine update. No
   -- second post phase runs here; its exact return tuple/errors pass through.
   if previous_update then return previous_update(...)end
  end
  set('update',active.pre)
  return true
 end
 function record.on_update(dt)
  local active=current
  if not active or active.retired then return end
  active.kernel.schedule:run('post',active.clock(),dt)
 end
 record.on_disable=cleanup
 record.on_cleanup_poll=cleanup
 function record.port_status()
  local active=current
  if not active then return{active=false,cleaned=true}end
  return{active=not active.retired,retired=active.retired,cleanup_error=active.cleanup_error,
   update_owned=get('update')==active.pre,kernel_started=active.kernel~=nil,
   status=active.runtime and active.runtime.status}
 end
 -- Original archive addons can require the foundation before its discovery
 -- turn. Preserve that ordering: extend ensures this same owned activation;
 -- LLL's later on_enable acknowledges it without starting a second scheduler.
 function record.extend(manifest)
  if not current then record.on_enable()end
  assert(current and not current.retired and current.public,'Transmog is retiring')
  return current.public.extend(manifest)
 end
 return setmetatable(record,{__index=function(_,key)
  local active=current
  return active and not active.retired and active.public and active.public[key]or nil
 end})
end
return M

end)()
