-- What other mods are handed as HD2Transmog: a read-only view of the runtime
-- that shows the documented members and nothing else. A namespace is itself a
-- read-only view, and a table held in one is handed out as a copy, so nothing
-- a caller does can change what the next caller, or the mod itself, gets.
local PUBLIC={version=true,channel=true,build=true,status=true,health=true,extend=true,export_logs=true,
    diverkit_compat=true,clothing='namespace',previews='namespace',appearances='namespace',equipment='namespace'}
local function read_only()error('HD2Transmog is read-only',2)end
local views=setmetatable({},{__mode='k'})
local function view(namespace)
    local seen=views[namespace]
    if seen then return seen end
    seen=setmetatable({},{__newindex=read_only,__metatable=false,__index=function(_,key)
        local value=namespace[key]
        if type(value)~='table' then return value end
        local copy={};for k,v in pairs(value)do copy[k]=v end
        return copy
    end})
    views[namespace]=seen
    return seen
end
local public=setmetatable({},{__newindex=read_only,__metatable=false,__index=function(_,key)
    local kind=PUBLIC[key]
